INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (78, 1, '[{"id": "a2-2-3-5-b1", "t": "table", "imp": "core", "title": "常用主流程序设计语言特性全览", "headers": ["编程语言", "范式类型", "核心技术特性", "典型应用领域"], "rows": [["==C 语言==", "面向过程", "简洁高效、允许直接访问物理硬件与指针操作，跨平台性能天花板", "操作系统内核、嵌入式硬件开发、驱动程序"], ["==C++==", "多范式（面向对象/泛型）", "在 C 语言基础上扩充面向对象类机制、STL 模板库，极致运行性能", "游戏引擎开发、图形图像渲染、底层高性能中间件"], ["==Java==", "纯面向对象", "垃圾自动回收（GC）、强类型安全、跨平台 JVM 虚拟机", "企业级大型分布式系统后台、Android 移动开发"], ["==Python==", "多范式动态脚本语言", "语法极其优雅简洁、库生态极度庞大强大（胶水语言）", "==人工智能与深度学习、大数据分析、科学计算、自动化测试=="], ["==JavaScript==", "基于原型对象的动态脚本", "事件驱动、非阻塞异步 I/O，浏览器端唯一的原生脚本语言", "Web 前端交互开发、Node.js 全栈服务端"]]}, {"id": "a2-2-3-5-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "语言地位考点", "text": "UNIX 操作系统的 90% 以上内核源码是由 ==C 语言==重写的；面向对象编程的三大基石为==封装、继承、多态=="}]'::jsonb, '', 'A2-2.3.5 常用程序设计语言。 常用主流程序设计语言特性全览 编程语言 范式类型 核心技术特性 典型应用领域 C 语言 面向过程 简洁高效、允许直接访问物理硬件与指针操作，跨平台性能天花板 操作系统内核、嵌入式硬件开发、驱动程序 C++ 多范式（面向对象/泛型） 在 C 语言基础上扩充面向对象类机制、STL 模板库，极致运行性能 游戏引擎开发、图形图像渲染、底层高性能中间件 Java 纯面向对象 垃圾自动回收（GC）、强类型安全、跨平台 JVM 虚拟机 企业级大型分布式系统后台、Android 移动开发 Python 多范式动态脚本语言 语法极其优雅简洁、库生态极度庞大强大（胶水语言） 人工智能与深度学习、大数据分析、科学计算、自动化测试 JavaScript 基于原型对象的动态脚本 事件驱动、非阻塞异步 I/O，浏览器端唯一的原生脚本语言 Web 前端交互开发、Node.js 全栈服务端 语言地位考点 UNIX 操作系统的 90% 以上内核源码是由 C 语言重写的；面向对象编程的三大基石为封装、继承、多态', '{"pdf": "理论复习.pdf", "pages": [36]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.4.1 算法的基本概念，算法复杂度的概念和意义（时间复杂度与空间复杂度）。 (node_id=80)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (80, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (80, 1, '[{"id": "a2-2-4-1-b1", "t": "list", "imp": "core", "title": "算法的五大基本特征（必须全部背出，错一不可）", "items": ["==1. 有穷性（Finiteness）==：算法必须在执行有限个步骤之后正常终止，不能陷入无限死循环", "==2. 确定性（Definiteness）==：算法的每一步骤都必须有明确确定无二义性的定义，不能模糊含混", "==3. 可行性（Effectiveness）==：算法中描述的操作都可以通过已经实现的基本运算执行有限次完成", "==4. 输入（Input）==：算法具有==零个或多个输入==（可以没有任何外部输入）", "==5. 输出（Output）==：算法必须具有==一个或多个输出==（没有任何输出的算法毫无实际意义！）"]}, {"id": "a2-2-4-1-b2", "t": "table", "imp": "core", "title": "算法复杂度两大维度：时间复杂度 vs 空间复杂度", "headers": ["复杂度维度", "衡量度量本质", "数学大 O 渐进符号表示法", "常见复杂度排序（从优到劣）"], "rows": [["==时间复杂度 T(n)==", "衡量算法执行所耗费的时间随问题规模 n 增长的渐进增长趋势", "以基本操作重复执行的频度度量，记作 ==O(f(n))==", "==O(1) 常数阶 < O(log n) 对数阶 < O(n) 线性阶 < O(n log n) 线性对数阶 < O(n^2) 平方阶 < O(2^n) 指数阶=="], ["==空间复杂度 S(n)==", "衡量算法在运行过程中所需占用的额外临时辅助存储空间大小", "不包括输入数据本身所占空间，仅计算法运行额外分配的辅助空间", "原地工作的排序算法空间复杂度通常为 ==O(1)=="]]}, {"id": "a2-2-4-1-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "算法输入与输出易错陷阱", "text": "专转本常考单选：==“算法可以有 0 个输入，但必须至少有 1 个输出！”== 如果某选项说“算法必须有至少一个输入”，则该说法必然是错误的。"}]'::jsonb, '', 'A2-2.4.1 算法的基本概念，算法复杂度的概念和意义（时间复杂度与空间复杂度）。 算法的五大基本特征（必须全部背出，错一不可） 1. 有穷性（Finiteness）：算法必须在执行有限个步骤之后正常终止，不能陷入无限死循环 2. 确定性（Definiteness）：算法的每一步骤都必须有明确确定无二义性的定义，不能模糊含混 3. 可行性（Effectiveness）：算法中描述的操作都可以通过已经实现的基本运算执行有限次完成 4. 输入（Input）：算法具有零个或多个输入（可以没有任何外部输入） 5. 输出（Output）：算法必须具有一个或多个输出（没有任何输出的算法毫无实际意义！） 算法复杂度两大维度：时间复杂度 vs 空间复杂度 复杂度维度 衡量度量本质 数学大 O 渐进符号表示法 常见复杂度排序（从优到劣） 时间复杂度 T(n) 衡量算法执行所耗费的时间随问题规模 n 增长的渐进增长趋势 以基本操作重复执行的频度度量，记作 O(f(n)) O(1) 常数阶 < O(log n) 对数阶 < O(n) 线性阶 < O(n log n) 线性对数阶 < O(n^2) 平方阶 < O(2^n) 指数阶 空间复杂度 S(n) 衡量算法在运行过程中所需占用的额外临时辅助存储空间大小 不包括输入数据本身所占空间，仅计算法运行额外分配的辅助空间 原地工作的排序算法空间复杂度通常为 O(1) 算法输入与输出易错陷阱 专转本常考单选：“算法可以有 0 个输入，但必须至少有 1 个输出！” 如果某选项说“算法必须有至少一个输入”，则该说法必然是错误的。', '{"pdf": "理论复习.pdf", "pages": [36, 37]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.4.2 数据结构的定义，数据的逻辑结构与存储结构，数据结构的图形表示，线性结构与非线性结构的概念。 (node_id=81)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (81, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (81, 1, '[{"id": "a2-2-4-2-b1", "t": "p", "imp": "core", "title": "数据结构的核心公式", "text": "计算机科学家沃思（Niklaus Wirth）提出经典名言：==程序 = 数据结构 + 算法==。数据结构是相互之间存在一种或多种特定关系的数据元素的集合。"}, {"id": "a2-2-4-2-b2", "t": "table", "imp": "core", "title": "数据的逻辑结构 vs 存储结构核心对比", "headers": ["结构维度", "定义内涵与视角", "细分类别与典型代表"], "rows": [["==逻辑结构==", "反映数据元素之间的逻辑关系，==完全独立于计算机硬件存储实现==", "==线性结构（一对一，如线性表/栈/队列/串）；非线性结构（树形结构一对多、图形网络多对多）=="], ["==存储结构（物理结构）==", "数据元素及其关系在计算机内存中的具体实际存储表现形式", "==顺序存储结构（数组，连续地址物理相邻）、链式存储结构（指针节点，任意物理地址）、索引存储、散列存储（哈希表）=="]]}, {"id": "a2-2-4-2-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "线性结构判定准则", "text": "线性结构的充要特征：==存在唯一的第一个元素（表头）；存在唯一的最后一个元素（表尾）；除第一个元素外每个元素有且仅有一个直接前驱；除最后一个元素外每个元素有且仅有一个直接后继==。"}]'::jsonb, '', 'A2-2.4.2 数据结构的定义，数据的逻辑结构与存储结构，数据结构的图形表示，线性结构与非线性结构的概念。 数据结构的核心公式 计算机科学家沃思（Niklaus Wirth）提出经典名言：程序 = 数据结构 + 算法。数据结构是相互之间存在一种或多种特定关系的数据元素的集合。 数据的逻辑结构 vs 存储结构核心对比 结构维度 定义内涵与视角 细分类别与典型代表 逻辑结构 反映数据元素之间的逻辑关系，完全独立于计算机硬件存储实现 线性结构（一对一，如线性表/栈/队列/串）；非线性结构（树形结构一对多、图形网络多对多） 存储结构（物理结构） 数据元素及其关系在计算机内存中的具体实际存储表现形式 顺序存储结构（数组，连续地址物理相邻）、链式存储结构（指针节点，任意物理地址）、索引存储、散列存储（哈希表） 线性结构判定准则 线性结构的充要特征：存在唯一的第一个元素（表头）；存在唯一的最后一个元素（表尾）；除第一个元素外每个元素有且仅有一个直接前驱；除最后一个元素外每个元素有且仅有一个直接后继。', '{"pdf": "理论复习.pdf", "pages": [37, 38]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.4.3 线性表的定义，线性表的顺序存储结构及其插入与删除运算。 (node_id=82)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (82, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (82, 1, '[{"id": "a2-2-4-3-b1", "t": "table", "imp": "core", "title": "顺序表（顺序存储）的插入与删除算法分析", "headers": ["操作类型", "操作动作过程", "元素移动平均次数公式", "时间复杂度"], "rows": [["==插入操作==", "在第 i（1 ≤ i ≤ n+1）个位置插入新元素，==必须将第 i 到第 n 个元素全部向后移动 1 个位置==", "在等概率情况下，平均移动元素次数为 ==n / 2==", "最好 O(1)（表尾插入），最坏 O(n)，平均 ==O(n)=="], ["==删除操作==", "删除第 i（1 ≤ i ≤ n）个元素，==必须将第 i+1 到第 n 个元素全部向前移动 1 个位置==", "在等概率情况下，平均移动元素次数为 ==(n - 1) / 2==", "最好 O(1)（表尾删除），最坏 O(n)，平均 ==O(n)=="]]}, {"id": "a2-2-4-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "顺序表随机存取特性", "text": "==顺序表最大的优点是支持随机存取（按数组下标可以在 O(1) 时间内直接定位任意第 i 个元素）==；主要缺点是插入和删除需要移动大量数据元素，且需要预先分配固定大小的连续内存块。"}]'::jsonb, '', 'A2-2.4.3 线性表的定义，线性表的顺序存储结构及其插入与删除运算。 顺序表（顺序存储）的插入与删除算法分析 操作类型 操作动作过程 元素移动平均次数公式 时间复杂度 插入操作 在第 i（1 ≤ i ≤ n+1）个位置插入新元素，必须将第 i 到第 n 个元素全部向后移动 1 个位置 在等概率情况下，平均移动元素次数为 n / 2 最好 O(1)（表尾插入），最坏 O(n)，平均 O(n) 删除操作 删除第 i（1 ≤ i ≤ n）个元素，必须将第 i+1 到第 n 个元素全部向前移动 1 个位置 在等概率情况下，平均移动元素次数为 (n - 1) / 2 最好 O(1)（表尾删除），最坏 O(n)，平均 O(n) 顺序表随机存取特性 顺序表最大的优点是支持随机存取（按数组下标可以在 O(1) 时间内直接定位任意第 i 个元素）；主要缺点是插入和删除需要移动大量数据元素，且需要预先分配固定大小的连续内存块。', '{"pdf": "理论复习.pdf", "pages": [38, 39]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.4.4 栈和队列的定义，栈和队列的顺序存储结构及其基本运算。 (node_id=83)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (83, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (83, 1, '[{"id": "a2-2-4-4-b1", "t": "table", "imp": "core", "title": "栈（Stack） vs 队列（Queue）核心操作对比（专转本高频大题）", "headers": ["操作受限线性表", "英文名称", "操作规则原则", "允许操作的一端", "经典应用场景"], "rows": [["==栈==", "Stack", "==后进先出（LIFO，Last In First Out）==", "==所有的插入（入栈 Push）和删除（出栈 Pop）操作只能在“栈顶（Top）”进行==", "==函数递归调用、括号匹配、表达式求值、浏览器后退历史=="], ["==队列==", "Queue", "==先进先出（FIFO，First In First Out）==", "==只允许在“队尾（Rear）”插入（入队），在“队头（Front）”删除（出队）==", "==打印机任务排队缓冲、操作系统 CPU 进程就绪队列、广度优先搜索（BFS）=="]]}, {"id": "a2-2-4-4-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "循环队列假溢出与队满判定", "text": "为解决顺序队列的“假溢出”问题，通常采用循环队列（利用求模运算取余 `% MaxSize`）。\n常见牺牲一个存储单元以区分队空队满：\n• ==队空条件：`front == rear`==；\n• ==队满条件：`(rear + 1) % MaxSize == front`==；\n• 队列中当前元素个数：`(rear - front + MaxSize) % MaxSize`。"}]'::jsonb, '', 'A2-2.4.4 栈和队列的定义，栈和队列的顺序存储结构及其基本运算。 栈（Stack） vs 队列（Queue）核心操作对比（专转本高频大题） 操作受限线性表 英文名称 操作规则原则 允许操作的一端 经典应用场景 栈 Stack 后进先出（LIFO，Last In First Out） 所有的插入（入栈 Push）和删除（出栈 Pop）操作只能在“栈顶（Top）”进行 函数递归调用、括号匹配、表达式求值、浏览器后退历史 队列 Queue 先进先出（FIFO，First In First Out） 只允许在“队尾（Rear）”插入（入队），在“队头（Front）”删除（出队） 打印机任务排队缓冲、操作系统 CPU 进程就绪队列、广度优先搜索（BFS） 循环队列假溢出与队满判定 为解决顺序队列的“假溢出”问题，通常采用循环队列（利用求模运算取余 % MaxSize）。
常见牺牲一个存储单元以区分队空队满：
• 队空条件：front  rear；
• 队满条件：(rear + 1) % MaxSize  front；
• 队列中当前元素个数：(rear - front + MaxSize) % MaxSize。', '{"pdf": "理论复习.pdf", "pages": [39, 40]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.4.5 线性单链表、双向链表与循环链表的结构及其基本运算。 (node_id=84)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (84, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (84, 1, '[{"id": "a2-2-4-5-b1", "t": "table", "imp": "core", "title": "链表结构核心特性对比（单链表 / 循环链表 / 双向链表）", "headers": ["链表结构类型", "节点结构指针域", "首尾闭合判定", "优缺点与操作特性"], "rows": [["==单链表==", "包含数据域 `data` + 单个后继指针域 `next`", "尾节点的 `next` 指针固定为 `NULL`", "==插入和删除已知节点指针时时间复杂度为 O(1)==（只需修改指针，无需移动数据）；不支持随机访问，查表需从头 O(n) 遍历"], ["==循环单链表==", "结构同单链表", "==尾节点的 `next` 指向头节点==，形成环状闭合回路", "从表中任意一个节点出发均能遍历访问到整张链表的所有元素"], ["==双向链表==", "包含数据域 `data` + 前驱指针 `prior` + 后继指针 `next`", "双向互通", "支持直接向前向后双向检索遍历，但每个节点需额外存储一个指针空间"]]}, {"id": "a2-2-4-5-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "单链表中头节点（Head Node）的作用", "text": "在单链表第一个有效数据节点之前增设一个头节点的好处：==使在链表第一个位置（表头）的插入和删除操作与在其他位置的操作统一，无需做特殊判断分支；空表与非空表处理逻辑一致=="}]'::jsonb, '', 'A2-2.4.5 线性单链表、双向链表与循环链表的结构及其基本运算。 链表结构核心特性对比（单链表 / 循环链表 / 双向链表） 链表结构类型 节点结构指针域 首尾闭合判定 优缺点与操作特性 单链表 包含数据域 data + 单个后继指针域 next 尾节点的 next 指针固定为 NULL 插入和删除已知节点指针时时间复杂度为 O(1)（只需修改指针，无需移动数据）；不支持随机访问，查表需从头 O(n) 遍历 循环单链表 结构同单链表 尾节点的 next 指向头节点，形成环状闭合回路 从表中任意一个节点出发均能遍历访问到整张链表的所有元素 双向链表 包含数据域 data + 前驱指针 prior + 后继指针 next 双向互通 支持直接向前向后双向检索遍历，但每个节点需额外存储一个指针空间 单链表中头节点（Head Node）的作用 在单链表第一个有效数据节点之前增设一个头节点的好处：使在链表第一个位置（表头）的插入和删除操作与在其他位置的操作统一，无需做特殊判断分支；空表与非空表处理逻辑一致', '{"pdf": "理论复习.pdf", "pages": [40, 41]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.4.6 树的基本概念，二叉树的定义及其存储结构，二叉树的前序、中序和后序遍历。 (node_id=85)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (85, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (85, 1, '[{"id": "a2-2-4-6-b1", "t": "table", "imp": "core", "title": "二叉树四大核心数学性质（专转本每年必考计算题）", "headers": ["性质序号", "性质内容公式", "应用推导与经典结论"], "rows": [["==性质 1==", "在二叉树的第 i 层上，至多有 ==2^(i-1) 个节点==（i ≥ 1）", "第 1 层至多 1 个，第 2 层至多 2 个，第 3 层至多 4 个"], ["==性质 2==", "深度为 k 的二叉树，至多有 ==2^k - 1 个节点==（k ≥ 1）", "深度为 3 的二叉树至多 7 个节点，深度为 4 至多 15 个节点"], ["==性质 3（最核心公式）==", "==在任意一棵二叉树中，若叶子节点数（度为0）为 n0，度为 2 的节点数为 n2，则必有：n0 = n2 + 1==", "【例】：若某二叉树中度为 2 的节点有 10 个，则其叶子节点数必为 ==11 个=="], ["性质 4", "具有 n 个节点的完全二叉树的深度为 ==⌊log2 n⌋ + 1==", "衡量完全二叉树的高度"]]}, {"id": "a2-2-4-6-b2", "t": "table", "imp": "core", "title": "二叉树三大遍历次序规则与算例", "headers": ["遍历方式", "遍历访问顺序规则", "根节点的访问位置"], "rows": [["==前序遍历（先序，Pre-order）==", "==根节点 -> 左子树 -> 右子树（根左右）==", "==最先访问根节点=="], ["==中序遍历（In-order）==", "==左子树 -> 根节点 -> 右子树（左根右）==", "==中间访问根节点=="], ["==后序遍历（Post-order）==", "==左子树 -> 右子树 -> 根节点（左右根）==", "==最后访问根节点=="]]}, {"id": "a2-2-4-6-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "根据遍历序列还原二叉树规律", "text": "专转本必考题型：==给出中序遍历 + 前序遍历（或后序遍历），可以唯一确定一棵二叉树==；【方法】：从前序的最前（或后序的最后）找出根节点，然后在中序遍历序列中以此根为中心，左边全属于左子树，右边全属于右子树，递归还原。\n注意：==单独给出“前序 + 后序”无法唯一确定一棵二叉树！=="}]'::jsonb, '', 'A2-2.4.6 树的基本概念，二叉树的定义及其存储结构，二叉树的前序、中序和后序遍历。 二叉树四大核心数学性质（专转本每年必考计算题） 性质序号 性质内容公式 应用推导与经典结论 性质 1 在二叉树的第 i 层上，至多有 2^(i-1) 个节点（i ≥ 1） 第 1 层至多 1 个，第 2 层至多 2 个，第 3 层至多 4 个 性质 2 深度为 k 的二叉树，至多有 2^k - 1 个节点（k ≥ 1） 深度为 3 的二叉树至多 7 个节点，深度为 4 至多 15 个节点 性质 3（最核心公式） 在任意一棵二叉树中，若叶子节点数（度为0）为 n0，度为 2 的节点数为 n2，则必有：n0 = n2 + 1 【例】：若某二叉树中度为 2 的节点有 10 个，则其叶子节点数必为 11 个 性质 4 具有 n 个节点的完全二叉树的深度为 ⌊log2 n⌋ + 1 衡量完全二叉树的高度 二叉树三大遍历次序规则与算例 遍历方式 遍历访问顺序规则 根节点的访问位置 前序遍历（先序，Pre-order） 根节点 -> 左子树 -> 右子树（根左右） 最先访问根节点 中序遍历（In-order） 左子树 -> 根节点 -> 右子树（左根右） 中间访问根节点 后序遍历（Post-order） 左子树 -> 右子树 -> 根节点（左右根） 最后访问根节点 根据遍历序列还原二叉树规律 专转本必考题型：给出中序遍历 + 前序遍历（或后序遍历），可以唯一确定一棵二叉树；【方法】：从前序的最前（或后序的最后）找出根节点，然后在中序遍历序列中以此根为中心，左边全属于左子树，右边全属于右子树，递归还原。
注意：单独给出“前序 + 后序”无法唯一确定一棵二叉树！', '{"pdf": "理论复习.pdf", "pages": [41, 42, 43, 44]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.5.1 软件工程基本概念与生命周期。 (node_id=87)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (87, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (87, 1, '[{"id": "a2-2-5-1-b1", "t": "p", "imp": "core", "title": "软件危机的产生与软件工程定义", "text": "==软件危机（Software Crisis）==是指在计算机软件的开发和维护过程中所遇到的一系列严重问题（软件开发成本超支、进度严重滞后、软件质量不可靠、维护困难等）。为了消除软件危机，1968 年在 NATO 会议上正式提出==软件工程（Software Engineering）==概念：采用工程化的原理、方法和技术来指导和规范软件的开发与维护。"}, {"id": "a2-2-5-1-b2", "t": "table", "imp": "core", "title": "软件工程三要素与经典瀑布生命周期各阶段", "headers": ["生命周期阶段", "主要交付成果（文档）", "核心任务"], "rows": [["==1. 问题定义与可行性研究==", "《可行性研究报告》", "论证技术可行性、经济可行性和操作可行性，决定是否立项开发"], ["==2. 需求分析==", "==《软件需求规格说明书（SRS）》==", "==确定系统“做什么”（What to do），建立数据流图（DFD）与数据字典（DD）=="], ["==3. 总体设计（概要设计）==", "《总体设计说明书》", "确定系统体系架构、划分功能模块、数据库概念结构设计（E-R图）"], ["==4. 详细设计==", "《详细设计说明书》", "设计每个模块内部的具体执行算法和逻辑流程（PAD图、N-S盒图）"], ["==5. 编码与单元测试==", "源程序代码", "选用合适的编程语言将设计逻辑转化为可执行代码"], ["==6. 综合测试==", "《软件测试报告》", "通过黑盒与白盒测试发现并纠正错误，确认是否满足需求"], ["==7. 运行与维护==", "维护记录", "==软件生命周期中耗时最长、成本开销最大（占 60%~80%）的阶段=="]]}]'::jsonb, '', 'A2-2.5.1 软件工程基本概念与生命周期。 软件危机的产生与软件工程定义 软件危机（Software Crisis）是指在计算机软件的开发和维护过程中所遇到的一系列严重问题（软件开发成本超支、进度严重滞后、软件质量不可靠、维护困难等）。为了消除软件危机，1968 年在 NATO 会议上正式提出软件工程（Software Engineering）概念：采用工程化的原理、方法和技术来指导和规范软件的开发与维护。 软件工程三要素与经典瀑布生命周期各阶段 生命周期阶段 主要交付成果（文档） 核心任务 1. 问题定义与可行性研究 《可行性研究报告》 论证技术可行性、经济可行性和操作可行性，决定是否立项开发 2. 需求分析 《软件需求规格说明书（SRS）》 确定系统“做什么”（What to do），建立数据流图（DFD）与数据字典（DD） 3. 总体设计（概要设计） 《总体设计说明书》 确定系统体系架构、划分功能模块、数据库概念结构设计（E-R图） 4. 详细设计 《详细设计说明书》 设计每个模块内部的具体执行算法和逻辑流程（PAD图、N-S盒图） 5. 编码与单元测试 源程序代码 选用合适的编程语言将设计逻辑转化为可执行代码 6. 综合测试 《软件测试报告》 通过黑盒与白盒测试发现并纠正错误，确认是否满足需求 7. 运行与维护 维护记录 软件生命周期中耗时最长、成本开销最大（占 60%~80%）的阶段', '{"pdf": "理论复习.pdf", "pages": [44, 45]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.5.2 结构化设计方法，总体设计与详细设计。 (node_id=88)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (88, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (88, 1, '[{"id": "a2-2-5-2-b1", "t": "table", "imp": "core", "title": "模块独立性两大衡量准则：内聚性 vs 耦合性（必须死记硬背）", "headers": ["衡量准则", "定义概念与设计目标", "强弱级别排列（从强到弱 / 从好到差）"], "rows": [["==内聚性（Cohesion）==", "衡量一个模块内部各元素之间联系紧密程度的度量，==追求“高内聚”==", "==功能内聚（最高/最好） > 顺序内聚 > 通信内聚 > 过程内聚 > 时间内聚 > 逻辑内聚 > 偶然内聚（最低/最差）=="], ["==耦合性（Coupling）==", "衡量不同模块之间相互依赖和相互调用程度的度量，==追求“低耦合”==", "==无直接耦合（最好） < 数据耦合（较好） < 标记耦合 < 控制耦合 < 公共耦合 < 内容耦合（最高/最差）=="]]}, {"id": "a2-2-5-2-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "模块化设计的黄金法则", "text": "专转本必考口诀：==“高内聚，低耦合”==！优秀的软件架构必须尽量做到模块内部功能高度专一单一（高内聚），而模块与模块之间的接口参数传递尽量简单松散（低耦合），严禁出现内容耦合！"}]'::jsonb, '', 'A2-2.5.2 结构化设计方法，总体设计与详细设计。 模块独立性两大衡量准则：内聚性 vs 耦合性（必须死记硬背） 衡量准则 定义概念与设计目标 强弱级别排列（从强到弱 / 从好到差） 内聚性（Cohesion） 衡量一个模块内部各元素之间联系紧密程度的度量，追求“高内聚” 功能内聚（最高/最好） > 顺序内聚 > 通信内聚 > 过程内聚 > 时间内聚 > 逻辑内聚 > 偶然内聚（最低/最差） 耦合性（Coupling） 衡量不同模块之间相互依赖和相互调用程度的度量，追求“低耦合” 无直接耦合（最好） < 数据耦合（较好） < 标记耦合 < 控制耦合 < 公共耦合 < 内容耦合（最高/最差） 模块化设计的黄金法则 专转本必考口诀：“高内聚，低耦合”！优秀的软件架构必须尽量做到模块内部功能高度专一单一（高内聚），而模块与模块之间的接口参数传递尽量简单松散（低耦合），严禁出现内容耦合！', '{"pdf": "理论复习.pdf", "pages": [45, 46]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.5.3 面向对象分析与设计：OOD，UML 图。 (node_id=89)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (89, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (89, 1, '[{"id": "a2-2-5-3-b1", "t": "table", "imp": "core", "title": "面向对象三大基本特征与核心概念", "headers": ["面向对象特征", "核心内涵解释", "软件工程带来的价值"], "rows": [["==对象（Object）==", "现实世界实体的软件映射，由属性（数据）和方法（操作行为）封装而成", "系统的基本运行实体"], ["==类（Class）==", "对一组具有相同属性和相同行为的对象的抽象模板", "对象是类的实例化具体表现"], ["==封装（Encapsulation）==", "隐藏对象的内部实现细节，仅对外暴露有限公共接口", "提高安全性和易用性"], ["==继承（Inheritance）==", "子类自动拥有父类的全部属性和方法，并可扩充重载新特性", "==实现代码的高度复用与层次化抽象=="], ["==多态（Polymorphism）==", "同一消息发给不同类的对象可以产生完全不同的执行行为", "提高软件的灵活性与可扩展性"]]}, {"id": "a2-2-5-3-b2", "t": "table", "imp": "core", "title": "UML 统一建模语言常用图分类全览", "headers": ["UML 图分类", "具体图名称", "主要展示视角与功能"], "rows": [["需求分析视角", "==用例图（Use Case Diagram）==", "展现外部参与者（Actor）与系统用例之间的关系，界定系统功能边界"], ["静态结构视角", "==类图（Class Diagram）==", "展现类之间的继承泛化、实现、关联、聚合、组合与依赖关系"], ["动态行为视角", "==顺序图 / 时序图（Sequence Diagram）==", "按时间顺序展现对象之间发送消息与交互的生命线流程"], ["动态行为视角", "==状态图（Statechart Diagram）==", "展现一个对象由于外部事件触发而在各种生命周期状态间的转移"], ["动态行为视角", "活动图（Activity Diagram）", "展现业务流程中的工作流动作、并行分支与合并"], ["物理架构视角", "组件图与部署图（Deployment Diagram）", "展现软件组件打包及在物理硬件服务器节点上的分布拓扑"]]}]'::jsonb, '', 'A2-2.5.3 面向对象分析与设计：OOD，UML 图。 面向对象三大基本特征与核心概念 面向对象特征 核心内涵解释 软件工程带来的价值 对象（Object） 现实世界实体的软件映射，由属性（数据）和方法（操作行为）封装而成 系统的基本运行实体 类（Class） 对一组具有相同属性和相同行为的对象的抽象模板 对象是类的实例化具体表现 封装（Encapsulation） 隐藏对象的内部实现细节，仅对外暴露有限公共接口 提高安全性和易用性 继承（Inheritance） 子类自动拥有父类的全部属性和方法，并可扩充重载新特性 实现代码的高度复用与层次化抽象 多态（Polymorphism） 同一消息发给不同类的对象可以产生完全不同的执行行为 提高软件的灵活性与可扩展性 UML 统一建模语言常用图分类全览 UML 图分类 具体图名称 主要展示视角与功能 需求分析视角 用例图（Use Case Diagram） 展现外部参与者（Actor）与系统用例之间的关系，界定系统功能边界 静态结构视角 类图（Class Diagram） 展现类之间的继承泛化、实现、关联、聚合、组合与依赖关系 动态行为视角 顺序图 / 时序图（Sequence Diagram） 按时间顺序展现对象之间发送消息与交互的生命线流程 动态行为视角 状态图（Statechart Diagram） 展现一个对象由于外部事件触发而在各种生命周期状态间的转移 动态行为视角 活动图（Activity Diagram） 展现业务流程中的工作流动作、并行分支与合并 物理架构视角 组件图与部署图（Deployment Diagram） 展现软件组件打包及在物理硬件服务器节点上的分布拓扑', '{"pdf": "理论复习.pdf", "pages": [46, 47]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.5.4 软件测试的方法，白盒测试与黑盒测试。 (node_id=90)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (90, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (90, 1, '[{"id": "a2-2-5-4-b1", "t": "table", "imp": "core", "title": "黑盒测试 vs 白盒测试核心对比（专转本每考必出大题）", "headers": ["对比项", "==黑盒测试（功能测试）==", "==白盒测试（结构测试 / 逻辑驱动）=="], "rows": [["==测试视角==", "==把程序看作一个看不见内部结构的黑盒子，完全不考虑程序内部逻辑结构==", "==清晰看清程序内部代码逻辑、执行路径和分支条件=="], ["==测试依据==", "依据《软件需求规格说明书》，检查输入与输出是否符合预期功能", "依据程序内部算法源代码结构设计测试用例"], ["==常用测试方法与用例设计技术==", "==等价类划分法（有效/无效等价类）、边界值分析法（最容易暴露错误）、错误推测法、因果图法==", "==逻辑覆盖测试（语句覆盖、判定覆盖、条件覆盖、判定/条件覆盖、条件组合覆盖、路径覆盖）=="], ["测试执行阶段", "主要用于集成测试、系统测试与验收测试", "主要用于单元测试（Unit Test）"]]}, {"id": "a2-2-5-4-b2", "t": "table", "imp": "core", "title": "白盒测试逻辑覆盖强度层级（从弱到强排列）", "headers": ["逻辑覆盖标准", "测试用例必须达到的覆盖要求", "覆盖强度评价"], "rows": [["==1. 语句覆盖==", "程序中每一条可执行语句至少被执行一次", "==覆盖能力最弱，无法发现分支判断逻辑错误=="], ["==2. 判定覆盖（分支覆盖）==", "每个判断语句的真（True）分支和假（False）分支至少各走一次", "弱于条件覆盖"], ["==3. 条件覆盖==", "每个判断语句中每个逻辑条件的各种可能取值（真/假）至少满足一次", "不能保证所有判定分支都被覆盖"], ["==4. 判定/条件覆盖==", "同时满足判定覆盖和条件覆盖", "综合二者"], ["==5. 条件组合覆盖==", "每个判断语句中所有条件的各种可能取值的组合至少出现一次", "强逻辑覆盖"], ["==6. 路径覆盖==", "覆盖程序控制流图中所有可能的从入口到出口的执行路径", "==覆盖能力最强，但当程序有循环时可能产生路径爆炸=="]]}]'::jsonb, '', 'A2-2.5.4 软件测试的方法，白盒测试与黑盒测试。 黑盒测试 vs 白盒测试核心对比（专转本每考必出大题） 对比项 黑盒测试（功能测试） 白盒测试（结构测试 / 逻辑驱动） 测试视角 把程序看作一个看不见内部结构的黑盒子，完全不考虑程序内部逻辑结构 清晰看清程序内部代码逻辑、执行路径和分支条件 测试依据 依据《软件需求规格说明书》，检查输入与输出是否符合预期功能 依据程序内部算法源代码结构设计测试用例 常用测试方法与用例设计技术 等价类划分法（有效/无效等价类）、边界值分析法（最容易暴露错误）、错误推测法、因果图法 逻辑覆盖测试（语句覆盖、判定覆盖、条件覆盖、判定/条件覆盖、条件组合覆盖、路径覆盖） 测试执行阶段 主要用于集成测试、系统测试与验收测试 主要用于单元测试（Unit Test） 白盒测试逻辑覆盖强度层级（从弱到强排列） 逻辑覆盖标准 测试用例必须达到的覆盖要求 覆盖强度评价 1. 语句覆盖 程序中每一条可执行语句至少被执行一次 覆盖能力最弱，无法发现分支判断逻辑错误 2. 判定覆盖（分支覆盖） 每个判断语句的真（True）分支和假（False）分支至少各走一次 弱于条件覆盖 3. 条件覆盖 每个判断语句中每个逻辑条件的各种可能取值（真/假）至少满足一次 不能保证所有判定分支都被覆盖 4. 判定/条件覆盖 同时满足判定覆盖和条件覆盖 综合二者 5. 条件组合覆盖 每个判断语句中所有条件的各种可能取值的组合至少出现一次 强逻辑覆盖 6. 路径覆盖 覆盖程序控制流图中所有可能的从入口到出口的执行路径 覆盖能力最强，但当程序有循环时可能产生路径爆炸', '{"pdf": "理论复习.pdf", "pages": [47, 48]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A2-2.5.5 程序的调试，静态调试与动态调试。 (node_id=91)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (91, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (91, 1, '[{"id": "a2-2-5-5-b1", "t": "table", "imp": "core", "title": "软件测试（Testing） vs 软件调试（Debugging）本质区别（必考概念题）", "headers": ["对比项", "==软件测试（Testing）==", "==软件调试（Debugging）=="], "rows": [["==核心目的==", "==发现程序中存在的潜在错误和缺陷==", "==定位错误发生的根本根源并纠正排除错误（Bug）=="], ["==工作执行人==", "主要由独立的专业软件测试工程师执行", "主要由负责编写该代码的原程序员执行"], ["==结果与状态==", "测试从已知条件开始，展示错误症状", "调试从未知原因开始，推断、假设并修改代码修复故障"], ["==阶段时序关系==", "测试先于调试进行", "==测试发现了错误之后，才启动调试排错=="]]}, {"id": "a2-2-5-5-b2", "t": "table", "imp": "core", "title": "静态调试 vs 动态调试方法对比", "headers": ["调试方法类别", "执行机制与方式", "常用手段与工具"], "rows": [["==静态调试==", "==不实际在计算机上运行程序代码==，依靠人工目视或静态代码扫描工具审查代码", "代码走查（Walkthrough）、同行评审、静态规则扫描（SonarQube、Linter）"], ["==动态调试==", "==在计算机上实际加载并运行程序==，通过动态监控程序运行时状态排查错误", "设置断点（Breakpoint）、单步跟踪（Step Over/Into）、内存变量监视、打印调试日志（Log）"]]}]'::jsonb, '', 'A2-2.5.5 程序的调试，静态调试与动态调试。 软件测试（Testing） vs 软件调试（Debugging）本质区别（必考概念题） 对比项 软件测试（Testing） 软件调试（Debugging） 核心目的 发现程序中存在的潜在错误和缺陷 定位错误发生的根本根源并纠正排除错误（Bug） 工作执行人 主要由独立的专业软件测试工程师执行 主要由负责编写该代码的原程序员执行 结果与状态 测试从已知条件开始，展示错误症状 调试从未知原因开始，推断、假设并修改代码修复故障 阶段时序关系 测试先于调试进行 测试发现了错误之后，才启动调试排错 静态调试 vs 动态调试方法对比 调试方法类别 执行机制与方式 常用手段与工具 静态调试 不实际在计算机上运行程序代码，依靠人工目视或静态代码扫描工具审查代码 代码走查（Walkthrough）、同行评审、静态规则扫描（SonarQube、Linter） 动态调试 在计算机上实际加载并运行程序，通过动态监控程序运行时状态排查错误 设置断点（Breakpoint）、单步跟踪（Step Over/Into）、内存变量监视、打印调试日志（Log）', '{"pdf": "理论复习.pdf", "pages": [48]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.1.1 计算机网络的定义、组成和分类。 (node_id=93)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (93, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (93, 1, '[{"id": "a3-3-1-1-b1", "t": "p", "imp": "core", "title": "计算机网络的定义与三大核心功能", "text": "==计算机网络（Computer Network）==是指将地理位置分散的、具有独立功能的计算机系统，通过通信设备和传输线路连接起来，在网络操作系统和通信协议的管理下，实现==资源共享（硬件、软件、数据）、信息传输和协同分布式处理==的系统。"}, {"id": "a3-3-1-1-b2", "t": "table", "imp": "core", "title": "按覆盖地理范围分类（LAN / MAN / WAN / PAN）", "headers": ["网络分类", "英文全称", "覆盖地理范围", "典型特征与代表"], "rows": [["==个人区域网==", "==PAN（Personal Area Network）==", "10 米以内", "基于低功耗蓝牙、UWB 等个人便携随身设备互联"], ["==局域网==", "==LAN（Local Area Network）==", "几米到数公里（楼宇、校园、企事业单位园区）", "==高传输速率（100M~10Gbps）、低误码率、私有部署管理=="], ["==城域网==", "==MAN（Metropolitan Area Network）==", "几公里到几十公里（整个城市或城区）", "以光纤千兆为骨干，由电信运营商统筹组建（如城市宽带网）"], ["==广域网==", "==WAN（Wide Area Network）==", "几十公里到几千公里（跨城市、跨国、全球）", "借助公用电信骨干网租用线路互联，==互联网（Internet）是全球最大的广域网=="]]}, {"id": "a3-3-1-1-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "拓扑结构考点", "text": "按网络拓扑结构分为：==星型（核心交换机，最常用、易维护但中心单点依赖）、总线型（共享同轴总线，两端需终结电阻）、环型（令牌环 Token Ring）、树型和网状（广域网常用，高冗余容错）=="}]'::jsonb, '', 'A3-3.1.1 计算机网络的定义、组成和分类。 计算机网络的定义与三大核心功能 计算机网络（Computer Network）是指将地理位置分散的、具有独立功能的计算机系统，通过通信设备和传输线路连接起来，在网络操作系统和通信协议的管理下，实现资源共享（硬件、软件、数据）、信息传输和协同分布式处理的系统。 按覆盖地理范围分类（LAN / MAN / WAN / PAN） 网络分类 英文全称 覆盖地理范围 典型特征与代表 个人区域网 PAN（Personal Area Network） 10 米以内 基于低功耗蓝牙、UWB 等个人便携随身设备互联 局域网 LAN（Local Area Network） 几米到数公里（楼宇、校园、企事业单位园区） 高传输速率（100M~10Gbps）、低误码率、私有部署管理 城域网 MAN（Metropolitan Area Network） 几公里到几十公里（整个城市或城区） 以光纤千兆为骨干，由电信运营商统筹组建（如城市宽带网） 广域网 WAN（Wide Area Network） 几十公里到几千公里（跨城市、跨国、全球） 借助公用电信骨干网租用线路互联，互联网（Internet）是全球最大的广域网 拓扑结构考点 按网络拓扑结构分为：星型（核心交换机，最常用、易维护但中心单点依赖）、总线型（共享同轴总线，两端需终结电阻）、环型（令牌环 Token Ring）、树型和网状（广域网常用，高冗余容错）', '{"pdf": "理论复习.pdf", "pages": [53, 54]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.1.2 网络服务分类，网络软件，网络操作系统，网络应用软件。 (node_id=94)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (94, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (94, 1, '[{"id": "a3-3-1-2-b1", "t": "table", "imp": "core", "title": "网络计算工作模式对比（C/S vs B/S vs P2P）", "headers": ["工作模式", "全称与拓扑特点", "核心优势与不足", "典型应用"], "rows": [["==客户机/服务器模式==", "==C/S（Client/Server）==", "客户端需安装专用客户端软件，服务器集中响应处理", "交互界面绚丽、响应快，但跨平台差、升级维护成本高（如大型网络游戏、SQL 桌面管理工具）"], ["==浏览器/服务器模式==", "==B/S（Browser/Server）==", "==以 Web 浏览器为通用客户端==，三层或多层架构", "零客户端安装、跨操作系统、集中在服务器端维护升级，==Web 门户、电商网站=="], ["==对等网络模式==", "==P2P（Peer-to-Peer）==", "节点地位完全均等，==每个节点既是客户端（下载者）又是服务器（上传提供者）==", "无单点性能瓶颈，用户越多下载反而越快；==BitTorrent（BT 种子）、电驴、区块链=="]]}, {"id": "a3-3-1-2-b2", "t": "table", "imp": "core", "title": "主流网络操作系统（NOS）代表", "headers": ["操作系统家族", "代表产品版本", "主要应用与生态特征"], "rows": [["==Linux==", "CentOS, Ubuntu Server, Red Hat Enterprise Linux", "开源免费、高稳定性、内核轻量高效，==全球绝大多数 Web 服务器和云主机的首选=="], ["==Windows Server==", "Windows Server 2016 / 2019 / 2022", "具备 GUI 图形界面、Active Directory 活动目录域控管理方便、与 .NET 生态深度结合"], ["UNIX", "IBM AIX, Oracle Solaris, HP-UX", "运行于高端小型机，用于大型银行电信核心交易系统（高可靠、昂贵）"]]}]'::jsonb, '', 'A3-3.1.2 网络服务分类，网络软件，网络操作系统，网络应用软件。 网络计算工作模式对比（C/S vs B/S vs P2P） 工作模式 全称与拓扑特点 核心优势与不足 典型应用 客户机/服务器模式 C/S（Client/Server） 客户端需安装专用客户端软件，服务器集中响应处理 交互界面绚丽、响应快，但跨平台差、升级维护成本高（如大型网络游戏、SQL 桌面管理工具） 浏览器/服务器模式 B/S（Browser/Server） 以 Web 浏览器为通用客户端，三层或多层架构 零客户端安装、跨操作系统、集中在服务器端维护升级，Web 门户、电商网站 对等网络模式 P2P（Peer-to-Peer） 节点地位完全均等，每个节点既是客户端（下载者）又是服务器（上传提供者） 无单点性能瓶颈，用户越多下载反而越快；BitTorrent（BT 种子）、电驴、区块链 主流网络操作系统（NOS）代表 操作系统家族 代表产品版本 主要应用与生态特征 Linux CentOS, Ubuntu Server, Red Hat Enterprise Linux 开源免费、高稳定性、内核轻量高效，全球绝大多数 Web 服务器和云主机的首选 Windows Server Windows Server 2016 / 2019 / 2022 具备 GUI 图形界面、Active Directory 活动目录域控管理方便、与 .NET 生态深度结合 UNIX IBM AIX, Oracle Solaris, HP-UX 运行于高端小型机，用于大型银行电信核心交易系统（高可靠、昂贵）', '{"pdf": "理论复习.pdf", "pages": [54, 55]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.2.1 局域网的特点、组成、分类。 (node_id=96)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (96, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (96, 1, '[{"id": "a3-3-2-1-b1", "t": "list", "imp": "core", "title": "局域网的四大核心特点", "items": ["覆盖地理范围有限（通常在单一建筑物、校园、企事业单位范围内）", "==传输速率高（传统 10M 到百兆、千兆乃至 10Gbps）==", "==误码率极低（通常为 10^-8 到 10^-11）==，信道质量优于广域网", "网络权属明确，由单一组织独占和自主规划、建设、维护与管理"]}, {"id": "a3-3-2-1-b2", "t": "table", "imp": "core", "title": "局域网硬件组成四大件", "headers": ["硬件组件", "主要功能", "考点关注"], "rows": [["==网络服务器==", "运行 NOS，集中存储共享文件、提供打印/邮件/Web/数据库服务", "网络中的核心资源供给者"], ["==网络工作站（客户机）==", "用户日常操作的台式电脑或终端，通过网络请求服务器资源", "接入网络的主机"], ["==网络适配器（网卡 NIC）==", "实现计算机与传输介质间的物理接口与数据串并转换", "==烧录唯一的全球 48 位（6 字节）MAC 物理地址=="], ["传输介质与互联设备", "双绞线、光纤；交换机（Switch）、无线 AP", "构建物理层与数据链路层通路"]]}]'::jsonb, '', 'A3-3.2.1 局域网的特点、组成、分类。 局域网的四大核心特点 覆盖地理范围有限（通常在单一建筑物、校园、企事业单位范围内） 传输速率高（传统 10M 到百兆、千兆乃至 10Gbps） 误码率极低（通常为 10^-8 到 10^-11），信道质量优于广域网 网络权属明确，由单一组织独占和自主规划、建设、维护与管理 局域网硬件组成四大件 硬件组件 主要功能 考点关注 网络服务器 运行 NOS，集中存储共享文件、提供打印/邮件/Web/数据库服务 网络中的核心资源供给者 网络工作站（客户机） 用户日常操作的台式电脑或终端，通过网络请求服务器资源 接入网络的主机 网络适配器（网卡 NIC） 实现计算机与传输介质间的物理接口与数据串并转换 烧录唯一的全球 48 位（6 字节）MAC 物理地址 传输介质与互联设备 双绞线、光纤；交换机（Switch）、无线 AP 构建物理层与数据链路层通路', '{"pdf": "理论复习.pdf", "pages": [55, 56]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.2.2 有线局域网。 (node_id=97)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (97, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (97, 1, '[{"id": "a3-3-2-2-b1", "t": "table", "imp": "core", "title": "以太网（IEEE 802.3 标准）与 CSMA/CD 介质访问控制", "headers": ["关键概念", "中文全称与含义", "工作机制与规则（专转本高频必背）"], "rows": [["==以太网标准==", "==IEEE 802.3==", "当前有线局域网占绝对统治地位的标准规范"], ["==CSMA/CD==", "==带冲突检测的载波监听多路访问==", "核心规则口诀：==“先听后发，边发边听，冲突停发，随机重发（二进制指数退避算法）”=="], ["==争用期（碰撞窗口）==", "信号在以太网最远端往返传播时间（2τ）", "以太网规定最短有效帧长为 ==64 字节==（小于 64 字节均为冲突碎片帧，直接丢弃）"]]}, {"id": "a3-3-2-2-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "全双工交换以太网不用 CSMA/CD", "text": "专转本必考陷阱：==早期的同轴电缆共享总线型以太网必须使用 CSMA/CD 协议解决信道冲突==；而现代使用双绞线/光纤连接全双工交换机的局域网，各端口独享带宽，==已经不存在碰撞冲突，无需使用 CSMA/CD=="}]'::jsonb, '', 'A3-3.2.2 有线局域网。 以太网（IEEE 802.3 标准）与 CSMA/CD 介质访问控制 关键概念 中文全称与含义 工作机制与规则（专转本高频必背） 以太网标准 IEEE 802.3 当前有线局域网占绝对统治地位的标准规范 CSMA/CD 带冲突检测的载波监听多路访问 核心规则口诀：“先听后发，边发边听，冲突停发，随机重发（二进制指数退避算法）” 争用期（碰撞窗口） 信号在以太网最远端往返传播时间（2τ） 以太网规定最短有效帧长为 64 字节（小于 64 字节均为冲突碎片帧，直接丢弃） 全双工交换以太网不用 CSMA/CD 专转本必考陷阱：早期的同轴电缆共享总线型以太网必须使用 CSMA/CD 协议解决信道冲突；而现代使用双绞线/光纤连接全双工交换机的局域网，各端口独享带宽，已经不存在碰撞冲突，无需使用 CSMA/CD', '{"pdf": "理论复习.pdf", "pages": [56, 57]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.2.3 无线局域网。 (node_id=98)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (98, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (98, 1, '[{"id": "a3-3-2-3-b1", "t": "table", "imp": "core", "title": "无线局域网（WLAN，IEEE 802.11 系列 / Wi-Fi）", "headers": ["标准协议", "常用商业代际称谓", "主流工作频段", "理论最高物理速率"], "rows": [["==IEEE 802.11b==", "早期 Wi-Fi 标准", "2.4 GHz", "11 Mbps"], ["==IEEE 802.11g==", "普及型标准", "2.4 GHz", "54 Mbps"], ["==IEEE 802.11n==", "Wi-Fi 4（引入 MIMO）", "2.4 GHz / 5 GHz 双频", "600 Mbps"], ["==IEEE 802.11ac==", "==Wi-Fi 5==", "5 GHz 频段", "1.3 Gbps ~ 3.5 Gbps"], ["==IEEE 802.11ax==", "==Wi-Fi 6==", "2.4 GHz / 5 GHz（OFDMA技术）", "9.6 Gbps"]]}, {"id": "a3-3-2-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "CSMA/CD 与 CSMA/CA 辨析（必考！）", "text": "==有线局域网（802.3）使用 CSMA/CD（碰撞检测）==；而==无线局域网（802.11）由于无线信号衰减巨大且无法一边发一边听，采用的是 CSMA/CA（碰撞避免，Collision Avoidance）协议==，结合 RTS/CTS 握手帧解决“隐藏终端”问题。"}]'::jsonb, '', 'A3-3.2.3 无线局域网。 无线局域网（WLAN，IEEE 802.11 系列 / Wi-Fi） 标准协议 常用商业代际称谓 主流工作频段 理论最高物理速率 IEEE 802.11b 早期 Wi-Fi 标准 2.4 GHz 11 Mbps IEEE 802.11g 普及型标准 2.4 GHz 54 Mbps IEEE 802.11n Wi-Fi 4（引入 MIMO） 2.4 GHz / 5 GHz 双频 600 Mbps IEEE 802.11ac Wi-Fi 5 5 GHz 频段 1.3 Gbps ~ 3.5 Gbps IEEE 802.11ax Wi-Fi 6 2.4 GHz / 5 GHz（OFDMA技术） 9.6 Gbps CSMA/CD 与 CSMA/CA 辨析（必考！） 有线局域网（802.3）使用 CSMA/CD（碰撞检测）；而无线局域网（802.11）由于无线信号衰减巨大且无法一边发一边听，采用的是 CSMA/CA（碰撞避免，Collision Avoidance）协议，结合 RTS/CTS 握手帧解决“隐藏终端”问题。', '{"pdf": "理论复习.pdf", "pages": [57, 58]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.3.1 广域网基础知识，广域网接入技术。 (node_id=100)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (100, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (100, 1, '[{"id": "a3-3-3-1-b1", "t": "table", "imp": "core", "title": "常见宽带接入技术演进对比", "headers": ["接入技术名称", "缩写/标准", "传输介质与上下行特点", "时代地位与应用"], "rows": [["传统拨号电话接入", "Dial-up (Modem)", "普通模拟电话双绞线，56 kbps", "早已淘汰"], ["非对称数字用户线路", "==ADSL==", "电话铜线，==上行与下行不对称（下行速率远大于上行）==，需外接话音分离器", "2000 年代主流家用宽带"], ["混合光纤同轴电缆网", "HFC (Cable Modem)", "有线电视同轴电缆 + 光纤入小区", "广电宽带典型架构"], ["==光纤接入网==", "==FTTx（光纤入户 FTTH / FTTO）==", "光纤直达家庭户内，采用 ==PON（无源光网络）==技术，百兆/千兆对称极速", "==当前我国绝大多数家庭与企业宽带的绝对主流=="]]}, {"id": "a3-3-3-1-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "FTTH 的含义", "text": "==FTTH 即 Fiber To The Home（光纤到户）==；PON（无源光网络）中间无需有源机房设备供电，抗雷击电磁干扰极强。"}]'::jsonb, '', 'A3-3.3.1 广域网基础知识，广域网接入技术。 常见宽带接入技术演进对比 接入技术名称 缩写/标准 传输介质与上下行特点 时代地位与应用 传统拨号电话接入 Dial-up (Modem) 普通模拟电话双绞线，56 kbps 早已淘汰 非对称数字用户线路 ADSL 电话铜线，上行与下行不对称（下行速率远大于上行），需外接话音分离器 2000 年代主流家用宽带 混合光纤同轴电缆网 HFC (Cable Modem) 有线电视同轴电缆 + 光纤入小区 广电宽带典型架构 光纤接入网 FTTx（光纤入户 FTTH / FTTO） 光纤直达家庭户内，采用 PON（无源光网络）技术，百兆/千兆对称极速 当前我国绝大多数家庭与企业宽带的绝对主流 FTTH 的含义 FTTH 即 Fiber To The Home（光纤到户）；PON（无源光网络）中间无需有源机房设备供电，抗雷击电磁干扰极强。', '{"pdf": "理论复习.pdf", "pages": [58]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.3.2 分组交换与路由。 (node_id=101)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (101, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (101, 1, '[{"id": "a3-3-3-2-b1", "t": "table", "imp": "core", "title": "分组交换的两大工作方式对比（数据报 vs 虚电路）", "headers": ["对比项", "==数据报（Datagram）服务==", "==虚电路（Virtual Circuit）服务=="], "rows": [["==连接建立==", "==无连接（发送前无需建立连接）==", "==面向连接（必须先建立逻辑虚电路连接）=="], ["==路由选择==", "每个分组独立路由寻径，到达终点可能乱序、丢失", "所有分组沿着预先确定的虚电路同一路径顺序传输，保证按序到达"], ["==分组头部开销==", "每个分组头都必须包含完整的源 IP 和目的 IP 地址", "仅需携带短小的虚电路标识号（VCID）"], ["==典型协议代表==", "==互联网 IP 协议（Internet 核心基石）==", "传统 X.25、帧中继（Frame Relay）、ATM 网络"]]}, {"id": "a3-3-3-2-b2", "t": "list", "imp": "important", "title": "路由器路由寻径与路由表", "items": ["路由器维护一张==路由表（Routing Table）==，记录目的网络 IP 地址、子网掩码、下一跳地址（Next Hop）及出接口", "路由学习方式：==静态路由（管理员手工配置）==与==动态路由协议（RIP、OSPF、BGP 自适应发现并更新网络拓扑变化）=="]}]'::jsonb, '', 'A3-3.3.2 分组交换与路由。 分组交换的两大工作方式对比（数据报 vs 虚电路） 对比项 数据报（Datagram）服务 虚电路（Virtual Circuit）服务 连接建立 无连接（发送前无需建立连接） 面向连接（必须先建立逻辑虚电路连接） 路由选择 每个分组独立路由寻径，到达终点可能乱序、丢失 所有分组沿着预先确定的虚电路同一路径顺序传输，保证按序到达 分组头部开销 每个分组头都必须包含完整的源 IP 和目的 IP 地址 仅需携带短小的虚电路标识号（VCID） 典型协议代表 互联网 IP 协议（Internet 核心基石） 传统 X.25、帧中继（Frame Relay）、ATM 网络 路由器路由寻径与路由表 路由器维护一张路由表（Routing Table），记录目的网络 IP 地址、子网掩码、下一跳地址（Next Hop）及出接口 路由学习方式：静态路由（管理员手工配置）与动态路由协议（RIP、OSPF、BGP 自适应发现并更新网络拓扑变化）', '{"pdf": "理论复习.pdf", "pages": [58, 59]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.4.1 互联网发展，网络互联与 TCP/IP 协议。 (node_id=103)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (103, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (103, 1, '[{"id": "a3-3-4-1-b1", "t": "table", "imp": "core", "title": "OSI 七层参考模型 vs TCP/IP 四层架构体系（必背考点）", "headers": ["OSI 七层参考模型", "TCP/IP 四层体系结构", "数据传输单位", "代表性协议"], "rows": [["7. 应用层<br>6. 表示层<br>5. 会话层", "==应用层（Application）==", "报文（Message）", "==HTTP, HTTPS, FTP, DNS, SMTP, POP3, DHCP=="], ["4. 传输层", "==传输层（Transport）==", "报文段（TCP）/ 数据报（UDP）", "==TCP（可靠、面向连接）、UDP（不可靠无连接）=="], ["3. 网络层", "==网际层 / 网络层（Internet）==", "IP 数据报 / 分组（Packet）", "==IP, ICMP（ping命令检测）, ARP（IP转MAC）, RARP=="], ["2. 数据链路层<br>1. 物理层", "==网络接口层（Network Interface）==", "帧（Frame）/ 比特位（Bit）", "以太网 802.3, Wi-Fi 802.11, PPP, MAC 寻址"]]}, {"id": "a3-3-4-1-b2", "t": "table", "imp": "core", "title": "传输层 TCP vs UDP 核心区别对比（专转本每年必考大题）", "headers": ["对比维度", "TCP（传输控制协议）", "UDP（用户数据报协议）"], "rows": [["==连接方式==", "==面向连接（必须经历三次握手建连、四次挥手断连）==", "==无连接（直接发送，无需提前握手）=="], ["==可靠性保证==", "==可靠传输（确认应答、超时重传、滑动窗口流量控制、拥塞控制）==", "==不可靠尽最大努力交付（不保证不丢失、不保证顺序）=="], ["传输开销与头部", "头部开销大（最小 20 字节，含复杂序列号与确认号控制位）", "头部小（仅 8 字节），开销极小"], ["传输模式", "面向字节流传输", "面向报文传输（保留上层报文边界）"], ["典型应用协议", "==HTTP/HTTPS（网页）、FTP（文件传输）、SMTP/POP3（邮件）、SSH==", "==DNS（域名解析）、SNMP、音视频直播、实时网络语音对战游戏=="]]}]'::jsonb, '', 'A3-3.4.1 互联网发展，网络互联与 TCP/IP 协议。 OSI 七层参考模型 vs TCP/IP 四层架构体系（必背考点） OSI 七层参考模型 TCP/IP 四层体系结构 数据传输单位 代表性协议 7. 应用层<br>6. 表示层<br>5. 会话层 应用层（Application） 报文（Message） HTTP, HTTPS, FTP, DNS, SMTP, POP3, DHCP 4. 传输层 传输层（Transport） 报文段（TCP）/ 数据报（UDP） TCP（可靠、面向连接）、UDP（不可靠无连接） 3. 网络层 网际层 / 网络层（Internet） IP 数据报 / 分组（Packet） IP, ICMP（ping命令检测）, ARP（IP转MAC）, RARP 2. 数据链路层<br>1. 物理层 网络接口层（Network Interface） 帧（Frame）/ 比特位（Bit） 以太网 802.3, Wi-Fi 802.11, PPP, MAC 寻址 传输层 TCP vs UDP 核心区别对比（专转本每年必考大题） 对比维度 TCP（传输控制协议） UDP（用户数据报协议） 连接方式 面向连接（必须经历三次握手建连、四次挥手断连） 无连接（直接发送，无需提前握手） 可靠性保证 可靠传输（确认应答、超时重传、滑动窗口流量控制、拥塞控制） 不可靠尽最大努力交付（不保证不丢失、不保证顺序） 传输开销与头部 头部开销大（最小 20 字节，含复杂序列号与确认号控制位） 头部小（仅 8 字节），开销极小 传输模式 面向字节流传输 面向报文传输（保留上层报文边界） 典型应用协议 HTTP/HTTPS（网页）、FTP（文件传输）、SMTP/POP3（邮件）、SSH DNS（域名解析）、SNMP、音视频直播、实时网络语音对战游戏', '{"pdf": "理论复习.pdf", "pages": [59, 60, 61]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.4.2 IP 地址（IPv4、IPv6）及分类，域名。 (node_id=104)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (104, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (104, 1, '[{"id": "a3-3-4-2-b1", "t": "table", "imp": "core", "title": "传统 IPv4 地址五类划分与私有保留地址表（必须死记硬背）", "headers": ["类别", "首字节范围", "默认子网掩码", "私有专用地址范围（内网私网地址）"], "rows": [["==A 类==", "==1 ~ 126==", "==255.0.0.0==（/8）", "==10.0.0.0 ~ 10.255.255.255=="], ["==B 类==", "==128 ~ 191==", "==255.255.0.0==（/16）", "==172.16.0.0 ~ 172.31.255.255=="], ["==C 类==", "==192 ~ 223==", "==255.255.255.0==（/24）", "==192.168.0.0 ~ 192.168.255.255=="], ["==D 类==", "==224 ~ 239==", "无（用于组播 / 多播）", "组播保留"], ["==E 类==", "==240 ~ 255==", "无（科学实验保留）", "科研实验保留"]]}, {"id": "a3-3-4-2-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "特殊保留 IP 地址陷阱", "text": "• ==127.0.0.1：本地环回测试地址（Loopback）==，用于测试本地网络协议栈是否正常；\n• 网络号全 0（0.0.0.0）：本网络本机；\n• 主机号全 0：代表当前==网络本身（网络地址）==；\n• 主机号全 1（如 192.168.1.255）：当前网络的==直接广播地址=="}, {"id": "a3-3-4-2-b3", "t": "table", "imp": "core", "title": "IPv4 vs IPv6 核心对比", "headers": ["特性维度", "IPv4", "IPv6"], "rows": [["==地址长度==", "==32 位（4 字节）==", "==128 位（16 字节）=="], ["地址书写表达", "点分十进制（如 `192.168.1.1`）", "==冒号十六进制（如 `2001:0db8::1`），支持零压缩连续双冒号::=="], ["地址空间数量", "约 43 亿个（已彻底耗尽）", "==2^128 个（可为地球上每一粒沙子分配一个 IP）=="], ["原生安全特性", "可选配置 IPSec", "内核原生集成 IPSec 加密与身份认证"]]}]'::jsonb, '', 'A3-3.4.2 IP 地址（IPv4、IPv6）及分类，域名。 传统 IPv4 地址五类划分与私有保留地址表（必须死记硬背） 类别 首字节范围 默认子网掩码 私有专用地址范围（内网私网地址） A 类 1 ~ 126 255.0.0.0（/8） 10.0.0.0 ~ 10.255.255.255 B 类 128 ~ 191 255.255.0.0（/16） 172.16.0.0 ~ 172.31.255.255 C 类 192 ~ 223 255.255.255.0（/24） 192.168.0.0 ~ 192.168.255.255 D 类 224 ~ 239 无（用于组播 / 多播） 组播保留 E 类 240 ~ 255 无（科学实验保留） 科研实验保留 特殊保留 IP 地址陷阱 • 127.0.0.1：本地环回测试地址（Loopback），用于测试本地网络协议栈是否正常；
• 网络号全 0（0.0.0.0）：本网络本机；
• 主机号全 0：代表当前网络本身（网络地址）；
• 主机号全 1（如 192.168.1.255）：当前网络的直接广播地址 IPv4 vs IPv6 核心对比 特性维度 IPv4 IPv6 地址长度 32 位（4 字节） 128 位（16 字节） 地址书写表达 点分十进制（如 192.168.1.1） 冒号十六进制（如 2001:0db8::1），支持零压缩连续双冒号:: 地址空间数量 约 43 亿个（已彻底耗尽） 2^128 个（可为地球上每一粒沙子分配一个 IP） 原生安全特性 可选配置 IPSec 内核原生集成 IPSec 加密与身份认证', '{"pdf": "理论复习.pdf", "pages": [62, 63, 64]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.4.3 交换机与路由器。 (node_id=105)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (105, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (105, 1, '[{"id": "a3-3-4-3-b1", "t": "table", "imp": "core", "title": "集线器 vs 交换机 vs 路由器 核心对比（专转本高频大题）", "headers": ["对比项", "集线器（Hub）", "==以太网交换机（Switch）==", "==路由器（Router）=="], "rows": [["==工作协议层级==", "物理层（第 1 层）", "==数据链路层（第 2 层）==", "==网络层（第 3 层）=="], ["==转发寻址依据==", "无寻址，单纯电信号放大，广播泛洪", "==基于 MAC 物理地址表（自学习学习源 MAC，按目的 MAC 硬件线速转发）==", "==基于 IP 路由表寻址（路由算法寻径，跨异构网络互联）=="], ["==冲突域与广播域==", "所有端口属于同一个冲突域、同一个广播域", "==每个端口独占一个冲突域，但所有端口仍处于同一个广播域==", "==每个端口都是一个独立的冲突域，且每个端口隔离广播域（阻隔广播风暴）=="], ["带宽分配方式", "所有端口共享总带宽", "==每个端口独占标称物理带宽（如每个端口均为 1Gbps）==", "根据路由接口与网络排队调度带宽"]]}, {"id": "a3-3-4-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "隔离冲突域与广播域速记", "text": "==集线器：既不隔离冲突域，也不隔离广播域==；\n==交换机：分割隔离冲突域，但不隔离广播域==（除非划分 VLAN 虚拟局域网）；\n==路由器：既隔离冲突域，又隔离广播域=="}]'::jsonb, '', 'A3-3.4.3 交换机与路由器。 集线器 vs 交换机 vs 路由器 核心对比（专转本高频大题） 对比项 集线器（Hub） 以太网交换机（Switch） 路由器（Router） 工作协议层级 物理层（第 1 层） 数据链路层（第 2 层） 网络层（第 3 层） 转发寻址依据 无寻址，单纯电信号放大，广播泛洪 基于 MAC 物理地址表（自学习学习源 MAC，按目的 MAC 硬件线速转发） 基于 IP 路由表寻址（路由算法寻径，跨异构网络互联） 冲突域与广播域 所有端口属于同一个冲突域、同一个广播域 每个端口独占一个冲突域，但所有端口仍处于同一个广播域 每个端口都是一个独立的冲突域，且每个端口隔离广播域（阻隔广播风暴） 带宽分配方式 所有端口共享总带宽 每个端口独占标称物理带宽（如每个端口均为 1Gbps） 根据路由接口与网络排队调度带宽 隔离冲突域与广播域速记 集线器：既不隔离冲突域，也不隔离广播域；
交换机：分割隔离冲突域，但不隔离广播域（除非划分 VLAN 虚拟局域网）；
路由器：既隔离冲突域，又隔离广播域', '{"pdf": "理论复习.pdf", "pages": [64]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.4.4 互联网提供的服务。 (node_id=106)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (106, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (106, 1, '[{"id": "a3-3-4-4-b1", "t": "table", "imp": "core", "title": "互联网核心基础服务与默认端口号（必须全部背出）", "headers": ["服务名称", "主要协议", "传输层协议", "默认标准端口号", "功能说明"], "rows": [["==万维网服务（Web）==", "==HTTP==", "TCP", "==80==", "超文本传输协议，网页浏览访问"], ["==安全万维网服务==", "==HTTPS==", "TCP", "==443==", "基于 SSL/TLS 证书加密传输的 HTTP"], ["==域名解析服务==", "==DNS==", "==UDP（主要）/ TCP==", "==53==", "将人类可读的域名解析转换为机器 IP 地址"], ["==文件传输服务==", "==FTP==", "TCP", "==21（控制连接） / 20（数据连接）==", "双连接架构：21 端口传控制指令，20 端口传数据"], ["==邮件发送服务==", "==SMTP==", "TCP", "==25==", "简单邮件传输协议，负责把信件投递发送到对方邮箱服务器"], ["==邮件接收服务==", "==POP3 / IMAP==", "TCP", "==POP3 为 110== / IMAP 为 143", "从邮件服务器拉取下载邮件到本地客户端"], ["==动态主机配置==", "==DHCP==", "UDP", "==67（服务器） / 68（客户端）==", "为局域网接入主机自动动态分配 IP 地址、网关和 DNS"], ["远程终端服务", "SSH / Telnet", "TCP", "==SSH 为 22（安全加密）== / Telnet 为 23（明文）", "远程命令行控制管理服务器"]]}, {"id": "a3-3-4-4-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "FTP 的双端口机制考点", "text": "专转本常考：FTP 服务在传输过程中同时建立两个并发连接——==控制连接使用 TCP 21 端口，贯穿整个会话；数据连接在主动模式下使用 TCP 20 端口，传输完毕立即断开=="}]'::jsonb, '', 'A3-3.4.4 互联网提供的服务。 互联网核心基础服务与默认端口号（必须全部背出） 服务名称 主要协议 传输层协议 默认标准端口号 功能说明 万维网服务（Web） HTTP TCP 80 超文本传输协议，网页浏览访问 安全万维网服务 HTTPS TCP 443 基于 SSL/TLS 证书加密传输的 HTTP 域名解析服务 DNS UDP（主要）/ TCP 53 将人类可读的域名解析转换为机器 IP 地址 文件传输服务 FTP TCP 21（控制连接） / 20（数据连接） 双连接架构：21 端口传控制指令，20 端口传数据 邮件发送服务 SMTP TCP 25 简单邮件传输协议，负责把信件投递发送到对方邮箱服务器 邮件接收服务 POP3 / IMAP TCP POP3 为 110 / IMAP 为 143 从邮件服务器拉取下载邮件到本地客户端 动态主机配置 DHCP UDP 67（服务器） / 68（客户端） 为局域网接入主机自动动态分配 IP 地址、网关和 DNS 远程终端服务 SSH / Telnet TCP SSH 为 22（安全加密） / Telnet 为 23（明文） 远程命令行控制管理服务器 FTP 的双端口机制考点 专转本常考：FTP 服务在传输过程中同时建立两个并发连接——控制连接使用 TCP 21 端口，贯穿整个会话；数据连接在主动模式下使用 TCP 20 端口，传输完毕立即断开', '{"pdf": "理论复习.pdf", "pages": [64, 65]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.5.1 信息安全基本概念。 (node_id=108)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (108, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (108, 1, '[{"id": "a3-3-5-1-b1", "t": "table", "imp": "core", "title": "信息安全五大基本属性（CIA 三要素及扩充）", "headers": ["安全属性", "英文标识", "定义内涵与要求", "破坏防范案例"], "rows": [["==机密性（保密性）==", "==Confidentiality==", "确保信息不暴露给未经授权的实体、实体人或进程（防止信息泄露）", "通过数据加密防止网络嗅探窃听"], ["==完整性==", "==Integrity==", "确保信息在存储或传输过程中不被未授权篡改、伪造、删除（保持真实完整）", "利用 MD5/SHA 哈希校验码与消息认证码防篡改"], ["==可用性==", "==Availability==", "确保获得授权的实体在需要时能够及时、正常访问到信息和系统服务", "防范 DDoS 拒绝服务攻击导致服务器瘫痪"], ["==真实性 / 身份认证==", "Authenticity", "确保通信各方身份真实合法，非冒充伪造", "数字证书、多因素认证（MFA）"], ["==不可抵赖性（防否认）==", "Non-repudiation", "行为人发起信息交互后无法否认其曾经发送或签署过的行为", "基于非对称私钥的数字签名技术"]]}, {"id": "a3-3-5-1-b2", "t": "callout", "imp": "core", "kind": "tip", "title": "CIA 三要素", "text": "现代信息安全的经典基石为 ==CIA 三要素：机密性（Confidentiality）、完整性（Integrity）、可用性（Availability）=="}]'::jsonb, '', 'A3-3.5.1 信息安全基本概念。 信息安全五大基本属性（CIA 三要素及扩充） 安全属性 英文标识 定义内涵与要求 破坏防范案例 机密性（保密性） Confidentiality 确保信息不暴露给未经授权的实体、实体人或进程（防止信息泄露） 通过数据加密防止网络嗅探窃听 完整性 Integrity 确保信息在存储或传输过程中不被未授权篡改、伪造、删除（保持真实完整） 利用 MD5/SHA 哈希校验码与消息认证码防篡改 可用性 Availability 确保获得授权的实体在需要时能够及时、正常访问到信息和系统服务 防范 DDoS 拒绝服务攻击导致服务器瘫痪 真实性 / 身份认证 Authenticity 确保通信各方身份真实合法，非冒充伪造 数字证书、多因素认证（MFA） 不可抵赖性（防否认） Non-repudiation 行为人发起信息交互后无法否认其曾经发送或签署过的行为 基于非对称私钥的数字签名技术 CIA 三要素 现代信息安全的经典基石为 CIA 三要素：机密性（Confidentiality）、完整性（Integrity）、可用性（Availability）', '{"pdf": "理论复习.pdf", "pages": [65]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.5.2 信息安全规范。 (node_id=109)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (109, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (109, 1, '[{"id": "a3-3-5-2-b1", "t": "table", "imp": "core", "title": "我国网络安全等级保护制度（等保 2.0 五级划分）", "headers": ["保护等级", "定级对象与影响范围", "监管要求与典型系统"], "rows": [["==第一级（自主保护级）==", "受到破坏后，对公民、法人和其他组织的合法权益造成损害，但不损害国家安全、社会秩序和公共利益", "一般小型私有内部办公系统"], ["==第二级（指导保护级）==", "受到破坏后，对社会秩序和公共利益造成轻度损害，但不损害国家安全", "地市级一般企事业单位门户网"], ["==第三级（监督保护级）==", "受到破坏后，==对社会秩序和公共利益造成严重损害，或对国家安全造成损害==", "==地级市以上重要政务、地市级社保、三甲医院 HIS、高校核心教务系统（常规大考重点）=="], ["==第四级（强制保护级）==", "受到破坏后，对社会秩序和公共利益造成特别严重损害，或对国家安全造成严重损害", "国家电力电网调度控制系统、全国性大型国有商业银行主干交易"], ["==第五级（专控保护级）==", "受到破坏后，对国家安全造成特别严重损害", "国家级国防涉密核心网络基础设施"]]}, {"id": "a3-3-5-2-b2", "t": "list", "imp": "important", "title": "我国核心网络安全法律法规体系", "items": ["==《中华人民共和国网络安全法》==（2017 年 6 月 1 日起施行，我国网络安全领域第一部基础性法律）", "《中华人民共和国数据安全法》与《中华人民共和国个人信息保护法》", "《计算机信息系统安全保护等级划分准则》（GB 17859-1999）"]}]'::jsonb, '', 'A3-3.5.2 信息安全规范。 我国网络安全等级保护制度（等保 2.0 五级划分） 保护等级 定级对象与影响范围 监管要求与典型系统 第一级（自主保护级） 受到破坏后，对公民、法人和其他组织的合法权益造成损害，但不损害国家安全、社会秩序和公共利益 一般小型私有内部办公系统 第二级（指导保护级） 受到破坏后，对社会秩序和公共利益造成轻度损害，但不损害国家安全 地市级一般企事业单位门户网 第三级（监督保护级） 受到破坏后，对社会秩序和公共利益造成严重损害，或对国家安全造成损害 地级市以上重要政务、地市级社保、三甲医院 HIS、高校核心教务系统（常规大考重点） 第四级（强制保护级） 受到破坏后，对社会秩序和公共利益造成特别严重损害，或对国家安全造成严重损害 国家电力电网调度控制系统、全国性大型国有商业银行主干交易 第五级（专控保护级） 受到破坏后，对国家安全造成特别严重损害 国家级国防涉密核心网络基础设施 我国核心网络安全法律法规体系 《中华人民共和国网络安全法》（2017 年 6 月 1 日起施行，我国网络安全领域第一部基础性法律） 《中华人民共和国数据安全法》与《中华人民共和国个人信息保护法》 《计算机信息系统安全保护等级划分准则》（GB 17859-1999）', '{"pdf": "理论复习.pdf", "pages": [65]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.5.3 常见的网络安全威胁。 (node_id=110)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (110, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (110, 1, '[{"id": "a3-3-5-3-b1", "t": "table", "imp": "core", "title": "常见主动攻击 vs 被动攻击对比", "headers": ["攻击分类", "核心威胁行为", "典型攻击手段举例", "防御侧重"], "rows": [["==被动攻击（Passive Attack）==", "==只窃听、监听、监视数据传输，不破坏和篡改数据，系统照常运行==", "网络嗅探（Sniffing，如 Wireshark 抓包）、流量模式分析", "==侧重加密预防（端到端强加密），很难直接检测发现=="], ["==主动攻击（Active Attack）==", "==故意篡改、伪造数据流，破坏系统可用性与完整性==", "==DDoS 拒绝服务攻击、重放攻击、IP/MAC 欺骗、中间人攻击（MITM）、SQL 注入、XSS 跨站脚本==", "==侧重检测、中断阻止与灾后数据恢复=="]]}, {"id": "a3-3-5-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "DDoS 分布式拒绝服务攻击", "text": "==DDoS（Distributed Denial of Service）==攻击通过控制成千上万台僵尸网络“肉鸡”，向目标服务器短时间内发送海量垃圾请求，将服务器带宽或 CPU 耗尽，破坏了信息安全的==“可用性”（Availability）=="}]'::jsonb, '', 'A3-3.5.3 常见的网络安全威胁。 常见主动攻击 vs 被动攻击对比 攻击分类 核心威胁行为 典型攻击手段举例 防御侧重 被动攻击（Passive Attack） 只窃听、监听、监视数据传输，不破坏和篡改数据，系统照常运行 网络嗅探（Sniffing，如 Wireshark 抓包）、流量模式分析 侧重加密预防（端到端强加密），很难直接检测发现 主动攻击（Active Attack） 故意篡改、伪造数据流，破坏系统可用性与完整性 DDoS 拒绝服务攻击、重放攻击、IP/MAC 欺骗、中间人攻击（MITM）、SQL 注入、XSS 跨站脚本 侧重检测、中断阻止与灾后数据恢复 DDoS 分布式拒绝服务攻击 DDoS（Distributed Denial of Service）攻击通过控制成千上万台僵尸网络“肉鸡”，向目标服务器短时间内发送海量垃圾请求，将服务器带宽或 CPU 耗尽，破坏了信息安全的“可用性”（Availability）', '{"pdf": "理论复习.pdf", "pages": [65]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.5.4 入侵检测、防火墙、计算机病毒。 (node_id=111)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (111, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (111, 1, '[{"id": "a3-3-5-4-b1", "t": "table", "imp": "core", "title": "防火墙（FW） vs 入侵检测系统（IDS） vs 入侵防御系统（IPS）", "headers": ["安全设备", "功能角色定位", "工作机制比喻", "主要部署位置"], "rows": [["==防火墙（Firewall）==", "依据安全策略规则进行网络边界访问控制与数据包过滤", "==门卫保安（检查工牌放行或拦截）==", "部署在网络出入口网络边界"], ["==入侵检测系统（IDS）==", "旁路监听镜像流量，实时检测入侵行为并告警记录日志", "==监控摄像头与报警器（只监视报警，不直接阻断交通）==", "旁路挂接在核心交换机镜像端口"], ["==入侵防御系统（IPS）==", "串联部署在网络主干，发现恶意特征攻击时直接实时阻断丢包", "==防暴警察（就地制服并直接阻断入侵）==", "串联在网络主链路中"]]}, {"id": "a3-3-5-4-b2", "t": "table", "imp": "core", "title": "计算机病毒（Virus）四大核心特征与分类", "headers": ["病毒特性", "内涵解释", "常见恶意软件分类辨析"], "rows": [["==传染性（最本质特征）==", "通过自我复制将病毒代码附加到正常程序或文档中", "==特洛伊木马（Trojan）：不自我繁殖，伪装成正常软件诱骗运行后开后门远程控制=="], ["==隐蔽性==", "寄生在正常文件中，未发作时不引起用户察觉", "==网络蠕虫（Worm）：具备独立文件实体，利用网络系统漏洞自主疯狂传播（如红色代码、震网）=="], ["==破坏性==", "占用系统资源、破坏引导扇区、加密勒索文件、窃取密码", "==勒索病毒（Ransomware）：利用非对称加密锁死用户关键数据库并勒索比特币=="], ["==潜伏性与可触发性==", "满足特定条件（如特定日期、特定键盘操作）才激活发作", "宏病毒：专门感染 Word/Excel 等 Office 文档中的 VBA 宏模块"]]}]'::jsonb, '', 'A3-3.5.4 入侵检测、防火墙、计算机病毒。 防火墙（FW） vs 入侵检测系统（IDS） vs 入侵防御系统（IPS） 安全设备 功能角色定位 工作机制比喻 主要部署位置 防火墙（Firewall） 依据安全策略规则进行网络边界访问控制与数据包过滤 门卫保安（检查工牌放行或拦截） 部署在网络出入口网络边界 入侵检测系统（IDS） 旁路监听镜像流量，实时检测入侵行为并告警记录日志 监控摄像头与报警器（只监视报警，不直接阻断交通） 旁路挂接在核心交换机镜像端口 入侵防御系统（IPS） 串联部署在网络主干，发现恶意特征攻击时直接实时阻断丢包 防暴警察（就地制服并直接阻断入侵） 串联在网络主链路中 计算机病毒（Virus）四大核心特征与分类 病毒特性 内涵解释 常见恶意软件分类辨析 传染性（最本质特征） 通过自我复制将病毒代码附加到正常程序或文档中 特洛伊木马（Trojan）：不自我繁殖，伪装成正常软件诱骗运行后开后门远程控制 隐蔽性 寄生在正常文件中，未发作时不引起用户察觉 网络蠕虫（Worm）：具备独立文件实体，利用网络系统漏洞自主疯狂传播（如红色代码、震网） 破坏性 占用系统资源、破坏引导扇区、加密勒索文件、窃取密码 勒索病毒（Ransomware）：利用非对称加密锁死用户关键数据库并勒索比特币 潜伏性与可触发性 满足特定条件（如特定日期、特定键盘操作）才激活发作 宏病毒：专门感染 Word/Excel 等 Office 文档中的 VBA 宏模块', '{"pdf": "理论复习.pdf", "pages": [65]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.5.5 加密和解密基本概念。 (node_id=112)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (112, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (112, 1, '[{"id": "a3-3-5-5-b1", "t": "table", "imp": "core", "title": "对称加密 vs 非对称加密（专转本每考必出大题）", "headers": ["对比项", "==对称加密（私钥密码体制）==", "==非对称加密（公钥密码体制）=="], "rows": [["==密钥使用==", "==加密和解密使用同一个密钥（相同秘钥）==", "==加密和解密使用一对密钥：公钥（Public Key）和私钥（Private Key）=="], ["==密钥分发安全性==", "密钥必须通过安全信道提前共享，在不可信网络中分发极难", "公钥可以向全世界完全公开公开广播，私钥仅由本人私自保管，==无密钥分发难题=="], ["==加解密速度与算力消耗==", "==计算速度极快，开销极小，适合对海量大数据块加密==", "算法涉及大数因子分解，计算复杂度高、==加解密速度较慢（慢百倍至千倍）=="], ["==典型代表算法==", "==DES（56位已不安全）、3DES、AES（主流高级加密标准）、RC4==", "==RSA（基于大素数分解）、ECC（椭圆曲线加密）、ElGamal=="], ["国产国密算法对应", "==SM4（商密4号，分组对称密码）==", "==SM2（商密2号，基于椭圆曲线的非对称加密）=="]]}, {"id": "a3-3-5-5-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "混合加密体系（现代 SSL/TLS 做法）", "text": "在实际互联网通信中，通常采用混合模式：==用运算慢但安全的“非对称加密”传递协商一个临时的“对称会话密钥”；随后双方使用速度极快的“对称加密”加密实际传输的业务报文=="}]'::jsonb, '', 'A3-3.5.5 加密和解密基本概念。 对称加密 vs 非对称加密（专转本每考必出大题） 对比项 对称加密（私钥密码体制） 非对称加密（公钥密码体制） 密钥使用 加密和解密使用同一个密钥（相同秘钥） 加密和解密使用一对密钥：公钥（Public Key）和私钥（Private Key） 密钥分发安全性 密钥必须通过安全信道提前共享，在不可信网络中分发极难 公钥可以向全世界完全公开公开广播，私钥仅由本人私自保管，无密钥分发难题 加解密速度与算力消耗 计算速度极快，开销极小，适合对海量大数据块加密 算法涉及大数因子分解，计算复杂度高、加解密速度较慢（慢百倍至千倍） 典型代表算法 DES（56位已不安全）、3DES、AES（主流高级加密标准）、RC4 RSA（基于大素数分解）、ECC（椭圆曲线加密）、ElGamal 国产国密算法对应 SM4（商密4号，分组对称密码） SM2（商密2号，基于椭圆曲线的非对称加密） 混合加密体系（现代 SSL/TLS 做法） 在实际互联网通信中，通常采用混合模式：用运算慢但安全的“非对称加密”传递协商一个临时的“对称会话密钥”；随后双方使用速度极快的“对称加密”加密实际传输的业务报文', '{"pdf": "理论复习.pdf", "pages": [65]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.5.6 威胁防范与信息安全发展趋势。 (node_id=113)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (113, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (113, 1, '[{"id": "a3-3-5-6-b1", "t": "list", "imp": "core", "title": "现代信息安全前沿技术演进方向", "items": ["==零信任架构（Zero Trust）==：核心原则==“持续验证，永不信任（Never Trust, Always Verify）”==，打破传统“内网即安全”的边界防御假设", "==安全编排自动化与响应（SOAR）与态势感知==：基于大数据威胁情报对全网安全事件进行智能关联聚类与毫秒级自动联动封堵", "==量子密码与后量子密码（PQC）==：基于量子不可克隆原理的量子密钥分发（QKD），防范未来量子计算机对经典 RSA 密码体制的颠覆式破解"]}, {"id": "a3-3-5-6-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "零信任三大支柱", "text": "零信任三大技术要素：==基于身份的动态访问控制（IAM）、软件定义边界（SDP）、微隔离（Micro-segmentation）=="}]'::jsonb, '', 'A3-3.5.6 威胁防范与信息安全发展趋势。 现代信息安全前沿技术演进方向 零信任架构（Zero Trust）：核心原则“持续验证，永不信任（Never Trust, Always Verify）”，打破传统“内网即安全”的边界防御假设 安全编排自动化与响应（SOAR）与态势感知：基于大数据威胁情报对全网安全事件进行智能关联聚类与毫秒级自动联动封堵 量子密码与后量子密码（PQC）：基于量子不可克隆原理的量子密钥分发（QKD），防范未来量子计算机对经典 RSA 密码体制的颠覆式破解 零信任三大支柱 零信任三大技术要素：基于身份的动态访问控制（IAM）、软件定义边界（SDP）、微隔离（Micro-segmentation）', '{"pdf": "理论复习.pdf", "pages": [65]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A3-3.5.7 应急响应处理流程。 (node_id=114)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (114, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (114, 1, '[{"id": "a3-3-5-7-b1", "t": "table", "imp": "core", "title": "网络安全应急响应 PDCERF 经典六阶段模型", "headers": ["阶段序号", "阶段英文缩写", "阶段名称", "主要应对工作与动作"], "rows": [["1", "P", "==准备阶段（Preparation）==", "制定应急预案体系、配备安全工具、组织实战演练与资产盘点"], ["2", "D", "==检测阶段（Detection）==", "发现安全告警、判定安全事件类型（病毒/入侵/篡改/断网）及危害波及范围"], ["3", "C", "==抑制阶段（Containment）==", "==第一时间拔掉网线、隔离受害主机、关闭风险端口，阻止危害进一步向全网横向扩散=="], ["4", "E", "==根除阶段（Eradication）==", "查找根本漏洞根源，清除残留木马病毒后门、修复系统漏洞、强制更换所有管理凭据"], ["5", "R", "==恢复阶段（Recovery）==", "从离线干净备份恢复业务数据，逐步恢复网络上线，开启高密监控"], ["6", "F", "==跟踪总结（Follow-up）==", "复盘事件全过程，形成事件溯源取证报告，修订完善应急预案与安全防御规则"]]}, {"id": "a3-3-5-7-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "应急响应第一黄金法则", "text": "当检测到服务器发生严重安全入侵或勒索病毒扩散时，现场运维人员的第一处置动作是：==物理断网隔离（拔掉网线或禁用网卡），但严禁直接断电关机，以防内存中黑客作案痕迹与木马进程易失性证据丢失！=="}]'::jsonb, '', 'A3-3.5.7 应急响应处理流程。 网络安全应急响应 PDCERF 经典六阶段模型 阶段序号 阶段英文缩写 阶段名称 主要应对工作与动作 1 P 准备阶段（Preparation） 制定应急预案体系、配备安全工具、组织实战演练与资产盘点 2 D 检测阶段（Detection） 发现安全告警、判定安全事件类型（病毒/入侵/篡改/断网）及危害波及范围 3 C 抑制阶段（Containment） 第一时间拔掉网线、隔离受害主机、关闭风险端口，阻止危害进一步向全网横向扩散 4 E 根除阶段（Eradication） 查找根本漏洞根源，清除残留木马病毒后门、修复系统漏洞、强制更换所有管理凭据 5 R 恢复阶段（Recovery） 从离线干净备份恢复业务数据，逐步恢复网络上线，开启高密监控 6 F 跟踪总结（Follow-up） 复盘事件全过程，形成事件溯源取证报告，修订完善应急预案与安全防御规则 应急响应第一黄金法则 当检测到服务器发生严重安全入侵或勒索病毒扩散时，现场运维人员的第一处置动作是：物理断网隔离（拔掉网线或禁用网卡），但严禁直接断电关机，以防内存中黑客作案痕迹与木马进程易失性证据丢失！', '{"pdf": "理论复习.pdf", "pages": [65]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.1.1 文本，文本处理，文本输入方法。 (node_id=116)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (116, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (116, 1, '[{"id": "a4-4-1-1-b1", "t": "p", "imp": "core", "title": "文本与文本处理的概念", "text": "==文本（Text）==是以文字、数字和专用符号等形式表达的信息载体，是人类最基本、最重要的信息交流方式。==文本处理（Text Processing）==是指利用计算机对文本信息进行输入、编辑排版、格式转换、校对、存储、检索和输出展现的全过程。"}, {"id": "a4-4-1-1-b2", "t": "table", "imp": "core", "title": "汉字输入码（外码）三大主流类型对比", "headers": ["输入码分类", "编码依据与原理", "主要优缺点", "代表输入法"], "rows": [["==音码（流水码）==", "按照汉字的标准汉语拼音字母进行编码输入", "容易上手、无需专门记忆字根；但==同音字重码率极高，录入盲打速度受限==", "微软拼音、搜狗拼音、微信输入法"], ["==形码（字形码）==", "按照汉字的笔画、偏旁部首等空间字形结构拆分编码", "学习记忆难度大（需背诵字根表）；但==重码率极低，熟练后录入速度极快==", "==五笔字型输入法（王码五笔）、仓颉输入法=="], ["==音形结合码==", "同时结合汉字的拼音读音和字形偏旁首笔画编码", "重码率适中，规则容易记忆", "自然码、二笔输入法"]]}]'::jsonb, '', 'A4-4.1.1 文本，文本处理，文本输入方法。 文本与文本处理的概念 文本（Text）是以文字、数字和专用符号等形式表达的信息载体，是人类最基本、最重要的信息交流方式。文本处理（Text Processing）是指利用计算机对文本信息进行输入、编辑排版、格式转换、校对、存储、检索和输出展现的全过程。 汉字输入码（外码）三大主流类型对比 输入码分类 编码依据与原理 主要优缺点 代表输入法 音码（流水码） 按照汉字的标准汉语拼音字母进行编码输入 容易上手、无需专门记忆字根；但同音字重码率极高，录入盲打速度受限 微软拼音、搜狗拼音、微信输入法 形码（字形码） 按照汉字的笔画、偏旁部首等空间字形结构拆分编码 学习记忆难度大（需背诵字根表）；但重码率极低，熟练后录入速度极快 五笔字型输入法（王码五笔）、仓颉输入法 音形结合码 同时结合汉字的拼音读音和字形偏旁首笔画编码 重码率适中，规则容易记忆 自然码、二笔输入法', '{"pdf": "理论复习.pdf", "pages": [66, 67]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.1.2 文本的表示与字符编码。 (node_id=117)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (117, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (117, 1, '[{"id": "a4-4-1-2-b1", "t": "table", "imp": "core", "title": "汉字编码体系四码演进与转换公式（专转本每年必考计算）", "headers": ["编码阶段", "编码名称", "存储/表示形式", "换算逻辑与计算公式"], "rows": [["1. 输入阶段", "==输入码（外码）==", "拼音字母或五笔编码", "用于键盘键入识别"], ["2. 区位划分", "==区位码==", "2 字节十进制（94 个区，每区 94 个位）", "如某汉字区位码为 `3045`（第 30 区第 45 位）"], ["3. 交换标准", "==国标码（GB2312）==", "2 字节十六进制，避开 ASCII 控制字符", "==国标码 = 区位码（十六进制） + 2020H=="], ["4. 内部存储", "==机内码（内码）==", "2 字节十六进制，==最高位置 1（大于 80H）以区分西文字符==", "==机内码 = 国标码 + 8080H = 区位码（十六进制） + A0A0H=="], ["5. 屏幕输出", "==字形码（字模码）==", "点阵字形二进制比特串（如 16×16 点阵）", "用于字库检索与屏幕笔画显微打印"]]}, {"id": "a4-4-1-2-b2", "t": "table", "imp": "core", "title": "常用字符集编码标准对比", "headers": ["字符集标准", "占用字节数", "收录字符范围", "兼容性与特点"], "rows": [["==ASCII==", "1 字节（最高位置 0，实际用 7 位）", "128 个基本字符（数字、英文字母、标点与控制符）", "现代字符编码的基石"], ["==GB2312-80==", "==2 字节==", "收录 6763 个简体汉字及 682 个符号", "一级汉字按拼音排序，二级汉字按部首笔画排序"], ["==GBK==", "==2 字节==", "收录 21003 个汉字（包含繁体字、生僻字）", "向下完全兼容 GB2312"], ["==GB18030==", "==1、2 或 4 字节变长==", "我国最新国家强制标准，收录 7 万+ 汉字及少数民族文字", "向下兼容 GBK 和 GB2312"], ["==Unicode==", "统一多国语言字符集（UCS-2 / UCS-4）", "为全世界每一种语言的每一个字符赋予全局唯一代码", "代码点空间标准"], ["==UTF-8==", "==1 ~ 4 字节变长编码==", "针对 Unicode 的网络传输编码实现（ASCII 占 1 字节，常见中文占 3 字节）", "==互联网全球统一字符编码标准=="]]}, {"id": "a4-4-1-2-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "汉字换算例题必记", "text": "若汉字“啊”的区位码是 1601（区号 16，位号 01）：\n1. 转为十六进制区位码：16 -> 10H，01 -> 01H，即 `1001H`；\n2. 计算国标码：`1001H + 2020H = 3021H`；\n3. 计算机内码：`3021H + 8080H = B0A1H`（两个字节最高位均为 1）。"}]'::jsonb, '', 'A4-4.1.2 文本的表示与字符编码。 汉字编码体系四码演进与转换公式（专转本每年必考计算） 编码阶段 编码名称 存储/表示形式 换算逻辑与计算公式 1. 输入阶段 输入码（外码） 拼音字母或五笔编码 用于键盘键入识别 2. 区位划分 区位码 2 字节十进制（94 个区，每区 94 个位） 如某汉字区位码为 3045（第 30 区第 45 位） 3. 交换标准 国标码（GB2312） 2 字节十六进制，避开 ASCII 控制字符 国标码 = 区位码（十六进制） + 2020H 4. 内部存储 机内码（内码） 2 字节十六进制，最高位置 1（大于 80H）以区分西文字符 机内码 = 国标码 + 8080H = 区位码（十六进制） + A0A0H 5. 屏幕输出 字形码（字模码） 点阵字形二进制比特串（如 16×16 点阵） 用于字库检索与屏幕笔画显微打印 常用字符集编码标准对比 字符集标准 占用字节数 收录字符范围 兼容性与特点 ASCII 1 字节（最高位置 0，实际用 7 位） 128 个基本字符（数字、英文字母、标点与控制符） 现代字符编码的基石 GB2312-80 2 字节 收录 6763 个简体汉字及 682 个符号 一级汉字按拼音排序，二级汉字按部首笔画排序 GBK 2 字节 收录 21003 个汉字（包含繁体字、生僻字） 向下完全兼容 GB2312 GB18030 1、2 或 4 字节变长 我国最新国家强制标准，收录 7 万+ 汉字及少数民族文字 向下兼容 GBK 和 GB2312 Unicode 统一多国语言字符集（UCS-2 / UCS-4） 为全世界每一种语言的每一个字符赋予全局唯一代码 代码点空间标准 UTF-8 1 ~ 4 字节变长编码 针对 Unicode 的网络传输编码实现（ASCII 占 1 字节，常见中文占 3 字节） 互联网全球统一字符编码标准 汉字换算例题必记 若汉字“啊”的区位码是 1601（区号 16，位号 01）：
1. 转为十六进制区位码：16 -> 10H，01 -> 01H，即 1001H；
2. 计算国标码：1001H + 2020H = 3021H；
3. 计算机内码：3021H + 8080H = B0A1H（两个字节最高位均为 1）。', '{"pdf": "理论复习.pdf", "pages": [67, 68, 69]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.1.3 文本的保存与文本文件的类型。 (node_id=118)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (118, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (118, 1, '[{"id": "a4-4-1-3-b1", "t": "table", "imp": "core", "title": "常见文本文件类型格式对比", "headers": ["文件类型", "扩展名", "是否包含排版格式", "主要特点与典型应用"], "rows": [["==纯文本文件==", "`.txt`", "==纯字符编码，不包含任何字体、字号、颜色等排版格式==", "文件体积最小、平台通用性最好，记事本直接打开"], ["富文本格式", "`.rtf`", "包含跨平台字体、段落排版指令（以控制代码存储）", "微软跨平台文档交换格式"], ["Word 文档", "`.doc` / `.docx`", "高度丰富的图文排版、样式、表格、宏，基于 XML 压缩包封装", "办公文书处理主流标准"], ["超文本标记语言", "`.html` / `.htm`", "利用标签描述超链接、图片排版及多媒体嵌入", "网页展现标准"], ["便携式文档格式", "==`.pdf`==", "==固定版式文档，无论在何种操作系统与打印机上均保持完全一致的排版呈现==", "电子出版、公文下发、学术论文标准"]]}, {"id": "a4-4-1-3-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "PDF 文件的核心优势", "text": "PDF（Portable Document Format）是由 Adobe 开发的电子文件格式，最大优势在于==与操作系统、硬件和显示设备无关，具有版式固化、高保真印刷和防随意篡改性=="}]'::jsonb, '', 'A4-4.1.3 文本的保存与文本文件的类型。 常见文本文件类型格式对比 文件类型 扩展名 是否包含排版格式 主要特点与典型应用 纯文本文件 .txt 纯字符编码，不包含任何字体、字号、颜色等排版格式 文件体积最小、平台通用性最好，记事本直接打开 富文本格式 .rtf 包含跨平台字体、段落排版指令（以控制代码存储） 微软跨平台文档交换格式 Word 文档 .doc / .docx 高度丰富的图文排版、样式、表格、宏，基于 XML 压缩包封装 办公文书处理主流标准 超文本标记语言 .html / .htm 利用标签描述超链接、图片排版及多媒体嵌入 网页展现标准 便携式文档格式 .pdf 固定版式文档，无论在何种操作系统与打印机上均保持完全一致的排版呈现 电子出版、公文下发、学术论文标准 PDF 文件的核心优势 PDF（Portable Document Format）是由 Adobe 开发的电子文件格式，最大优势在于与操作系统、硬件和显示设备无关，具有版式固化、高保真印刷和防随意篡改性', '{"pdf": "理论复习.pdf", "pages": [69, 70]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.1.4 文本的编辑处理，检索与文本的展现。 (node_id=119)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (119, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (119, 1, '[{"id": "a4-4-1-4-b1", "t": "table", "imp": "core", "title": "点阵字形 vs 矢量字形（专转本高频必考计算）", "headers": ["字形技术", "存储记录原理", "放大缩小表现", "字模容量计算公式与经典算例"], "rows": [["==点阵字形（位图字形）==", "用 0/1 像素矩阵表示笔画（0 代表空白，1 代表笔画墨点）", "==放大后笔画出现明显锯齿毛刺，缩小后笔画容易粘连糊成一团==", "==容量 = (水平点数 × 垂直点数) ÷ 8 字节==<br>• 16×16 点阵：16×16÷8 = ==32 字节==<br>• 24×24 点阵：24×24÷8 = ==72 字节==<br>• 32×32 点阵：32×32÷8 = ==128 字节=="], ["==矢量字形（轮廓字形）==", "用数学贝塞尔曲线、直线轮廓方程与填充参数描述笔画", "==任意无级放大、缩小、旋转均平滑清晰，无任何失真变形==", "字体文件小，常用格式：==TrueType（.ttf）、OpenType（.otf）=="]]}, {"id": "a4-4-1-4-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "点阵字库存储容量计算题", "text": "真题：一个包含 6763 个汉字的 16×16 点阵汉字字库，需要占用多少存储空间？\n==计算：6763 × (16×16÷8) 字节 = 6763 × 32 字节 ≈ 216416 字节 ≈ 211.3 KB=="}]'::jsonb, '', 'A4-4.1.4 文本的编辑处理，检索与文本的展现。 点阵字形 vs 矢量字形（专转本高频必考计算） 字形技术 存储记录原理 放大缩小表现 字模容量计算公式与经典算例 点阵字形（位图字形） 用 0/1 像素矩阵表示笔画（0 代表空白，1 代表笔画墨点） 放大后笔画出现明显锯齿毛刺，缩小后笔画容易粘连糊成一团 容量 = (水平点数 × 垂直点数) ÷ 8 字节<br>• 16×16 点阵：16×16÷8 = 32 字节<br>• 24×24 点阵：24×24÷8 = 72 字节<br>• 32×32 点阵：32×32÷8 = 128 字节 矢量字形（轮廓字形） 用数学贝塞尔曲线、直线轮廓方程与填充参数描述笔画 任意无级放大、缩小、旋转均平滑清晰，无任何失真变形 字体文件小，常用格式：TrueType（.ttf）、OpenType（.otf） 点阵字库存储容量计算题 真题：一个包含 6763 个汉字的 16×16 点阵汉字字库，需要占用多少存储空间？
计算：6763 × (16×16÷8) 字节 = 6763 × 32 字节 ≈ 216416 字节 ≈ 211.3 KB', '{"pdf": "理论复习.pdf", "pages": [70]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.2.1 色彩产生，色彩的表达方法，色彩空间。 (node_id=121)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (121, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (121, 1, '[{"id": "a4-4-2-1-b1", "t": "table", "imp": "core", "title": "常见色彩空间模型对比（专转本高频必考）", "headers": ["色彩模型", "三基色 / 组成要素", "色彩合成物理原理", "主要应用领域"], "rows": [["==RGB 模型==", "==红（Red）、绿（Green）、蓝（Blue）==", "==加色法原理==（色光叠加越混越亮，RGB 全为 255 时为白色，全为 0 为黑色）", "==显示器、电视机屏幕、手机屏幕、扫描仪、数码相机等发光显示设备=="], ["==CMYK 模型==", "==青（Cyan）、品红（Magenta）、黄（Yellow）、黑（blacK）==", "==减色法原理==（颜料吸收光线越混越暗，CMY 三色等量混合为深灰色，引入专门黑色 K 提高浓度与节约成本）", "==彩色印刷、彩印机、喷墨打印机、油墨出版物=="], ["==HSB / HSV 模型==", "==色调（Hue）、饱和度（Saturation）、明度（Brightness/Value）==", "符合人类视觉感知心理的色彩描述模型（色调表示颜色种类，饱和度表示纯度）", "艺术设计、Photoshop 调色板选色"], ["==YUV / YIQ 模型==", "==亮度（Y）、色度（U、V）==", "将明暗亮度信号与色彩色度信号完全分离传输，兼容黑白电视", "==彩色电视广播与视频压缩编码（如 MPEG、H.264）=="]]}, {"id": "a4-4-2-1-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "加色法 vs 减色法混淆陷阱", "text": "牢记口诀：==“屏上亮光用 RGB 加色法，纸上油墨用 CMYK 减色法”==。显示器显示纯红+纯绿光混合呈现==黄色（Yellow）==，红+蓝混合呈现==品红（Magenta）==，绿+蓝混合呈现==青色（Cyan）=="}]'::jsonb, '', 'A4-4.2.1 色彩产生，色彩的表达方法，色彩空间。 常见色彩空间模型对比（专转本高频必考） 色彩模型 三基色 / 组成要素 色彩合成物理原理 主要应用领域 RGB 模型 红（Red）、绿（Green）、蓝（Blue） 加色法原理（色光叠加越混越亮，RGB 全为 255 时为白色，全为 0 为黑色） 显示器、电视机屏幕、手机屏幕、扫描仪、数码相机等发光显示设备 CMYK 模型 青（Cyan）、品红（Magenta）、黄（Yellow）、黑（blacK） 减色法原理（颜料吸收光线越混越暗，CMY 三色等量混合为深灰色，引入专门黑色 K 提高浓度与节约成本） 彩色印刷、彩印机、喷墨打印机、油墨出版物 HSB / HSV 模型 色调（Hue）、饱和度（Saturation）、明度（Brightness/Value） 符合人类视觉感知心理的色彩描述模型（色调表示颜色种类，饱和度表示纯度） 艺术设计、Photoshop 调色板选色 YUV / YIQ 模型 亮度（Y）、色度（U、V） 将明暗亮度信号与色彩色度信号完全分离传输，兼容黑白电视 彩色电视广播与视频压缩编码（如 MPEG、H.264） 加色法 vs 减色法混淆陷阱 牢记口诀：“屏上亮光用 RGB 加色法，纸上油墨用 CMYK 减色法”。显示器显示纯红+纯绿光混合呈现黄色（Yellow），红+蓝混合呈现品红（Magenta），绿+蓝混合呈现青色（Cyan）', '{"pdf": "理论复习.pdf", "pages": [70, 71]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.2.2 数字图像的获取与重现。 (node_id=122)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (122, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (122, 1, '[{"id": "a4-4-2-2-b1", "t": "table", "imp": "core", "title": "常见图像输入与采集设备核心部件", "headers": ["设备名称", "核心图像传感器", "主要性能指标", "特点与工作机制"], "rows": [["==数码相机（Digital Camera）==", "==CCD（电荷耦合器件）或 CMOS（互补金属氧化物半导体）==", "有效像素数（如 4800 万像素）、光学变焦倍数、感光度 ISO", "通过透镜成像在感光阵列上，直接转换为数字信号存储在闪存卡中"], ["==平板扫描仪（Scanner）==", "线性 CCD 感光阵列与步进电机、冷阴极荧光灯/LED 光源", "==光学分辨率（DPI，点每英寸）==、色彩位数（如 48 位色）", "对平面印刷照片、图纸逐行扫描采样输入"], ["智能手机摄像头", "高灵敏度背照式 CMOS、ISP 图像信号处理器", "大光圈、多摄组合、计算摄影与防抖算法", "集成度极高，随身便携拍摄"]]}, {"id": "a4-4-2-2-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "CCD vs CMOS 传感器", "text": "CCD 成像质量高、噪点低，但功耗高、制造工艺昂贵；==CMOS 功耗低、成本低、集成度高，已成为现代手机和绝大多数数码相机的主流感光元件=="}]'::jsonb, '', 'A4-4.2.2 数字图像的获取与重现。 常见图像输入与采集设备核心部件 设备名称 核心图像传感器 主要性能指标 特点与工作机制 数码相机（Digital Camera） CCD（电荷耦合器件）或 CMOS（互补金属氧化物半导体） 有效像素数（如 4800 万像素）、光学变焦倍数、感光度 ISO 通过透镜成像在感光阵列上，直接转换为数字信号存储在闪存卡中 平板扫描仪（Scanner） 线性 CCD 感光阵列与步进电机、冷阴极荧光灯/LED 光源 光学分辨率（DPI，点每英寸）、色彩位数（如 48 位色） 对平面印刷照片、图纸逐行扫描采样输入 智能手机摄像头 高灵敏度背照式 CMOS、ISP 图像信号处理器 大光圈、多摄组合、计算摄影与防抖算法 集成度极高，随身便携拍摄 CCD vs CMOS 传感器 CCD 成像质量高、噪点低，但功耗高、制造工艺昂贵；CMOS 功耗低、成本低、集成度高，已成为现代手机和绝大多数数码相机的主流感光元件', '{"pdf": "理论复习.pdf", "pages": [71, 72]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.2.3 模拟图像的数字化过程。 (node_id=123)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (123, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (123, 1, '[{"id": "a4-4-2-3-b1", "t": "table", "imp": "core", "title": "图像数字化三大核心步骤（空间离散化与色彩离散化）", "headers": ["步骤序号", "处理步骤名称", "物理本质与处理动作", "直接决定的技术指标"], "rows": [["1", "==采样（Sampling）==", "将连续二维空间坐标分割为离散规则网格点（网格越密，像素越多）", "==决定图像的分辨率（水平像素 × 垂直像素，如 1920×1080）=="], ["2", "==量化（Quantization）==", "将每个像素点上的连续模拟亮度和色彩强度取值近似为有限个离散整数级", "==决定图像的色彩深度（像素深度，如 8 位、24 位真彩色）=="], ["3", "==编码（Encoding）==", "将量化后的数值按照特定格式转换为二进制计算机代码并予以排列压缩", "决定图像的文件存储格式与压缩比率（如 BMP、JPEG）"]]}, {"id": "a4-4-2-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "采样与量化对应关系常考", "text": "专转本必考题：==“采样”是将空间连续的图像离散化为像素点（影响分辨率）；“量化”是将连续的明暗与色彩离散化为阶梯数值（影响色彩深度/颜色丰富度）=="}]'::jsonb, '', 'A4-4.2.3 模拟图像的数字化过程。 图像数字化三大核心步骤（空间离散化与色彩离散化） 步骤序号 处理步骤名称 物理本质与处理动作 直接决定的技术指标 1 采样（Sampling） 将连续二维空间坐标分割为离散规则网格点（网格越密，像素越多） 决定图像的分辨率（水平像素 × 垂直像素，如 1920×1080） 2 量化（Quantization） 将每个像素点上的连续模拟亮度和色彩强度取值近似为有限个离散整数级 决定图像的色彩深度（像素深度，如 8 位、24 位真彩色） 3 编码（Encoding） 将量化后的数值按照特定格式转换为二进制计算机代码并予以排列压缩 决定图像的文件存储格式与压缩比率（如 BMP、JPEG） 采样与量化对应关系常考 专转本必考题：“采样”是将空间连续的图像离散化为像素点（影响分辨率）；“量化”是将连续的明暗与色彩离散化为阶梯数值（影响色彩深度/颜色丰富度）', '{"pdf": "理论复习.pdf", "pages": [72]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.2.4 数字图像的表示及存储数据量的计算，压缩编码类型，数字图像的性能指标。 (node_id=124)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (124, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (124, 1, '[{"id": "a4-4-2-4-b1", "t": "callout", "imp": "core", "kind": "tip", "title": "数字图像未压缩数据量黄金计算公式（每年必考计算大题）", "text": "==图像存储容量（字节 Byte） = (水平像素点数 × 垂直像素点数 × 像素色彩深度 bit) ÷ 8==\n若要求换算为 KB，除以 1024；若要求换算为 MB，再除以 1024。"}, {"id": "a4-4-2-4-b2", "t": "table", "imp": "core", "title": "常用色彩深度与单像素占用位数对应表", "headers": ["色彩类型", "色彩深度（bpp）", "能表达的最大颜色种类数", "每个像素占用字节数"], "rows": [["==黑白二值图==", "==1 bit==", "2^1 = 2 种（纯黑与纯白）", "1/8 字节"], ["==16 色图==", "==4 bit==", "2^4 = 16 种颜色", "0.5 字节"], ["==256 色图 / 256级灰度图==", "==8 bit==", "2^8 = 256 种颜色 / 灰阶", "1 字节"], ["65536 增强色（高彩色）", "16 bit", "2^16 = 65536 种颜色", "2 字节"], ["==真彩色（True Color）==", "==24 bit==", "2^24 = 16777216 种颜色（约 1677 万色，人眼极限）", "==3 字节（R/G/B 各占 8 位）=="], ["32 位带透明度（RGBA）", "32 bit", "1677 万色 + 256 级 Alpha 透明度", "4 字节"]]}, {"id": "a4-4-2-4-b3", "t": "table", "imp": "core", "title": "无损压缩 vs 有损压缩核心对比", "headers": ["对比项", "==无损压缩（Lossless）==", "==有损压缩（Lossy）=="], "rows": [["==数据还原保真度==", "==完全无损，解压缩后数据与原始数据 100% 毫无差异==", "==存在失真，丢弃人眼视觉不敏感的高频细节，无法完全还原原始数据=="], ["==压缩比率==", "压缩比较低（通常为 2:1 ~ 4:1）", "==压缩比极高（可达 10:1 到 50:1 以上）=="], ["==常用算法与格式==", "==Huffman 编码、行程编码（RLE）、LZW 字典编码；BMP、PNG、GIF、TIFF==", "==离散余弦变换（DCT）、小波变换；JPEG、MP3、MPEG 视频=="]]}]'::jsonb, '', 'A4-4.2.4 数字图像的表示及存储数据量的计算，压缩编码类型，数字图像的性能指标。 数字图像未压缩数据量黄金计算公式（每年必考计算大题） 图像存储容量（字节 Byte） = (水平像素点数 × 垂直像素点数 × 像素色彩深度 bit) ÷ 8
若要求换算为 KB，除以 1024；若要求换算为 MB，再除以 1024。 常用色彩深度与单像素占用位数对应表 色彩类型 色彩深度（bpp） 能表达的最大颜色种类数 每个像素占用字节数 黑白二值图 1 bit 2^1 = 2 种（纯黑与纯白） 1/8 字节 16 色图 4 bit 2^4 = 16 种颜色 0.5 字节 256 色图 / 256级灰度图 8 bit 2^8 = 256 种颜色 / 灰阶 1 字节 65536 增强色（高彩色） 16 bit 2^16 = 65536 种颜色 2 字节 真彩色（True Color） 24 bit 2^24 = 16777216 种颜色（约 1677 万色，人眼极限） 3 字节（R/G/B 各占 8 位） 32 位带透明度（RGBA） 32 bit 1677 万色 + 256 级 Alpha 透明度 4 字节 无损压缩 vs 有损压缩核心对比 对比项 无损压缩（Lossless） 有损压缩（Lossy） 数据还原保真度 完全无损，解压缩后数据与原始数据 100% 毫无差异 存在失真，丢弃人眼视觉不敏感的高频细节，无法完全还原原始数据 压缩比率 压缩比较低（通常为 2:1 ~ 4:1） 压缩比极高（可达 10:1 到 50:1 以上） 常用算法与格式 Huffman 编码、行程编码（RLE）、LZW 字典编码；BMP、PNG、GIF、TIFF 离散余弦变换（DCT）、小波变换；JPEG、MP3、MPEG 视频', '{"pdf": "理论复习.pdf", "pages": [72, 73]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.2.5 常用图像文件格式，数字图像处理及应用，常用软件。 (node_id=125)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (125, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (125, 1, '[{"id": "a4-4-2-5-b1", "t": "table", "imp": "core", "title": "常见位图图像文件格式特性全览（专转本高频必背）", "headers": ["格式扩展名", "压缩类型", "色彩深度支持", "核心特点与最佳应用场景"], "rows": [["==BMP==", "通常无压缩", "1 ~ 32 位", "Windows 操作系统标准位图格式，未压缩，文件体积最大"], ["==JPEG / JPG==", "==有损压缩（基于 DCT 变换）==", "==24 位真彩色==", "==文件体积小、特别适合保存色彩丰富细腻的自然风景与人物摄影照片；不支持透明通道、不支持动画=="], ["==PNG==", "==无损压缩（基于 LZ77 算法）==", "最高 48 位", "==支持 Alpha 渐变透明通道（透明背景）、无损高保真，Web UI 图标及线条插画首选=="], ["==GIF==", "==无损压缩（基于 LZW 编码）==", "==最大仅支持 8 位（256 色）==", "==支持多帧动态图片播放（动图表情包）、支持简单单色透明=="], ["TIFF", "可选无损或有损", "支持高位深与 CMYK", "高保真专业印刷出版、医学影像与扫描存档"], ["WebP", "Google 开发，支持有损/无损", "24/32 位", "全面兼顾高压缩率、透明通道与动图，现代新一代 Web 图像格式"]]}, {"id": "a4-4-2-5-b2", "t": "list", "imp": "important", "title": "主流数字图像处理软件代表", "items": ["位图专业处理软件：==Adobe Photoshop（行业霸主，专业图像精修合成）、GIMP（开源跨平台图像处理神器）==", "常用基础图像处理操作：色彩与对比度校正、几何旋转裁剪、滤波降噪与锐化、仿制图章去瑕疵、图层混合与抠图蒙版"]}]'::jsonb, '', 'A4-4.2.5 常用图像文件格式，数字图像处理及应用，常用软件。 常见位图图像文件格式特性全览（专转本高频必背） 格式扩展名 压缩类型 色彩深度支持 核心特点与最佳应用场景 BMP 通常无压缩 1 ~ 32 位 Windows 操作系统标准位图格式，未压缩，文件体积最大 JPEG / JPG 有损压缩（基于 DCT 变换） 24 位真彩色 文件体积小、特别适合保存色彩丰富细腻的自然风景与人物摄影照片；不支持透明通道、不支持动画 PNG 无损压缩（基于 LZ77 算法） 最高 48 位 支持 Alpha 渐变透明通道（透明背景）、无损高保真，Web UI 图标及线条插画首选 GIF 无损压缩（基于 LZW 编码） 最大仅支持 8 位（256 色） 支持多帧动态图片播放（动图表情包）、支持简单单色透明 TIFF 可选无损或有损 支持高位深与 CMYK 高保真专业印刷出版、医学影像与扫描存档 WebP Google 开发，支持有损/无损 24/32 位 全面兼顾高压缩率、透明通道与动图，现代新一代 Web 图像格式 主流数字图像处理软件代表 位图专业处理软件：Adobe Photoshop（行业霸主，专业图像精修合成）、GIMP（开源跨平台图像处理神器） 常用基础图像处理操作：色彩与对比度校正、几何旋转裁剪、滤波降噪与锐化、仿制图章去瑕疵、图层混合与抠图蒙版', '{"pdf": "理论复习.pdf", "pages": [73, 74]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.2.6 计算机合成图像，合成过程，优点，常见的绘图软件。 (node_id=126)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (126, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (126, 1, '[{"id": "a4-4-2-6-b1", "t": "table", "imp": "core", "title": "位图（点阵图） vs 矢量图（图形）核心终极对比（专转本必考题）", "headers": ["对比项", "==位图（点阵图像，Image）==", "==矢量图（计算机绘图，Graphic）=="], "rows": [["==基本组成单元==", "==像素点阵（Pixel）==", "==几何数学图形基元（直线、圆、椭圆、贝塞尔曲线等轮廓方程）=="], ["==放大缩放表现==", "==放大后出现明显马赛克方块和边缘锯齿模糊==", "==无限放大缩小旋转，边缘始终绝对平滑清晰，无任何失真=="], ["==文件体积大小==", "与图像尺寸（像素数）成正比，通常体积很大", "与图形尺寸大小无关，仅取决于图形元素复杂程度，==文件体积非常小=="], ["==表现色彩层次==", "擅长表现色彩极其丰富、层次细腻复杂的情景（如真实照片）", "擅长展现规整轮廓、平滑色块，难表现复杂色彩光影过渡"], ["==常见文件格式==", "==BMP, JPEG, PNG, GIF, TIFF==", "==SVG, AI, CDR, WMF, EPS, DXF=="], ["==主流编辑软件==", "==Photoshop, GIMP==", "==Adobe Illustrator（AI）, CorelDRAW, AutoCAD=="]]}, {"id": "a4-4-2-6-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "记忆口诀", "text": "==“位图由像素组成，放大失真变模糊；矢量图由数学指令描述，无限放大依然清晰！”== 工程图纸、Logo 商标、字体通常必须设计为矢量图。"}]'::jsonb, '', 'A4-4.2.6 计算机合成图像，合成过程，优点，常见的绘图软件。 位图（点阵图） vs 矢量图（图形）核心终极对比（专转本必考题） 对比项 位图（点阵图像，Image） 矢量图（计算机绘图，Graphic） 基本组成单元 像素点阵（Pixel） 几何数学图形基元（直线、圆、椭圆、贝塞尔曲线等轮廓方程） 放大缩放表现 放大后出现明显马赛克方块和边缘锯齿模糊 无限放大缩小旋转，边缘始终绝对平滑清晰，无任何失真 文件体积大小 与图像尺寸（像素数）成正比，通常体积很大 与图形尺寸大小无关，仅取决于图形元素复杂程度，文件体积非常小 表现色彩层次 擅长表现色彩极其丰富、层次细腻复杂的情景（如真实照片） 擅长展现规整轮廓、平滑色块，难表现复杂色彩光影过渡 常见文件格式 BMP, JPEG, PNG, GIF, TIFF SVG, AI, CDR, WMF, EPS, DXF 主流编辑软件 Photoshop, GIMP Adobe Illustrator（AI）, CorelDRAW, AutoCAD 记忆口诀 “位图由像素组成，放大失真变模糊；矢量图由数学指令描述，无限放大依然清晰！” 工程图纸、Logo 商标、字体通常必须设计为矢量图。', '{"pdf": "理论复习.pdf", "pages": [74]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.3.1 模拟声音信号的数字化。 (node_id=128)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (128, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (128, 1, '[{"id": "a4-4-3-1-b1", "t": "table", "imp": "core", "title": "声音信号数字化三大步骤（PCM 脉冲编码调制）", "headers": ["数字化步骤", "操作定义与物理本质", "专转本核心定理与重要参数"], "rows": [["1. ==采样（Sampling）==", "按固定时间间隔测定模拟声波电压瞬时值", "==奈奎斯特采样定理（Nyquist）：采样频率 fs 必须大于等于信号最高频率 fmax 的 2 倍（fs ≥ 2 fmax），才能完整无失真还原原始信号=="], ["2. ==量化（Quantization）==", "将采样得到的连续电平幅值转换为有限级离散二进制整数", "==量化位数（Resolution）：通常为 8 位、16 位（CD 标准）或 24 位；位数越高，动态范围越大、量化噪声越小=="], ["3. ==编码（Encoding）==", "将量化后的离散等级数值转换为二进制代码比特流写入文件", "输出未压缩的 PCM 原始波形音频流（如 `.wav` 文件）"]]}, {"id": "a4-4-3-1-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "人耳听觉范围与 CD 采样率标准考点", "text": "人耳可听到的音频频率范围为 ==20 Hz ~ 20 kHz（20000 Hz）==。\n根据采样定理，为无失真捕捉人耳极限声音（20 kHz），采样率至少需 40 kHz。因此国际标准音乐 CD 采用了 ==44.1 kHz 采样频率、16 位量化深度、双声道立体声==的标准。"}]'::jsonb, '', 'A4-4.3.1 模拟声音信号的数字化。 声音信号数字化三大步骤（PCM 脉冲编码调制） 数字化步骤 操作定义与物理本质 专转本核心定理与重要参数 1. 采样（Sampling） 按固定时间间隔测定模拟声波电压瞬时值 奈奎斯特采样定理（Nyquist）：采样频率 fs 必须大于等于信号最高频率 fmax 的 2 倍（fs ≥ 2 fmax），才能完整无失真还原原始信号 2. 量化（Quantization） 将采样得到的连续电平幅值转换为有限级离散二进制整数 量化位数（Resolution）：通常为 8 位、16 位（CD 标准）或 24 位；位数越高，动态范围越大、量化噪声越小 3. 编码（Encoding） 将量化后的离散等级数值转换为二进制代码比特流写入文件 输出未压缩的 PCM 原始波形音频流（如 .wav 文件） 人耳听觉范围与 CD 采样率标准考点 人耳可听到的音频频率范围为 20 Hz ~ 20 kHz（20000 Hz）。
根据采样定理，为无失真捕捉人耳极限声音（20 kHz），采样率至少需 40 kHz。因此国际标准音乐 CD 采用了 44.1 kHz 采样频率、16 位量化深度、双声道立体声的标准。', '{"pdf": "理论复习.pdf", "pages": [74, 75]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.3.2 波形声音的获取设备，波形声音的表示及存储数据量的计算，压缩编码和编辑。 (node_id=129)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (129, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (129, 1, '[{"id": "a4-4-3-2-b1", "t": "callout", "imp": "core", "kind": "tip", "title": "波形声音数据量计算黄金公式（每考必考大题）", "text": "==音频数据量（字节 Byte） = (采样频率 Hz × 量化位数 bit × 声道数 × 播放时间 s) ÷ 8==\n• 单声道：声道数 = 1；双声道（立体声）：声道数 = 2；\n• 注意采样频率单位转换：44.1 kHz = 44100 Hz。"}, {"id": "a4-4-3-2-b2", "t": "table", "imp": "core", "title": "经典 CD 音质数据率与典型容量算例", "headers": ["参数项目", "标准参数取值", "计算过程与结果"], "rows": [["==标准 CD 规格参数==", "采样率 44.1 kHz，量化深度 16 位，双声道", "1 秒数据量 = 44100 × 16 × 2 × 1 ÷ 8 = ==176,400 字节/秒 ≈ 172.27 KB/s=="], ["标准 CD 音频码率", "按 bps（比特/秒）计算", "码率 = 44100 × 16 × 2 = ==1411.2 kbps（即 1.411 Mbps）=="], ["1 小时 CD 音乐容量", "时间 = 3600 秒", "176400 × 3600 ÷ 1024 ÷ 1024 ≈ ==605.6 MB（一张 700MB CD 盘刚好容纳约 70 分钟）=="]]}, {"id": "a4-4-3-2-b3", "t": "table", "imp": "core", "title": "常见音频文件格式与压缩特性", "headers": ["音频格式", "压缩类型", "核心技术与特点", "应用领域"], "rows": [["==WAV==", "通常无压缩", "Windows 标准原始 PCM 波形音频，体积巨大，音质最纯正", "专业音乐母带剪辑"], ["==MP3==", "==有损压缩（MPEG Audio Layer 3）==", "利用人眼人耳心理声学模型遮蔽效应压缩，==压缩比达 10:1 到 12:1==，音质接近 CD", "便携音乐、网络流传"], ["==FLAC / APE==", "==无损压缩==", "将原始波形无损压缩约 50% 体积，解压后 100% 还原 CD 音质", "发烧级 Hi-Fi 音乐分享"], ["AAC", "先进有损压缩", "同码率下音质优于 MP3，苹果 Apple Music 默认采用", "手机无线耳机蓝牙传输"]]}]'::jsonb, '', 'A4-4.3.2 波形声音的获取设备，波形声音的表示及存储数据量的计算，压缩编码和编辑。 波形声音数据量计算黄金公式（每考必考大题） 音频数据量（字节 Byte） = (采样频率 Hz × 量化位数 bit × 声道数 × 播放时间 s) ÷ 8
• 单声道：声道数 = 1；双声道（立体声）：声道数 = 2；
• 注意采样频率单位转换：44.1 kHz = 44100 Hz。 经典 CD 音质数据率与典型容量算例 参数项目 标准参数取值 计算过程与结果 标准 CD 规格参数 采样率 44.1 kHz，量化深度 16 位，双声道 1 秒数据量 = 44100 × 16 × 2 × 1 ÷ 8 = 176,400 字节/秒 ≈ 172.27 KB/s 标准 CD 音频码率 按 bps（比特/秒）计算 码率 = 44100 × 16 × 2 = 1411.2 kbps（即 1.411 Mbps） 1 小时 CD 音乐容量 时间 = 3600 秒 176400 × 3600 ÷ 1024 ÷ 1024 ≈ 605.6 MB（一张 700MB CD 盘刚好容纳约 70 分钟） 常见音频文件格式与压缩特性 音频格式 压缩类型 核心技术与特点 应用领域 WAV 通常无压缩 Windows 标准原始 PCM 波形音频，体积巨大，音质最纯正 专业音乐母带剪辑 MP3 有损压缩（MPEG Audio Layer 3） 利用人眼人耳心理声学模型遮蔽效应压缩，压缩比达 10:1 到 12:1，音质接近 CD 便携音乐、网络流传 FLAC / APE 无损压缩 将原始波形无损压缩约 50% 体积，解压后 100% 还原 CD 音质 发烧级 Hi-Fi 音乐分享 AAC 先进有损压缩 同码率下音质优于 MP3，苹果 Apple Music 默认采用 手机无线耳机蓝牙传输', '{"pdf": "理论复习.pdf", "pages": [75, 76]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.3.3 计算机合成声音的制作与播放。 (node_id=130)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (130, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (130, 1, '[{"id": "a4-4-3-3-b1", "t": "table", "imp": "core", "title": "波形声音（WAV/MP3） vs MIDI 音乐核心对比（必考常客）", "headers": ["对比项", "==波形声音（Wave Audio）==", "==MIDI 音乐（电子乐器数字接口）=="], "rows": [["==记录本质==", "==记录实际声音信号采样量化后的真实波形比特流==", "==不记录任何声波信号，仅记录演奏乐谱控制指令（乐器编号、音符音调、按键力度、时长）=="], ["==文件体积==", "文件数据量非常大（即便压缩也需要几 MB ~ 几十 MB）", "==文件极其微小，一首几分钟的完整交响乐 MIDI 文件仅几十 KB=="], ["==回放音质依赖==", "回放音质完全保真确定，不依赖声卡硬件性能", "==回放音质严重依赖声卡内置的音色库（波表音色库质量越高，还原越逼真）=="], ["==声音类型适用==", "可以记录任何自然界的任意声音（人声清唱、鸟鸣、风雨声）", "==只能合成演奏乐器乐曲，无法合成自然人声语言语音=="]]}, {"id": "a4-4-3-3-b2", "t": "list", "imp": "core", "title": "计算机语音合成（TTS）技术", "items": ["==文语转换（TTS，Text-To-Speech）==：将任意书面文本自动合成为流畅自然的语音输出", "核心工作机制：文本语言学分析（词性、分词、重音、停顿预测） -> 声学模型预测声学特征 -> 神经声码器（如 WaveNet）合成逼真波形", "典型应用：智能导航语音播报、视障人士屏幕朗读软件、有声书智能主播"]}]'::jsonb, '', 'A4-4.3.3 计算机合成声音的制作与播放。 波形声音（WAV/MP3） vs MIDI 音乐核心对比（必考常客） 对比项 波形声音（Wave Audio） MIDI 音乐（电子乐器数字接口） 记录本质 记录实际声音信号采样量化后的真实波形比特流 不记录任何声波信号，仅记录演奏乐谱控制指令（乐器编号、音符音调、按键力度、时长） 文件体积 文件数据量非常大（即便压缩也需要几 MB ~ 几十 MB） 文件极其微小，一首几分钟的完整交响乐 MIDI 文件仅几十 KB 回放音质依赖 回放音质完全保真确定，不依赖声卡硬件性能 回放音质严重依赖声卡内置的音色库（波表音色库质量越高，还原越逼真） 声音类型适用 可以记录任何自然界的任意声音（人声清唱、鸟鸣、风雨声） 只能合成演奏乐器乐曲，无法合成自然人声语言语音 计算机语音合成（TTS）技术 文语转换（TTS，Text-To-Speech）：将任意书面文本自动合成为流畅自然的语音输出 核心工作机制：文本语言学分析（词性、分词、重音、停顿预测） -> 声学模型预测声学特征 -> 神经声码器（如 WaveNet）合成逼真波形 典型应用：智能导航语音播报、视障人士屏幕朗读软件、有声书智能主播', '{"pdf": "理论复习.pdf", "pages": [76, 77]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.4.1 视频信号的组成、原理，彩色电视的三种制式。 (node_id=132)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (132, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (132, 1, '[{"id": "a4-4-4-1-b1", "t": "p", "imp": "core", "title": "活动视频的生理视觉原理", "text": "活动视频和电影的连续动态呈现是基于人类眼睛的==“视觉暂留（Persistence of Vision）”效应==（光线停止刺激后，视网膜上影像仍会保留约 0.05 ~ 0.2 秒）。当以每秒大于 ==24 帧（fps）==的速度连续播放静止图像序列时，人眼视觉大脑就会感知为流畅平滑的连续动态画面。"}, {"id": "a4-4-4-1-b2", "t": "table", "imp": "core", "title": "全球彩色电视三大传统广播制式（专转本高频必背）", "headers": ["电视制式", "中文名称", "帧率（帧/秒）", "扫描行数", "主要采用国家 / 地区"], "rows": [["==PAL 制式==", "逐行倒相正交平衡调幅制", "==25 fps==", "==625 行==", "==中国、英国、德国、澳大利亚及西欧多数国家=="], ["==NTSC 制式==", "国家电视系统委员会制式", "==30 fps（实际 29.97）==", "==525 行==", "==美国、日本、加拿大、韩国及中国台湾地区=="], ["==SECAM 制式==", "顺序传送彩色与存储制", "==25 fps==", "==625 行==", "==法国、俄罗斯及部分东欧、非洲国家=="]]}, {"id": "a4-4-4-1-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "我国采用的电视制式", "text": "专转本常考单选题：==中国广播电视采用的是 PAL 制式，其刷新帧率为每秒 25 帧，扫描行数为 625 行=="}]'::jsonb, '', 'A4-4.4.1 视频信号的组成、原理，彩色电视的三种制式。 活动视频的生理视觉原理 活动视频和电影的连续动态呈现是基于人类眼睛的“视觉暂留（Persistence of Vision）”效应（光线停止刺激后，视网膜上影像仍会保留约 0.05 ~ 0.2 秒）。当以每秒大于 24 帧（fps）的速度连续播放静止图像序列时，人眼视觉大脑就会感知为流畅平滑的连续动态画面。 全球彩色电视三大传统广播制式（专转本高频必背） 电视制式 中文名称 帧率（帧/秒） 扫描行数 主要采用国家 / 地区 PAL 制式 逐行倒相正交平衡调幅制 25 fps 625 行 中国、英国、德国、澳大利亚及西欧多数国家 NTSC 制式 国家电视系统委员会制式 30 fps（实际 29.97） 525 行 美国、日本、加拿大、韩国及中国台湾地区 SECAM 制式 顺序传送彩色与存储制 25 fps 625 行 法国、俄罗斯及部分东欧、非洲国家 我国采用的电视制式 专转本常考单选题：中国广播电视采用的是 PAL 制式，其刷新帧率为每秒 25 帧，扫描行数为 625 行', '{"pdf": "理论复习.pdf", "pages": [78, 79]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.4.2 数字视频的获取、播放。 (node_id=133)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (133, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (133, 1, '[{"id": "a4-4-4-2-b1", "t": "table", "imp": "core", "title": "数字视频获取设备与播放架构", "headers": ["环节角色", "典型硬件设备/软件工具", "核心功能与技术指标"], "rows": [["==数字视频采集输入==", "数码摄像机、手机摄像头、PCI-E 视频采集卡", "支持 1080P / 4K 高分辨率、60/120fps 高帧率无损捕获与硬件实时压流"], ["==视频解码与播放==", "VLC Player、PotPlayer、手机视频 App", "包含==解复用器（拆出音视频轨）、视频解码器（H.264/HEVC）、音频解码器、渲染输出引擎=="], ["硬件加速渲染", "GPU 内置硬件编解码器（NVENC/QuickSync）", "利用图形显卡硬件专用 ASIC 芯片硬解 4K/8K 视频，CPU 占用率直降到 5% 以下"]]}, {"id": "a4-4-4-2-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "硬解 vs 软解", "text": "==软解（CPU 解码）==通过软件算法占用 CPU 密集运算，耗电高易发热卡顿；==硬解（GPU 解码）==调用显卡独立硬件视频解码单元，高效流畅极其省电。"}]'::jsonb, '', 'A4-4.4.2 数字视频的获取、播放。 数字视频获取设备与播放架构 环节角色 典型硬件设备/软件工具 核心功能与技术指标 数字视频采集输入 数码摄像机、手机摄像头、PCI-E 视频采集卡 支持 1080P / 4K 高分辨率、60/120fps 高帧率无损捕获与硬件实时压流 视频解码与播放 VLC Player、PotPlayer、手机视频 App 包含解复用器（拆出音视频轨）、视频解码器（H.264/HEVC）、音频解码器、渲染输出引擎 硬件加速渲染 GPU 内置硬件编解码器（NVENC/QuickSync） 利用图形显卡硬件专用 ASIC 芯片硬解 4K/8K 视频，CPU 占用率直降到 5% 以下 硬解 vs 软解 软解（CPU 解码）通过软件算法占用 CPU 密集运算，耗电高易发热卡顿；硬解（GPU 解码）调用显卡独立硬件视频解码单元，高效流畅极其省电。', '{"pdf": "理论复习.pdf", "pages": [79, 80]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.4.3 视频信号的数字化。 (node_id=134)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (134, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (134, 1, '[{"id": "a4-4-4-3-b1", "t": "table", "imp": "core", "title": "视频数字化中的 YUV 色彩空间与下采样格式", "headers": ["YUV 下采样格式", "采样比例内涵", "数据量相比 RGB 的压缩率", "典型应用领域"], "rows": [["==YUV 4:4:4==", "每个像素均拥有完整的 Y（亮度）、U（色度）、V（色度）分量", "无压缩，与 RGB 24位真彩色等量", "电影后期调色、无损高保真监视"], ["==YUV 4:2:2==", "水平方向每两个像素共享一组 UV 色度分量，亮度分量 Y 保持全采样", "数据量减小至原始 RGB 的 2/3（66.7%）", "专业广播级高清电视摄像"], ["==YUV 4:2:0==", "水平和垂直方向每 4 个相邻像素共享一组 UV 色度分量", "==数据量减小至原始 RGB 的 1/2（50%）==", "==绝大多数网络视频、DVD、蓝光、H.264/HEVC 消费级视频默认标准=="]]}, {"id": "a4-4-4-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "为什么采用 YUV 4:2:0 压缩？", "text": "生理学依据：==人眼视觉系统对“明暗细节（亮度 Y）”极其敏感，而对“色彩细节（色度 UV）”相对迟钝==。因此大幅降低色度采样率不会被人眼察觉，却能在源头上直接砍掉 50% 原始数据量。"}]'::jsonb, '', 'A4-4.4.3 视频信号的数字化。 视频数字化中的 YUV 色彩空间与下采样格式 YUV 下采样格式 采样比例内涵 数据量相比 RGB 的压缩率 典型应用领域 YUV 4:4:4 每个像素均拥有完整的 Y（亮度）、U（色度）、V（色度）分量 无压缩，与 RGB 24位真彩色等量 电影后期调色、无损高保真监视 YUV 4:2:2 水平方向每两个像素共享一组 UV 色度分量，亮度分量 Y 保持全采样 数据量减小至原始 RGB 的 2/3（66.7%） 专业广播级高清电视摄像 YUV 4:2:0 水平和垂直方向每 4 个相邻像素共享一组 UV 色度分量 数据量减小至原始 RGB 的 1/2（50%） 绝大多数网络视频、DVD、蓝光、H.264/HEVC 消费级视频默认标准 为什么采用 YUV 4:2:0 压缩？ 生理学依据：人眼视觉系统对“明暗细节（亮度 Y）”极其敏感，而对“色彩细节（色度 UV）”相对迟钝。因此大幅降低色度采样率不会被人眼察觉，却能在源头上直接砍掉 50% 原始数据量。', '{"pdf": "理论复习.pdf", "pages": [80, 81]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.4.4 数字视频存储数据量的计算、压缩编码、编辑和应用。 (node_id=135)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (135, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (135, 1, '[{"id": "a4-4-4-4-b1", "t": "callout", "imp": "core", "kind": "tip", "title": "数字视频未压缩存储数据量计算公式（专转本高频必考）", "text": "==未压缩视频数据量（字节） = 单帧图像数据量 × 帧率（fps） × 播放时间（秒）==\n即：==[(水平像素 × 垂直像素 × 色彩深度 bit) ÷ 8] × 帧率 × 时间=="}, {"id": "a4-4-4-4-b2", "t": "table", "imp": "core", "title": "视频压缩核心概念：I 帧、P 帧、B 帧（MPEG 核心帧类型）", "headers": ["帧类型名称", "英文全称", "压缩参考原理与特性", "压缩率与重要性"], "rows": [["==I 帧（关键帧）==", "Intra-coded Picture", "==帧内压缩图像，不依赖任何前后帧，自身包含完整画面数据==", "压缩比最小（体积最大），但==是解码和快速跳转定位的基准，必须首先解码=="], ["==P 帧（前向预测帧）==", "Predictive-coded Picture", "参考其前面的一个 I 帧或 P 帧，仅记录与前帧的差值变化（运动补偿）", "压缩比高，体积居中"], ["==B 帧（双向预测帧）==", "Bi-directional Predictive", "==同时参考前面的前向帧和后面的后向帧进行双向插值预测==", "==压缩比最高（体积最小），但解码时需要前后帧都到位才能解码=="]]}, {"id": "a4-4-4-4-b3", "t": "table", "imp": "core", "title": "主流视频编码标准与文件封装容器格式区分", "headers": ["对比维度", "常见类别与代表", "核心说明与常考点"], "rows": [["==视频编码标准（编解码算法）==", "==MPEG-1 (VCD), MPEG-2 (DVD), MPEG-4, H.264/AVC, H.265/HEVC, AV1==", "定义视频像素的压缩数学算法；H.265 比 H.264 在同等画质下节约约 50% 带宽"], ["==视频封装容器格式（文件后缀）==", "==MP4 (.mp4), AVI (.avi), MKV (.mkv), MOV (.mov), FLV (.flv)==", "==外壳包装盒==：将视频轨、音频轨、字幕轨及元数据打包封装进同一个文件中"]]}]'::jsonb, '', 'A4-4.4.4 数字视频存储数据量的计算、压缩编码、编辑和应用。 数字视频未压缩存储数据量计算公式（专转本高频必考） 未压缩视频数据量（字节） = 单帧图像数据量 × 帧率（fps） × 播放时间（秒）
即：[(水平像素 × 垂直像素 × 色彩深度 bit) ÷ 8] × 帧率 × 时间 视频压缩核心概念：I 帧、P 帧、B 帧（MPEG 核心帧类型） 帧类型名称 英文全称 压缩参考原理与特性 压缩率与重要性 I 帧（关键帧） Intra-coded Picture 帧内压缩图像，不依赖任何前后帧，自身包含完整画面数据 压缩比最小（体积最大），但是解码和快速跳转定位的基准，必须首先解码 P 帧（前向预测帧） Predictive-coded Picture 参考其前面的一个 I 帧或 P 帧，仅记录与前帧的差值变化（运动补偿） 压缩比高，体积居中 B 帧（双向预测帧） Bi-directional Predictive 同时参考前面的前向帧和后面的后向帧进行双向插值预测 压缩比最高（体积最小），但解码时需要前后帧都到位才能解码 主流视频编码标准与文件封装容器格式区分 对比维度 常见类别与代表 核心说明与常考点 视频编码标准（编解码算法） MPEG-1 (VCD), MPEG-2 (DVD), MPEG-4, H.264/AVC, H.265/HEVC, AV1 定义视频像素的压缩数学算法；H.265 比 H.264 在同等画质下节约约 50% 带宽 视频封装容器格式（文件后缀） MP4 (.mp4), AVI (.avi), MKV (.mkv), MOV (.mov), FLV (.flv) 外壳包装盒：将视频轨、音频轨、字幕轨及元数据打包封装进同一个文件中', '{"pdf": "理论复习.pdf", "pages": [81, 82]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.4.5 计算机合成数字视频。 (node_id=136)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (136, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (136, 1, '[{"id": "a4-4-4-5-b1", "t": "table", "imp": "core", "title": "二维动画 vs 三维计算机动画制作流程对比", "headers": ["动画类型", "核心技术原理", "经典制作步骤流程", "代表软件工具"], "rows": [["==二维动画（2D Animation）==", "在平面坐标系中基于关键帧（Keyframe）与补间动画自动过渡", "原画设计 -> 绘制关键帧 -> 计算机自动生成中间帧 -> 上色合成", "Adobe Animate (Flash), Toon Boom Harmony"], ["==三维动画（3D Animation）==", "在虚拟三维三维空间中构建模型多边形网格并赋予材质光影渲染", "==三维建模（Modeling） -> 骨骼绑定（Rigging） -> 动作动画设计 -> 材质贴图灯光 -> 渲染输出（Rendering）==", "==Autodesk Maya, 3ds Max, Blender, Cinema 4D=="]]}, {"id": "a4-4-4-5-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "渲染（Rendering）的概念", "text": "==渲染==是三维动画制作的最后一道关键工序，指计算机根据设定的三维场景模型、材质着色器、全局光照与摄像机参数，经由复杂光线追踪数学算法，计算生成最终连续二维图像序列的过程。"}]'::jsonb, '', 'A4-4.4.5 计算机合成数字视频。 二维动画 vs 三维计算机动画制作流程对比 动画类型 核心技术原理 经典制作步骤流程 代表软件工具 二维动画（2D Animation） 在平面坐标系中基于关键帧（Keyframe）与补间动画自动过渡 原画设计 -> 绘制关键帧 -> 计算机自动生成中间帧 -> 上色合成 Adobe Animate (Flash), Toon Boom Harmony 三维动画（3D Animation） 在虚拟三维三维空间中构建模型多边形网格并赋予材质光影渲染 三维建模（Modeling） -> 骨骼绑定（Rigging） -> 动作动画设计 -> 材质贴图灯光 -> 渲染输出（Rendering） Autodesk Maya, 3ds Max, Blender, Cinema 4D 渲染（Rendering）的概念 渲染是三维动画制作的最后一道关键工序，指计算机根据设定的三维场景模型、材质着色器、全局光照与摄像机参数，经由复杂光线追踪数学算法，计算生成最终连续二维图像序列的过程。', '{"pdf": "理论复习.pdf", "pages": [82, 83]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- A4-4.4.6 流媒体。 (node_id=137)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (137, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (137, 1, '[{"id": "a4-4-4-6-b1", "t": "p", "imp": "core", "title": "流媒体的核心概念与技术优势", "text": "==流媒体（Streaming Media）==是指采用流式传输技术在网络上连续传输音频、视频等多媒体文件的技术。其核心突破在于：==无需等待整个几十 GB 的媒体文件全部下载完毕，只需将开始部分数据缓存在本地内存几秒钟即可实现“边下载、边解压、边播放”==，极大缩短启动等待时间，大幅降低客户端存储空间占用。"}, {"id": "a4-4-4-6-b2", "t": "table", "imp": "core", "title": "主流流媒体传输协议体系对比", "headers": ["流媒体协议", "英文全称", "传输层底层", "特点与主要应用场景"], "rows": [["==RTSP==", "实时流传输协议（Real-Time Streaming Protocol）", "TCP / UDP", "用于流媒体客户端与服务器之间的控制交互（充当网络流媒体“遥控器”：播放、暂停、快进快退）"], ["==RTP / RTCP==", "实时传输协议 / 控制协议", "==UDP（低时延）==", "RTP 负责实时打包传输音视频数据包；RTCP 负责 QoS 服务质量监控与反馈"], ["==RTMP==", "实时消息传输协议（Adobe 开发）", "TCP", "延迟极低（1~3秒），曾广泛用于国内各大直播平台推流"], ["==HLS==", "HTTP Live Streaming（苹果主导）", "==HTTP / TCP==", "基于标准 HTTP 协议将视频切成若干小切片（`.ts` 切片 + `.m3u8` 索引清单），==天然穿透各种防火墙，全平台移动端兼容最好=="]]}]'::jsonb, '', 'A4-4.4.6 流媒体。 流媒体的核心概念与技术优势 流媒体（Streaming Media）是指采用流式传输技术在网络上连续传输音频、视频等多媒体文件的技术。其核心突破在于：无需等待整个几十 GB 的媒体文件全部下载完毕，只需将开始部分数据缓存在本地内存几秒钟即可实现“边下载、边解压、边播放”，极大缩短启动等待时间，大幅降低客户端存储空间占用。 主流流媒体传输协议体系对比 流媒体协议 英文全称 传输层底层 特点与主要应用场景 RTSP 实时流传输协议（Real-Time Streaming Protocol） TCP / UDP 用于流媒体客户端与服务器之间的控制交互（充当网络流媒体“遥控器”：播放、暂停、快进快退） RTP / RTCP 实时传输协议 / 控制协议 UDP（低时延） RTP 负责实时打包传输音视频数据包；RTCP 负责 QoS 服务质量监控与反馈 RTMP 实时消息传输协议（Adobe 开发） TCP 延迟极低（1~3秒），曾广泛用于国内各大直播平台推流 HLS HTTP Live Streaming（苹果主导） HTTP / TCP 基于标准 HTTP 协议将视频切成若干小切片（.ts 切片 + .m3u8 索引清单），天然穿透各种防火墙，全平台移动端兼容最好', '{"pdf": "理论复习.pdf", "pages": [83]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.1.1 信息特性及定义，数据、信息、知识，信息处理系统。 (node_id=139)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (139, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (139, 1, '[{"id": "b1-1-1-1-b1", "t": "table", "imp": "core", "title": "信息科学奠基人对信息的经典定义", "headers": ["科学家/奠基人", "学术领域", "核心定义论断", "专转本必考点"], "rows": [["==克劳德·香农（Claude Shannon）==", "信息论之父", "==信息是用来消除不确定性的东西==", "信息量的单位为比特（bit），通过概率测度消除不确定性"], ["==诺伯特·维纳（Norbert Wiener）==", "控制论创始人", "==信息就是信息，既不是物质，也不是能量==", "与物质、能量并列为构成客观世界的三大要素"]]}, {"id": "b1-1-1-1-b2", "t": "table", "imp": "core", "title": "数据、信息与知识的递进层次关系（DIKW 体系）", "headers": ["层级要素", "概念定义", "本质区别与实例说明"], "rows": [["==数据（Data）==", "记录客观事物的原始符号表示（未经加工解释的原始事实）", "如孤立的一组数字：`38.5`、`39.2`、`36.8`"], ["==信息（Information）==", "经过加工处理后、具有特定上下文和意义的数据", "赋予语义：某患者近三天的体温数据，呈现连续发烧趋势"], ["==知识（Knowledge）==", "人类对信息进行归纳总结、验证升华后形成的规律与认知", "由体温与化验指标结合，得出“细菌性感染导致持续高热”的诊断规律"]]}, {"id": "b1-1-1-1-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "信息的基本特征", "text": "专转本常考信息的几大特性：==普遍性、客观性、传递性、共享性（共享不会造成自身损失）、时效性（过期贬值）、依附性（必须载体依附，不存在无载体的信息）、可伪性与价值性=="}]'::jsonb, '', 'B1-1.1.1 信息特性及定义，数据、信息、知识，信息处理系统。 信息科学奠基人对信息的经典定义 科学家/奠基人 学术领域 核心定义论断 专转本必考点 克劳德·香农（Claude Shannon） 信息论之父 信息是用来消除不确定性的东西 信息量的单位为比特（bit），通过概率测度消除不确定性 诺伯特·维纳（Norbert Wiener） 控制论创始人 信息就是信息，既不是物质，也不是能量 与物质、能量并列为构成客观世界的三大要素 数据、信息与知识的递进层次关系（DIKW 体系） 层级要素 概念定义 本质区别与实例说明 数据（Data） 记录客观事物的原始符号表示（未经加工解释的原始事实） 如孤立的一组数字：38.5、39.2、36.8 信息（Information） 经过加工处理后、具有特定上下文和意义的数据 赋予语义：某患者近三天的体温数据，呈现连续发烧趋势 知识（Knowledge） 人类对信息进行归纳总结、验证升华后形成的规律与认知 由体温与化验指标结合，得出“细菌性感染导致持续高热”的诊断规律 信息的基本特征 专转本常考信息的几大特性：普遍性、客观性、传递性、共享性（共享不会造成自身损失）、时效性（过期贬值）、依附性（必须载体依附，不存在无载体的信息）、可伪性与价值性', '{"pdf": "理论复习.pdf", "pages": [85, 86]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.1.2 信息分类及信息处理，信息技术内容。 (node_id=140)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (140, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (140, 1, '[{"id": "b1-1-1-2-b1", "t": "table", "imp": "core", "title": "现代信息技术四大支柱体系", "headers": ["信息技术支柱", "对应人类器官功能", "核心实现技术与关键设备"], "rows": [["==感测与识别技术（传感技术）==", "扩展人的==感觉器官==（看、听、触）", "传感器、RFID、数字摄像头、雷达、遥感技术"], ["==通信技术（传输技术）==", "扩展人的==神经系统==（信息传递）", "光纤通信、移动蜂窝网络（5G）、卫星通信、计算机网络"], ["==计算机与智能技术（处理技术）==", "扩展人的==大脑思维器官==（记忆与推理）", "微处理器、服务器、云计算、人工智能算法模型"], ["==控制与显示技术（执行技术）==", "扩展人的==效应器官==（四肢行动执行）", "工业机械臂、数控机床、各类电子显示屏、智能执行器"]]}, {"id": "b1-1-1-2-b2", "t": "list", "imp": "important", "title": "信息处理基本生命周期流程", "items": ["信息收集与输入 -> 信息传输 -> 信息存储与检索 -> 信息加工与处理（分类、计算、统计、推理） -> 信息输出与呈现 -> 信息控制与反馈"]}]'::jsonb, '', 'B1-1.1.2 信息分类及信息处理，信息技术内容。 现代信息技术四大支柱体系 信息技术支柱 对应人类器官功能 核心实现技术与关键设备 感测与识别技术（传感技术） 扩展人的感觉器官（看、听、触） 传感器、RFID、数字摄像头、雷达、遥感技术 通信技术（传输技术） 扩展人的神经系统（信息传递） 光纤通信、移动蜂窝网络（5G）、卫星通信、计算机网络 计算机与智能技术（处理技术） 扩展人的大脑思维器官（记忆与推理） 微处理器、服务器、云计算、人工智能算法模型 控制与显示技术（执行技术） 扩展人的效应器官（四肢行动执行） 工业机械臂、数控机床、各类电子显示屏、智能执行器 信息处理基本生命周期流程 信息收集与输入 -> 信息传输 -> 信息存储与检索 -> 信息加工与处理（分类、计算、统计、推理） -> 信息输出与呈现 -> 信息控制与反馈', '{"pdf": "理论复习.pdf", "pages": [86, 87]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.2.1 通信系统基本原理，信道、信源、信宿，模拟信号，数字信号。 (node_id=142)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (142, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (142, 1, '[{"id": "b1-1-2-1-b1", "t": "table", "imp": "core", "title": "现代通信系统的基本模型五要素", "headers": ["系统组成部件", "功能定义", "典型设备或介质举例"], "rows": [["==信源（Source）==", "产生并发送原始信息的实体（源头）", "讲话的人、电话麦克风、监控摄像头、计算机客户端"], ["==发送设备（Transmitter）==", "将信源输出的原始基带信号转换为适合在信道中传输的信号", "调制器（Modulator）、编码器、无线发射机"], ["==信道（Channel）==", "传输信号的物理通道或传输介质", "双绞线、同轴电缆、光纤、自由空间无线电波"], ["==接收设备（Receiver）==", "从信道接收信号并进行放大、解调、解码，还原为原始信号", "解调器（Demodulator）、解码器、无线接收机"], ["==信宿（Sink）==", "接收并理解信息的最终实体（目的地）", "听话的人、电话扬声器、监视器屏幕、接收端服务器"]]}, {"id": "b1-1-2-1-b2", "t": "table", "imp": "core", "title": "模拟信号 vs 数字信号核心对比", "headers": ["对比项", "模拟信号（Analog Signal）", "数字信号（Digital Signal）"], "rows": [["==参数取值特点==", "幅度随时间取值==连续变化（无限个可能状态）==", "幅度随时间取值==离散分布（如有限个电平状态 0 和 1）=="], ["==抗干扰与防噪声==", "抗噪声能力弱，长途传输噪声会被逐级放大累积", "==抗干扰能力极强，便于再生中继和纠错编码=="], ["==保密性与加密==", "保密性差，容易被监听窃听", "数字比特流便于利用密码学算法进行高级加密"], ["信号转换设备", "模拟转数字：==A/D 转换器（采样、量化、编码）==", "数字转模拟：==D/A 转换器（调制解调）=="]]}]'::jsonb, '', 'B1-1.2.1 通信系统基本原理，信道、信源、信宿，模拟信号，数字信号。 现代通信系统的基本模型五要素 系统组成部件 功能定义 典型设备或介质举例 信源（Source） 产生并发送原始信息的实体（源头） 讲话的人、电话麦克风、监控摄像头、计算机客户端 发送设备（Transmitter） 将信源输出的原始基带信号转换为适合在信道中传输的信号 调制器（Modulator）、编码器、无线发射机 信道（Channel） 传输信号的物理通道或传输介质 双绞线、同轴电缆、光纤、自由空间无线电波 接收设备（Receiver） 从信道接收信号并进行放大、解调、解码，还原为原始信号 解调器（Demodulator）、解码器、无线接收机 信宿（Sink） 接收并理解信息的最终实体（目的地） 听话的人、电话扬声器、监视器屏幕、接收端服务器 模拟信号 vs 数字信号核心对比 对比项 模拟信号（Analog Signal） 数字信号（Digital Signal） 参数取值特点 幅度随时间取值连续变化（无限个可能状态） 幅度随时间取值离散分布（如有限个电平状态 0 和 1） 抗干扰与防噪声 抗噪声能力弱，长途传输噪声会被逐级放大累积 抗干扰能力极强，便于再生中继和纠错编码 保密性与加密 保密性差，容易被监听窃听 数字比特流便于利用密码学算法进行高级加密 信号转换设备 模拟转数字：A/D 转换器（采样、量化、编码） 数字转模拟：D/A 转换器（调制解调）', '{"pdf": "理论复习.pdf", "pages": [87, 88]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.2.2 信道的传输模式，信道的带宽，信道的传输速率，多路复用技术，交换技术。 (node_id=143)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (143, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (143, 1, '[{"id": "b1-1-2-2-b1", "t": "table", "imp": "core", "title": "信道通信的三大传输模式（专转本高频必考）", "headers": ["传输模式", "通信方向定义", "信道数量要求", "生活典型实例"], "rows": [["==单工通信（Simplex）==", "信号只能单向传输，任何时候都不能反向传送", "1 条单向通道", "==广播电台、无线电视、寻呼机、遥控器=="], ["==半双工通信（Half-duplex）==", "双方都可以发送和接收信息，但==不能同时进行，同一时间只能一方发一方收==", "通常 1 条双向复用物理信道", "==传统对讲机（按键说话）、对讲电话=="], ["==全双工通信（Full-duplex）==", "通信双方==可以同时发送和同时接收信息==", "需要 2 条物理信道（或频分/时分双向拆分）", "==普通电话通话、手机语音、宽带互联网通信=="]]}, {"id": "b1-1-2-2-b2", "t": "table", "imp": "core", "title": "四大主流多路复用技术（Multiplexing）对比", "headers": ["复用技术名称", "英文缩写", "工作划分原理", "典型应用领域"], "rows": [["==频分多路复用==", "==FDM==", "将信道总频带分割为多个不重叠的子频带，各传输一路信号", "有线电视、传统模拟电话载波通信"], ["==时分多路复用==", "==TDM==", "将传输时间划分为互不重叠的时间间隙（时隙），轮流分配给各路信号", "数字电话通信系统、PCM 脉冲编码调制基带网络"], ["==波分多路复用==", "==WDM==", "在一根光纤中同时传输多个不同波长的光载波信号（本质为光领域的 FDM）", "==单根光纤超大容量长途骨干传输=="], ["==码分多路复用==", "==CDM / CDMA==", "各路信号使用相互正交的不同伪随机编码序列调制同一频带", "2G/3G 移动通信、GPS 卫星定位导航"]]}, {"id": "b1-1-2-2-b3", "t": "table", "imp": "core", "title": "三大数据交换技术（Switching）对比", "headers": ["交换技术", "电路交换（Circuit Switching）", "报文交换（Message Switching）", "分组交换（Packet Switching）"], "rows": [["==通信过程==", "==必须经历“建立连接 -> 占用通话 -> 释放连接”三阶段==", "存储转发整份完整报文，无需预先建连接", "==存储转发切分成小单位的分组（Packet），无需预先独占建连=="], ["==信道占用==", "通信期间==独占物理信道==，空闲时信道利用率极低", "动态共享信道，报文大小不限导致缓冲区排队过长", "==动态复用信道，流水线式并行转发，信道利用率极高=="], ["==典型应用==", "传统电话网络（PSTN）", "早期的电报系统", "==现代计算机互联网（TCP/IP 网络）的基础=="]]}]'::jsonb, '', 'B1-1.2.2 信道的传输模式，信道的带宽，信道的传输速率，多路复用技术，交换技术。 信道通信的三大传输模式（专转本高频必考） 传输模式 通信方向定义 信道数量要求 生活典型实例 单工通信（Simplex） 信号只能单向传输，任何时候都不能反向传送 1 条单向通道 广播电台、无线电视、寻呼机、遥控器 半双工通信（Half-duplex） 双方都可以发送和接收信息，但不能同时进行，同一时间只能一方发一方收 通常 1 条双向复用物理信道 传统对讲机（按键说话）、对讲电话 全双工通信（Full-duplex） 通信双方可以同时发送和同时接收信息 需要 2 条物理信道（或频分/时分双向拆分） 普通电话通话、手机语音、宽带互联网通信 四大主流多路复用技术（Multiplexing）对比 复用技术名称 英文缩写 工作划分原理 典型应用领域 频分多路复用 FDM 将信道总频带分割为多个不重叠的子频带，各传输一路信号 有线电视、传统模拟电话载波通信 时分多路复用 TDM 将传输时间划分为互不重叠的时间间隙（时隙），轮流分配给各路信号 数字电话通信系统、PCM 脉冲编码调制基带网络 波分多路复用 WDM 在一根光纤中同时传输多个不同波长的光载波信号（本质为光领域的 FDM） 单根光纤超大容量长途骨干传输 码分多路复用 CDM / CDMA 各路信号使用相互正交的不同伪随机编码序列调制同一频带 2G/3G 移动通信、GPS 卫星定位导航 三大数据交换技术（Switching）对比 交换技术 电路交换（Circuit Switching） 报文交换（Message Switching） 分组交换（Packet Switching） 通信过程 必须经历“建立连接 -> 占用通话 -> 释放连接”三阶段 存储转发整份完整报文，无需预先建连接 存储转发切分成小单位的分组（Packet），无需预先独占建连 信道占用 通信期间独占物理信道，空闲时信道利用率极低 动态共享信道，报文大小不限导致缓冲区排队过长 动态复用信道，流水线式并行转发，信道利用率极高 典型应用 传统电话网络（PSTN） 早期的电报系统 现代计算机互联网（TCP/IP 网络）的基础', '{"pdf": "理论复习.pdf", "pages": [88, 89, 90]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.2.3 有线传输，无线传输，有线载波通信，传输介质，光纤通信。 (node_id=144)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (144, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (144, 1, '[{"id": "b1-1-2-3-b1", "t": "table", "imp": "core", "title": "常见有线传输介质特性对比（双绞线 / 同轴电缆 / 光纤）", "headers": ["传输介质", "结构原理与分类", "最大传输距离", "带宽与抗干扰性"], "rows": [["==双绞线（Twisted Pair）==", "两根绝缘铜导线按一定密度绞合（抵消电磁干扰）；分为==非屏蔽（UTP）与屏蔽（STP）==", "以太网最大传输距离 ==100 米==", "成本最低，广泛用于局域网楼层布线"], ["同轴电缆（Coaxial Cable）", "内导体铜芯、绝缘层、外导体网状编织屏蔽层、护套；分为粗缆与细缆", "数百米", "抗干扰优于双绞线，常用于有线电视及闭路监控"], ["==光纤（Optical Fiber）==", "利用==光的全反射原理==在石英玻璃纤芯中传输光脉冲", "==数公里至上百公里==", "==带宽高、衰减极小、抗电磁干扰极强、重量轻、保密性极高=="]]}, {"id": "b1-1-2-3-b2", "t": "table", "imp": "core", "title": "单模光纤（SMF） vs 多模光纤（MMF）专转本必考点", "headers": ["对比项", "单模光纤（Single Mode Fiber）", "多模光纤（Multi Mode Fiber）"], "rows": [["==纤芯直径==", "==很细（通常为 8~10 微米）==", "==较粗（通常为 50 或 62.5 微米）=="], ["==光传输模式==", "只允许单一路径的光线沿轴线直线传播，==无模间色散==", "允许多条不同入射角的光线沿多种模式全反射传播，==存在模间色散=="], ["==光源类型==", "采用高成本的==半导体激光器（LD）==", "采用低成本的发光二极管（LED）"], ["==传输距离与应用==", "==传输距离远（几十至上百公里），用于城域网和骨干网==", "传输距离短（通常在 2 公里以内），用于园区和建筑物内部短距互联"], ["外护套国际规范颜色", "通常为==黄色（Yellow）==", "通常为==橙色（Orange）或浅天蓝色（Aqua）=="]]}]'::jsonb, '', 'B1-1.2.3 有线传输，无线传输，有线载波通信，传输介质，光纤通信。 常见有线传输介质特性对比（双绞线 / 同轴电缆 / 光纤） 传输介质 结构原理与分类 最大传输距离 带宽与抗干扰性 双绞线（Twisted Pair） 两根绝缘铜导线按一定密度绞合（抵消电磁干扰）；分为非屏蔽（UTP）与屏蔽（STP） 以太网最大传输距离 100 米 成本最低，广泛用于局域网楼层布线 同轴电缆（Coaxial Cable） 内导体铜芯、绝缘层、外导体网状编织屏蔽层、护套；分为粗缆与细缆 数百米 抗干扰优于双绞线，常用于有线电视及闭路监控 光纤（Optical Fiber） 利用光的全反射原理在石英玻璃纤芯中传输光脉冲 数公里至上百公里 带宽高、衰减极小、抗电磁干扰极强、重量轻、保密性极高 单模光纤（SMF） vs 多模光纤（MMF）专转本必考点 对比项 单模光纤（Single Mode Fiber） 多模光纤（Multi Mode Fiber） 纤芯直径 很细（通常为 8~10 微米） 较粗（通常为 50 或 62.5 微米） 光传输模式 只允许单一路径的光线沿轴线直线传播，无模间色散 允许多条不同入射角的光线沿多种模式全反射传播，存在模间色散 光源类型 采用高成本的半导体激光器（LD） 采用低成本的发光二极管（LED） 传输距离与应用 传输距离远（几十至上百公里），用于城域网和骨干网 传输距离短（通常在 2 公里以内），用于园区和建筑物内部短距互联 外护套国际规范颜色 通常为黄色（Yellow） 通常为橙色（Orange）或浅天蓝色（Aqua）', '{"pdf": "理论复习.pdf", "pages": [90, 91]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.2.4 无线电通信，微波通信，卫星通信，红外线通信，移动通信。 (node_id=145)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (145, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (145, 1, '[{"id": "b1-1-2-4-b1", "t": "table", "imp": "core", "title": "常见无线通信技术特点梳理", "headers": ["无线技术类别", "频率/波长特点", "传播方式与特点", "典型应用"], "rows": [["==微波通信（Microwave）==", "频率 300MHz ~ 300GHz（极高频）", "==直线视距传播（Line-of-Sight）==，受地球曲率限制，每隔 50 公里需建微波中继站", "微波中继通信、雷达探测、家用微波炉"], ["==卫星通信==", "利用人造地球同步卫星充当微波中继站", "==覆盖范围极广（仅需 3 颗地球同步同步静止卫星即可覆盖除两极外的全球通信）==，但存在约 270ms 传输时延", "远洋轮船、跨洋越顶电视转播、野外地质科考应急通信"], ["==红外线通信（Infrared）==", "波长介于微波与可见光之间", "==具有方向性、不能穿透墙壁障碍物==，传输距离通常在数米内", "电视空调遥控器、早期手机红外传输"], ["==蜂窝移动通信==", "采用正六边形蜂窝小区制，频率复用", "基站与移动台双向无线连接，支持跨区自动越区切换（Handover）", "2G/3G/4G/5G 手机公众移动通信"]]}, {"id": "b1-1-2-4-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "卫星通信核心参数考点", "text": "专转本常考单选题：地球同步轨道卫星位于赤道上方约 ==36000 公里==；理论上只需 ==3 颗互成 120 度的地球同步卫星==即可实现除南北极盲区外的全球无死角覆盖。"}]'::jsonb, '', 'B1-1.2.4 无线电通信，微波通信，卫星通信，红外线通信，移动通信。 常见无线通信技术特点梳理 无线技术类别 频率/波长特点 传播方式与特点 典型应用 微波通信（Microwave） 频率 300MHz ~ 300GHz（极高频） 直线视距传播（Line-of-Sight），受地球曲率限制，每隔 50 公里需建微波中继站 微波中继通信、雷达探测、家用微波炉 卫星通信 利用人造地球同步卫星充当微波中继站 覆盖范围极广（仅需 3 颗地球同步同步静止卫星即可覆盖除两极外的全球通信），但存在约 270ms 传输时延 远洋轮船、跨洋越顶电视转播、野外地质科考应急通信 红外线通信（Infrared） 波长介于微波与可见光之间 具有方向性、不能穿透墙壁障碍物，传输距离通常在数米内 电视空调遥控器、早期手机红外传输 蜂窝移动通信 采用正六边形蜂窝小区制，频率复用 基站与移动台双向无线连接，支持跨区自动越区切换（Handover） 2G/3G/4G/5G 手机公众移动通信 卫星通信核心参数考点 专转本常考单选题：地球同步轨道卫星位于赤道上方约 36000 公里；理论上只需 3 颗互成 120 度的地球同步卫星即可实现除南北极盲区外的全球无死角覆盖。', '{"pdf": "理论复习.pdf", "pages": [91, 92, 93]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.3.1 计算机信息系统的含义及特点。 (node_id=147)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (147, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (147, 1, '[{"id": "b1-1-3-1-b1", "t": "p", "imp": "core", "title": "计算机信息系统的定义", "text": "==计算机信息系统（Computer Information System，简称 CIS）==是以计算机技术、网络通信技术为基础，以数据库为核心，对信息进行收集、存储、加工、检索、传输和呈现的人机交互综合系统。其终极目标是为组织运营决策提供数据支持和管理效率赋能。"}, {"id": "b1-1-3-1-b2", "t": "list", "imp": "core", "title": "计算机信息系统的五大本质特征", "items": ["==人机和谐系统（Man-Machine System）==：系统由人、计算机硬件、软件、数据和规章制度共同组成，==“人”是系统的主导者和核心要素==", "==以数据库为核心==：采用关系数据库集中或分布式存储海量业务数据，实现数据统一维护、共享与减少冗余", "综合性与多学科交叉：涉及计算机科学、管理学、运筹学、系统工程等多门学科", "网络化与分布式：依赖计算机网络实现不同部门和跨地域的数据互联互通", "动态适应性：伴随组织业务流程再造（BPR）与外部市场环境变化持续演进迭代"]}]'::jsonb, '', 'B1-1.3.1 计算机信息系统的含义及特点。 计算机信息系统的定义 计算机信息系统（Computer Information System，简称 CIS）是以计算机技术、网络通信技术为基础，以数据库为核心，对信息进行收集、存储、加工、检索、传输和呈现的人机交互综合系统。其终极目标是为组织运营决策提供数据支持和管理效率赋能。 计算机信息系统的五大本质特征 人机和谐系统（Man-Machine System）：系统由人、计算机硬件、软件、数据和规章制度共同组成，“人”是系统的主导者和核心要素 以数据库为核心：采用关系数据库集中或分布式存储海量业务数据，实现数据统一维护、共享与减少冗余 综合性与多学科交叉：涉及计算机科学、管理学、运筹学、系统工程等多门学科 网络化与分布式：依赖计算机网络实现不同部门和跨地域的数据互联互通 动态适应性：伴随组织业务流程再造（BPR）与外部市场环境变化持续演进迭代', '{"pdf": "理论复习.pdf", "pages": [94]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.3.2 计算机信息系统的类型。 (node_id=148)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (148, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (148, 1, '[{"id": "b1-1-3-2-b1", "t": "table", "imp": "core", "title": "常见计算机信息系统类型及层级（自底向上）", "headers": ["系统类型名称", "英文缩写", "服务的组织层级", "核心处理任务与功能定位"], "rows": [["==业务处理系统（事务处理系统）==", "==TPS / EDPS==", "组织底层操作人员（基层）", "日常大批量、重复性事务流水记录（如银行柜员存取款、超市 POS 结账扫码）"], ["==管理信息系统==", "==MIS==", "部门主管/中层管理者", "汇集基层日常事务数据，生成定期结构化汇总报表，进行运营监控与控制"], ["==决策支持系统==", "==DSS==", "中高层决策人员", "利用数学模型、运筹学算法和人机交互，辅助解决半结构化与非结构化决策问题"], ["==主管信息系统（行政全面系统）==", "==EIS / ESS==", "最高层领导决策者（CEO/总经理）", "汇总组织全局宏观指标大屏看板，提供高度凝练的图表化战略概览与预警"], ["办公自动化系统", "OAS", "全员/办公文秘人员", "公文流转、日程管理、协同办公审批"]]}, {"id": "b1-1-3-2-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "MIS 与 DSS 的核心区别", "text": "专转本常考单选题辨析：==MIS 主要面向结构化问题（依靠确定规则和报表）==；而==DSS 主要面向半结构化或非结构化问题（依靠人机交互与模型辅助模拟推演）==。"}]'::jsonb, '', 'B1-1.3.2 计算机信息系统的类型。 常见计算机信息系统类型及层级（自底向上） 系统类型名称 英文缩写 服务的组织层级 核心处理任务与功能定位 业务处理系统（事务处理系统） TPS / EDPS 组织底层操作人员（基层） 日常大批量、重复性事务流水记录（如银行柜员存取款、超市 POS 结账扫码） 管理信息系统 MIS 部门主管/中层管理者 汇集基层日常事务数据，生成定期结构化汇总报表，进行运营监控与控制 决策支持系统 DSS 中高层决策人员 利用数学模型、运筹学算法和人机交互，辅助解决半结构化与非结构化决策问题 主管信息系统（行政全面系统） EIS / ESS 最高层领导决策者（CEO/总经理） 汇总组织全局宏观指标大屏看板，提供高度凝练的图表化战略概览与预警 办公自动化系统 OAS 全员/办公文秘人员 公文流转、日程管理、协同办公审批 MIS 与 DSS 的核心区别 专转本常考单选题辨析：MIS 主要面向结构化问题（依靠确定规则和报表）；而DSS 主要面向半结构化或非结构化问题（依靠人机交互与模型辅助模拟推演）。', '{"pdf": "理论复习.pdf", "pages": [94, 95]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.3.3 计算机信息系统的结构。 (node_id=149)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (149, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (149, 1, '[{"id": "b1-1-3-3-b1", "t": "table", "imp": "core", "title": "信息系统的两大结构视角（功能结构 vs 软件架构）", "headers": ["结构视角", "划分维度", "具体内容构成"], "rows": [["==横向功能划分（业务职能）==", "按企业业务流程职能", "财务管理子系统、生产制造子系统、销售与市场子系统、人力资源子系统、物资采购子系统"], ["==纵向层级划分（管理层次）==", "按组织行政权利层级", "战略决策层（高层） -> 战术管理控制层（中层） -> 操作业务运行层（基层）"], ["==软件体系架构==", "按计算部署拓扑", "集中式主机架构、==客户机/服务器（C/S 架构）==、==浏览器/服务器（B/S 架构）==、微服务分布式架构"]]}, {"id": "b1-1-3-3-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "C/S 架构 vs B/S 架构", "text": "C/S 架构客户端需安装专用客户端软件，交互性能好但升级维护困难；==B/S 架构客户端只需标准 Web 浏览器，零客户端安装，极利于跨平台访问与集中维护更新==。"}]'::jsonb, '', 'B1-1.3.3 计算机信息系统的结构。 信息系统的两大结构视角（功能结构 vs 软件架构） 结构视角 划分维度 具体内容构成 横向功能划分（业务职能） 按企业业务流程职能 财务管理子系统、生产制造子系统、销售与市场子系统、人力资源子系统、物资采购子系统 纵向层级划分（管理层次） 按组织行政权利层级 战略决策层（高层） -> 战术管理控制层（中层） -> 操作业务运行层（基层） 软件体系架构 按计算部署拓扑 集中式主机架构、客户机/服务器（C/S 架构）、浏览器/服务器（B/S 架构）、微服务分布式架构 C/S 架构 vs B/S 架构 C/S 架构客户端需安装专用客户端软件，交互性能好但升级维护困难；B/S 架构客户端只需标准 Web 浏览器，零客户端安装，极利于跨平台访问与集中维护更新。', '{"pdf": "理论复习.pdf", "pages": [95]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.3.4 计算机信息系统的发展趋势。 (node_id=150)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (150, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (150, 1, '[{"id": "b1-1-3-4-b1", "t": "list", "imp": "core", "title": "信息系统前沿演进趋势", "items": ["==云原生与微服务化（SaaS 化）==：单体大型架构拆解为松耦合微服务，利用容器技术实现弹性部署与高容灾", "==移动化与泛在接入（Mobile First）==：支持手机移动端随身审批与协同办公，业务流程全链路无缝线上化", "==智能化（AI-driven）与数据驱动==：引入机器学习、大模型助手实现流程智能自动化（RPA）与预测性智能决策", "生态协同与开放 API 共享：打破企业间信息孤岛，通过供应链与金融 API 实现跨行业生态数据互联"]}, {"id": "b1-1-3-4-b2", "t": "callout", "imp": "normal", "kind": "tip", "title": "信息孤岛的破除", "text": "企业信息系统建设的重要目标之一就是==消除部门之间的“信息孤岛”（Data Silos）==，实现全局数据资产的流通共享与单点登录（SSO）。"}]'::jsonb, '', 'B1-1.3.4 计算机信息系统的发展趋势。 信息系统前沿演进趋势 云原生与微服务化（SaaS 化）：单体大型架构拆解为松耦合微服务，利用容器技术实现弹性部署与高容灾 移动化与泛在接入（Mobile First）：支持手机移动端随身审批与协同办公，业务流程全链路无缝线上化 智能化（AI-driven）与数据驱动：引入机器学习、大模型助手实现流程智能自动化（RPA）与预测性智能决策 生态协同与开放 API 共享：打破企业间信息孤岛，通过供应链与金融 API 实现跨行业生态数据互联 信息孤岛的破除 企业信息系统建设的重要目标之一就是消除部门之间的“信息孤岛”（Data Silos），实现全局数据资产的流通共享与单点登录（SSO）。', '{"pdf": "理论复习.pdf", "pages": [95, 96]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.4.1 制造业信息系统。 (node_id=152)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (152, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (152, 1, '[{"id": "b1-1-4-1-b1", "t": "table", "imp": "core", "title": "现代制造业核心信息系统简称与功能（专转本高频必考）", "headers": ["系统英文缩写", "系统中文全称", "核心功能与管控范围"], "rows": [["==CAD==", "计算机辅助设计", "工程图纸绘制、机械零件三维建模与仿真设计"], ["==CAM==", "计算机辅助制造", "利用计算机控制机床、数控设备直接加工零件成品"], ["==CIMS==", "计算机集成制造系统", "将设计、制造、经营管理全流程通过网络统一集成"], ["==ERP==", "==企业资源计划==", "整合企业人、财、物、产、供、销全方位资源的骨干管理软件"], ["==MES==", "制造执行系统", "负责车间现场工序调度、设备作业实时监控与工单追踪"], ["==PLM / PDM==", "产品生命周期管理 / 产品数据管理", "管理从产品概念构想、设计图纸到报废的全生命周期数据"]]}, {"id": "b1-1-4-1-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "ERP 演进三部曲", "text": "专转本高频考点：==MRP（物料需求计划） -> 闭环 MRP -> MRP II（制造资源计划） -> ERP（企业资源计划）==。ERP 实现了对企业内部以及供应链外部资源的全面一体化整合。"}]'::jsonb, '', 'B1-1.4.1 制造业信息系统。 现代制造业核心信息系统简称与功能（专转本高频必考） 系统英文缩写 系统中文全称 核心功能与管控范围 CAD 计算机辅助设计 工程图纸绘制、机械零件三维建模与仿真设计 CAM 计算机辅助制造 利用计算机控制机床、数控设备直接加工零件成品 CIMS 计算机集成制造系统 将设计、制造、经营管理全流程通过网络统一集成 ERP 企业资源计划 整合企业人、财、物、产、供、销全方位资源的骨干管理软件 MES 制造执行系统 负责车间现场工序调度、设备作业实时监控与工单追踪 PLM / PDM 产品生命周期管理 / 产品数据管理 管理从产品概念构想、设计图纸到报废的全生命周期数据 ERP 演进三部曲 专转本高频考点：MRP（物料需求计划） -> 闭环 MRP -> MRP II（制造资源计划） -> ERP（企业资源计划）。ERP 实现了对企业内部以及供应链外部资源的全面一体化整合。', '{"pdf": "理论复习.pdf", "pages": [96]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

