INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (153, 1, '[{"id": "b1-1-4-2-b1", "t": "table", "imp": "core", "title": "电子商务核心业务模式分类（按交易主体划分）", "headers": ["模式标识", "英文全称", "交易双方角色", "代表平台与典型案例"], "rows": [["==B2B==", "Business to Business", "==企业对企业==", "阿里巴巴 1688 批发网、慧聪网、大宗商品交易平台"], ["==B2C==", "Business to Consumer", "==企业对个人消费者==", "天猫官方旗舰店、京东自营商城、苏宁易购"], ["==C2C==", "Consumer to Consumer", "==个人消费者对个人消费者==", "淘宝个人网店、闲鱼二手交易平台、拍拍网"], ["==O2O==", "Online to Offline", "==线上到线下==", "美团外卖、大众点评线上团购到店消费、滴滴出行"], ["B2G / G2B", "Business to Government", "企业与政府之间", "政府采购网电子招标投系统"]]}, {"id": "b1-1-4-2-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "电子支付与安全标准", "text": "电子商务的核心安全保障技术：==SSL/TLS 传输层加密协议==与==SET（安全电子交易协议）==；第三方支付机构（如支付宝、微信支付）起到资金担保与信用中介作用。"}]'::jsonb, '', 'B1-1.4.2 电子商务。 电子商务核心业务模式分类（按交易主体划分） 模式标识 英文全称 交易双方角色 代表平台与典型案例 B2B Business to Business 企业对企业 阿里巴巴 1688 批发网、慧聪网、大宗商品交易平台 B2C Business to Consumer 企业对个人消费者 天猫官方旗舰店、京东自营商城、苏宁易购 C2C Consumer to Consumer 个人消费者对个人消费者 淘宝个人网店、闲鱼二手交易平台、拍拍网 O2O Online to Offline 线上到线下 美团外卖、大众点评线上团购到店消费、滴滴出行 B2G / G2B Business to Government 企业与政府之间 政府采购网电子招标投系统 电子支付与安全标准 电子商务的核心安全保障技术：SSL/TLS 传输层加密协议与SET（安全电子交易协议）；第三方支付机构（如支付宝、微信支付）起到资金担保与信用中介作用。', '{"pdf": "理论复习.pdf", "pages": [96, 97]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.4.3 电子政务。 (node_id=154)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (154, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (154, 1, '[{"id": "b1-1-4-3-b1", "t": "table", "imp": "core", "title": "电子政务（E-Government）四大主要模式", "headers": ["模式缩写", "对应交互主体", "主要应用场景与功能"], "rows": [["==G2G==", "政府与政府之间（内部各部门）", "政务内网公文无纸化流转、各部门跨系统数据协同互认、国家电子监察"], ["==G2B==", "政府与企业之间", "电子化税务申报、企业在线工商年检、工程在线审批备案"], ["==G2C==", "政府对公民/公众", "网上身份证/社保查询申报、户籍在线预约办理、市长热线网络信箱"], ["==G2E==", "政府与公务员员工之间", "公务员人事档案管理、在线培训与绩效考核测评"]]}, {"id": "b1-1-4-3-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "一网通办与数据共享", "text": "推进电子政务的核心目标是==“让数据多跑路，让群众少跑腿”==，通过建设全国一体化政务服务平台，破除“奇葩证明”和重复提交材料。"}]'::jsonb, '', 'B1-1.4.3 电子政务。 电子政务（E-Government）四大主要模式 模式缩写 对应交互主体 主要应用场景与功能 G2G 政府与政府之间（内部各部门） 政务内网公文无纸化流转、各部门跨系统数据协同互认、国家电子监察 G2B 政府与企业之间 电子化税务申报、企业在线工商年检、工程在线审批备案 G2C 政府对公民/公众 网上身份证/社保查询申报、户籍在线预约办理、市长热线网络信箱 G2E 政府与公务员员工之间 公务员人事档案管理、在线培训与绩效考核测评 一网通办与数据共享 推进电子政务的核心目标是“让数据多跑路，让群众少跑腿”，通过建设全国一体化政务服务平台，破除“奇葩证明”和重复提交材料。', '{"pdf": "理论复习.pdf", "pages": [97]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.4.4 地理信息系统和数字地球。 (node_id=155)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (155, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (155, 1, '[{"id": "b1-1-4-4-b1", "t": "list", "imp": "core", "title": "地理信息系统（GIS）与“3S”技术", "items": ["==地理信息系统（GIS）==：在计算机软硬件支持下，对整个或部分地球表层空间中的有关地理分布数据进行采集、存储、管理、运算、分析、显示和描述的系统", "==“3S”集成技术体系（专转本高频考点）==：", "• ==GIS（地理信息系统）==：负责空间数据的==分析、查询与综合管理（相当于大脑分析）==", "• ==RS（遥感技术）==：负责地表宏观多光谱图像的==采集与实时监测（相当于眼睛拍照）==", "• ==GPS / 北斗（全球卫星定位导航系统）==：负责物体空间绝对位置的==精准定位与测速（相当于定位坐标）=="]}, {"id": "b1-1-4-4-b2", "t": "callout", "imp": "core", "kind": "tip", "title": "数字地球概念", "text": "==数字地球（Digital Earth）==是由美国前副总统戈尔于 1998 年提出，指把整个地球信息数字化后，由计算机网络来管理的技术系统。其最直观的商业体现即为 Google Earth、天地图等三维虚拟地球软件。"}]'::jsonb, '', 'B1-1.4.4 地理信息系统和数字地球。 地理信息系统（GIS）与“3S”技术 地理信息系统（GIS）：在计算机软硬件支持下，对整个或部分地球表层空间中的有关地理分布数据进行采集、存储、管理、运算、分析、显示和描述的系统 “3S”集成技术体系（专转本高频考点）： • GIS（地理信息系统）：负责空间数据的分析、查询与综合管理（相当于大脑分析） • RS（遥感技术）：负责地表宏观多光谱图像的采集与实时监测（相当于眼睛拍照） • GPS / 北斗（全球卫星定位导航系统）：负责物体空间绝对位置的精准定位与测速（相当于定位坐标） 数字地球概念 数字地球（Digital Earth）是由美国前副总统戈尔于 1998 年提出，指把整个地球信息数字化后，由计算机网络来管理的技术系统。其最直观的商业体现即为 Google Earth、天地图等三维虚拟地球软件。', '{"pdf": "理论复习.pdf", "pages": [97]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.4.5 远程教育。 (node_id=156)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (156, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (156, 1, '[{"id": "b1-1-4-5-b1", "t": "list", "imp": "core", "title": "现代远程教育的核心形态与优势", "items": ["==慕课（MOOC，Massive Open Online Courses）==：大规模开放在线课程，支持成千上万人同时选课、互动讨论与在线作业互评", "核心优势：==打破教育的时空限制==、促进优质教育资源均衡共享、支持学习者按照个人节奏自主终身学习", "交互模式支持：实时同步直播互动课堂（腾讯课堂/钉钉直播）与异步点播交互教学"]}, {"id": "b1-1-4-5-b2", "t": "callout", "imp": "normal", "kind": "tip", "title": "远程教育发展历程", "text": "远程教育经历了三代演进：第一代为==函授教育（纸质教材）==；第二代为==广播电视教育（卫星电大）==；第三代为==现代网络远程教育（互联网与流媒体技术）=="}]'::jsonb, '', 'B1-1.4.5 远程教育。 现代远程教育的核心形态与优势 慕课（MOOC，Massive Open Online Courses）：大规模开放在线课程，支持成千上万人同时选课、互动讨论与在线作业互评 核心优势：打破教育的时空限制、促进优质教育资源均衡共享、支持学习者按照个人节奏自主终身学习 交互模式支持：实时同步直播互动课堂（腾讯课堂/钉钉直播）与异步点播交互教学 远程教育发展历程 远程教育经历了三代演进：第一代为函授教育（纸质教材）；第二代为广播电视教育（卫星电大）；第三代为现代网络远程教育（互联网与流媒体技术）', '{"pdf": "理论复习.pdf", "pages": [97, 98]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.4.6 远程医疗。 (node_id=157)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (157, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (157, 1, '[{"id": "b1-1-4-6-b1", "t": "table", "imp": "core", "title": "远程医疗主要业务应用形态", "headers": ["远程业务形态", "技术手段", "实现效果与价值"], "rows": [["==远程专家会诊==", "超高清视频会议、高精医学图像传输", "基层医院与三甲名医面对面讨论复杂疑难病例，免去患者长途奔波"], ["==远程病理/影像诊断==", "PACS 医疗影像传输系统、DICOM 标准", "千里之外阅片出具权威 CT/核磁共振诊断报告"], ["==5G 远程手术示教/操控==", "5G uRLLC 毫秒级低时延高可靠专网、手术机器人", "顶尖外科专家远程控制机械臂为偏远基层患者实施高难度微创手术"], ["在线互联网医院", "电子处方流转、医保在线结算、顺丰送药上门", "常见病、慢病复诊轻量化全流程闭环服务"]]}, {"id": "b1-1-4-6-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "PACS 与 DICOM 标准", "text": "医院内部专门用于传输和保存放射 CT、MRI 图像的系统名为 ==PACS（影像归档和通信系统）==，全球通用的医学图像文件格式标准为 ==DICOM=="}]'::jsonb, '', 'B1-1.4.6 远程医疗。 远程医疗主要业务应用形态 远程业务形态 技术手段 实现效果与价值 远程专家会诊 超高清视频会议、高精医学图像传输 基层医院与三甲名医面对面讨论复杂疑难病例，免去患者长途奔波 远程病理/影像诊断 PACS 医疗影像传输系统、DICOM 标准 千里之外阅片出具权威 CT/核磁共振诊断报告 5G 远程手术示教/操控 5G uRLLC 毫秒级低时延高可靠专网、手术机器人 顶尖外科专家远程控制机械臂为偏远基层患者实施高难度微创手术 在线互联网医院 电子处方流转、医保在线结算、顺丰送药上门 常见病、慢病复诊轻量化全流程闭环服务 PACS 与 DICOM 标准 医院内部专门用于传输和保存放射 CT、MRI 图像的系统名为 PACS（影像归档和通信系统），全球通用的医学图像文件格式标准为 DICOM', '{"pdf": "理论复习.pdf", "pages": [98]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.4.7 数字图书馆。 (node_id=158)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (158, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (158, 1, '[{"id": "b1-1-4-7-b1", "t": "list", "imp": "core", "title": "数字图书馆的特征与关键技术", "items": ["==资源数字化==：将传统纸质图文、手稿古籍、音频、视频经过高精扫描 OCR 技术转换为数字多媒体格式持久保存", "==服务网络化与无死角检索==：通过互联网 24 小时随时随地全文检索、在线阅读借阅，打破实体图书馆开闭馆物理限制", "数字版权保护（DRM）：利用数字水印、权限加密防止电子图书被恶意盗版传播", "常用数字期刊数据库代表：==中国知网（CNKI）、万方数据、维普资讯、Web of Science=="]}, {"id": "b1-1-4-7-b2", "t": "callout", "imp": "normal", "kind": "tip", "title": "元数据（Metadata）规范", "text": "数字图书馆普遍采用 Dublin Core（都柏林核心元数据集）等国际标准，标注文献的标题、作者、主题词、出版商等属性以便精准检索。"}]'::jsonb, '', 'B1-1.4.7 数字图书馆。 数字图书馆的特征与关键技术 资源数字化：将传统纸质图文、手稿古籍、音频、视频经过高精扫描 OCR 技术转换为数字多媒体格式持久保存 服务网络化与无死角检索：通过互联网 24 小时随时随地全文检索、在线阅读借阅，打破实体图书馆开闭馆物理限制 数字版权保护（DRM）：利用数字水印、权限加密防止电子图书被恶意盗版传播 常用数字期刊数据库代表：中国知网（CNKI）、万方数据、维普资讯、Web of Science 元数据（Metadata）规范 数字图书馆普遍采用 Dublin Core（都柏林核心元数据集）等国际标准，标注文献的标题、作者、主题词、出版商等属性以便精准检索。', '{"pdf": "理论复习.pdf", "pages": [98]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.5.1 数据库系统的组成和特点。 (node_id=160)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (160, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (160, 1, '[{"id": "b1-1-5-1-b1", "t": "table", "imp": "core", "title": "数据库相关四大量级概念辨析（从 DB 到 DBS）", "headers": ["缩写", "中文全称", "概念内涵与定位"], "rows": [["==数据（Data）==", "数据", "描述事物的符号记录，是数据库中存储的基本对象"], ["==DB==", "==数据库（DataBase）==", "长期存储在计算机内、有组织的、可共享的大量数据的集合"], ["==DBMS==", "==数据库管理系统==", "位于用户与操作系统之间的系统软件，负责数据库的科学组织管理与存取控制（如 MySQL、Oracle）"], ["==DBS==", "==数据库系统==", "包含 ==数据库（DB） + 数据库管理系统（DBMS） + 应用系统 + 硬件环境 + 数据库管理员（DBA）与用户=="]]}, {"id": "b1-1-5-1-b2", "t": "table", "imp": "core", "title": "数据库系统的三级模式与两级映像（专转本绝对重点）", "headers": ["体系层次 / 映像", "名称定义", "保证的数据独立性"], "rows": [["==外模式（子模式 / 用户模式）==", "用户能够看见和使用的局部数据的逻辑结构描述", "一个数据库可以有==多个外模式=="], ["==模式（概念模式 / 逻辑模式）==", "数据库中==全体数据的逻辑结构和特征的描述==（所有用户的公共数据视图）", "一个数据库==只有一个模式=="], ["==内模式（存储模式）==", "数据在数据库内部的存储方式与物理存储结构描述", "一个数据库==只有一个内模式=="], ["==外模式 / 模式映像==", "定义外模式与全局概念模式之间的对应关系", "==保证了数据的“逻辑独立性”==（概念模式改变时外模式无需改）"], ["==模式 / 内模式映像==", "定义全局概念模式与底层内模式存储结构之间的对应关系", "==保证了数据的“物理独立性”==（存储介质调整时应用程序无需改）"]]}]'::jsonb, '', 'B1-1.5.1 数据库系统的组成和特点。 数据库相关四大量级概念辨析（从 DB 到 DBS） 缩写 中文全称 概念内涵与定位 数据（Data） 数据 描述事物的符号记录，是数据库中存储的基本对象 DB 数据库（DataBase） 长期存储在计算机内、有组织的、可共享的大量数据的集合 DBMS 数据库管理系统 位于用户与操作系统之间的系统软件，负责数据库的科学组织管理与存取控制（如 MySQL、Oracle） DBS 数据库系统 包含 数据库（DB） + 数据库管理系统（DBMS） + 应用系统 + 硬件环境 + 数据库管理员（DBA）与用户 数据库系统的三级模式与两级映像（专转本绝对重点） 体系层次 / 映像 名称定义 保证的数据独立性 外模式（子模式 / 用户模式） 用户能够看见和使用的局部数据的逻辑结构描述 一个数据库可以有多个外模式 模式（概念模式 / 逻辑模式） 数据库中全体数据的逻辑结构和特征的描述（所有用户的公共数据视图） 一个数据库只有一个模式 内模式（存储模式） 数据在数据库内部的存储方式与物理存储结构描述 一个数据库只有一个内模式 外模式 / 模式映像 定义外模式与全局概念模式之间的对应关系 保证了数据的“逻辑独立性”（概念模式改变时外模式无需改） 模式 / 内模式映像 定义全局概念模式与底层内模式存储结构之间的对应关系 保证了数据的“物理独立性”（存储介质调整时应用程序无需改）', '{"pdf": "理论复习.pdf", "pages": [98, 99]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.5.2 数据模型的基本概念及类型。 (node_id=161)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (161, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (161, 1, '[{"id": "b1-1-5-2-b1", "t": "list", "imp": "core", "title": "数据模型三要素（必须背熟）", "items": ["==1. 数据结构==：描述系统的静态特性，研究数据库对象的类型、内容、性质以及对象之间的相互联系（如二维表）", "==2. 数据操作==：描述系统的动态特性，对数据库中各种对象允许执行的操作集合（检索与更新：增、删、改、查）", "==3. 完整性约束条件==：一组完整性规则的集合，定义数据模型中数据及其联系所具有的制约和依存规则（实体/参照/用户自定义完整性）"]}, {"id": "b1-1-5-2-b2", "t": "table", "imp": "core", "title": "传统四大逻辑数据模型对比", "headers": ["数据模型类型", "底层数据结构", "记录之间联系表现形式", "代表产品举例"], "rows": [["==层次模型（Hierarchical）==", "==树状结构（有根树）==", "仅有一个无双亲的根节点，其他子节点有且仅有一个双亲", "IBM IMS 系统"], ["==网状模型（Network）==", "==有向图网状结构==", "允许一个节点有多个双亲，允许节点没有双亲", "DBTG 系统"], ["==关系模型（Relational）==", "==二维表结构（Table）==", "通过二维表中的外键字段关联表达实体联系", "==MySQL、Oracle、SQL Server、PostgreSQL=="], ["面向对象模型（OO）", "对象、类、继承与方法", "支持封装、多态与复杂嵌套对象直接持久化", "ObjectStore, Versant"]]}]'::jsonb, '', 'B1-1.5.2 数据模型的基本概念及类型。 数据模型三要素（必须背熟） 1. 数据结构：描述系统的静态特性，研究数据库对象的类型、内容、性质以及对象之间的相互联系（如二维表） 2. 数据操作：描述系统的动态特性，对数据库中各种对象允许执行的操作集合（检索与更新：增、删、改、查） 3. 完整性约束条件：一组完整性规则的集合，定义数据模型中数据及其联系所具有的制约和依存规则（实体/参照/用户自定义完整性） 传统四大逻辑数据模型对比 数据模型类型 底层数据结构 记录之间联系表现形式 代表产品举例 层次模型（Hierarchical） 树状结构（有根树） 仅有一个无双亲的根节点，其他子节点有且仅有一个双亲 IBM IMS 系统 网状模型（Network） 有向图网状结构 允许一个节点有多个双亲，允许节点没有双亲 DBTG 系统 关系模型（Relational） 二维表结构（Table） 通过二维表中的外键字段关联表达实体联系 MySQL、Oracle、SQL Server、PostgreSQL 面向对象模型（OO） 对象、类、继承与方法 支持封装、多态与复杂嵌套对象直接持久化 ObjectStore, Versant', '{"pdf": "理论复习.pdf", "pages": [99, 100]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.5.3 关系数据模型。 (node_id=162)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (162, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (162, 1, '[{"id": "b1-1-5-3-b1", "t": "table", "imp": "core", "title": "关系模型专业术语与日常表格概念对照（专转本高频选择题）", "headers": ["关系模型专业数学术语", "日常平常常用表格词汇", "数学定义与说明"], "rows": [["==关系（Relation）==", "==一张二维表（Table）==", "笛卡尔积的子集，二维表中的数据集合"], ["==元组（Tuple）==", "==表中的一行记录（Row / Record）==", "一个具体实体的完整属性值集合"], ["==属性（Attribute）==", "==表中的一列字段（Column / Field）==", "实体所具有的某一特征，表中每一列有名字"], ["==域（Domain）==", "属性的取值范围", "该属性允许的所有合法取值集合（如年龄域为 0~120 的整数）"], ["==分量（Component）==", "元组在某一属性上的取值（单元格数据）", "行与列交叉点上的单一数据值"], ["==候选码 / 主码（Primary Key）==", "表中能唯一标识一个元组的属性或属性集", "主码的值不能重复且==绝不能为空（实体完整性）=="]]}, {"id": "b1-1-5-3-b2", "t": "table", "imp": "core", "title": "关系模型的三类完整性约束（必考大题）", "headers": ["完整性约束类型", "规则核心内涵要求", "违规报错现象举例"], "rows": [["==实体完整性（Entity Integrity）==", "==关系的主键属性（主属性）不能取空值（NULL），且必须唯一==", "学生表中新插入学生记录的学号为空或与已有学号重复"], ["==参照完整性（Referential Integrity）==", "外键的值要么等于被参照表的主键值，==要么取空值（NULL）==", "选课表中学生学号填写了一个学生表里根本不存在的学号"], ["==用户定义完整性==", "针对特定应用领域的具体语义要求（由用户自行设定）", "如学生年龄字段设定 `CHECK (age BETWEEN 0 AND 100)`"]]}]'::jsonb, '', 'B1-1.5.3 关系数据模型。 关系模型专业术语与日常表格概念对照（专转本高频选择题） 关系模型专业数学术语 日常平常常用表格词汇 数学定义与说明 关系（Relation） 一张二维表（Table） 笛卡尔积的子集，二维表中的数据集合 元组（Tuple） 表中的一行记录（Row / Record） 一个具体实体的完整属性值集合 属性（Attribute） 表中的一列字段（Column / Field） 实体所具有的某一特征，表中每一列有名字 域（Domain） 属性的取值范围 该属性允许的所有合法取值集合（如年龄域为 0~120 的整数） 分量（Component） 元组在某一属性上的取值（单元格数据） 行与列交叉点上的单一数据值 候选码 / 主码（Primary Key） 表中能唯一标识一个元组的属性或属性集 主码的值不能重复且绝不能为空（实体完整性） 关系模型的三类完整性约束（必考大题） 完整性约束类型 规则核心内涵要求 违规报错现象举例 实体完整性（Entity Integrity） 关系的主键属性（主属性）不能取空值（NULL），且必须唯一 学生表中新插入学生记录的学号为空或与已有学号重复 参照完整性（Referential Integrity） 外键的值要么等于被参照表的主键值，要么取空值（NULL） 选课表中学生学号填写了一个学生表里根本不存在的学号 用户定义完整性 针对特定应用领域的具体语义要求（由用户自行设定） 如学生年龄字段设定 CHECK (age BETWEEN 0 AND 100)', '{"pdf": "理论复习.pdf", "pages": [100]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.5.4 关系运算。 (node_id=163)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (163, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (163, 1, '[{"id": "b1-1-5-4-b1", "t": "table", "imp": "core", "title": "专门关系代数运算四大核心（专转本每考必出代数表达式）", "headers": ["关系代数运算", "数学符号", "运算本质与动作", "SQL 对应关键字"], "rows": [["==选择（Selection）==", "==σ (sigma)==", "在关系中选取满足给定逻辑条件的==“行（元组）”==", "==WHERE 子句=="], ["==投影（Projection）==", "==π (pi)==", "在关系中选取若干指定的==“列（属性）”==组成新关系（自动消除重复行）", "==SELECT 列名=="], ["==连接（Join）==", "==⋈==", "从两个关系的笛卡尔积中选取属性间满足一定条件的元组拼接成新关系", "==JOIN ... ON ...=="], ["==除运算（Division）==", "÷", "用于求解“选修了全部课程”、“至少包含某些属性集合”的综合查询条件", "嵌套带有 NOT EXISTS 的子查询"]]}, {"id": "b1-1-5-4-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "选择与投影动作记忆口诀", "text": "牢记：==选择是“横向切行”（过滤元组），投影是“纵向切列”（挑选字段）==。传统集合运算（并∪、交∩、差-）要求两个参与运算的关系必须具有相同的关系模式（同元数且对应属性域相同）。"}]'::jsonb, '', 'B1-1.5.4 关系运算。 专门关系代数运算四大核心（专转本每考必出代数表达式） 关系代数运算 数学符号 运算本质与动作 SQL 对应关键字 选择（Selection） σ (sigma) 在关系中选取满足给定逻辑条件的“行（元组）” WHERE 子句 投影（Projection） π (pi) 在关系中选取若干指定的“列（属性）”组成新关系（自动消除重复行） SELECT 列名 连接（Join） ⋈ 从两个关系的笛卡尔积中选取属性间满足一定条件的元组拼接成新关系 JOIN ... ON ... 除运算（Division） ÷ 用于求解“选修了全部课程”、“至少包含某些属性集合”的综合查询条件 嵌套带有 NOT EXISTS 的子查询 选择与投影动作记忆口诀 牢记：选择是“横向切行”（过滤元组），投影是“纵向切列”（挑选字段）。传统集合运算（并∪、交∩、差-）要求两个参与运算的关系必须具有相同的关系模式（同元数且对应属性域相同）。', '{"pdf": "理论复习.pdf", "pages": [100, 101]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.5.5 关系数据库语言 SQL。 (node_id=164)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (164, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (164, 1, '[{"id": "b1-1-5-5-b1", "t": "table", "imp": "core", "title": "SQL（结构化查询语言）四大语句类型", "headers": ["SQL 功能分类", "分类全称缩写", "核心包含指令动词", "功能描述"], "rows": [["==数据定义语言==", "==DDL==", "==CREATE, ALTER, DROP, TRUNCATE==", "定义或修改数据库、表、视图、索引的结构"], ["==数据操纵语言==", "==DML==", "==INSERT, UPDATE, DELETE==", "对表中的记录行进行增、改、删数据内容"], ["==数据查询语言==", "==DQL==", "==SELECT==", "从数据库中检索满足条件的数据（SQL 的核心灵魂）"], ["==数据控制语言==", "==DCL==", "==GRANT, REVOKE, COMMIT, ROLLBACK==", "权限分配回收与事务控制管理"]]}, {"id": "b1-1-5-5-b2", "t": "code", "lang": "sql", "imp": "important", "title": "专转本经典 SQL 综合查询模板", "code": "SELECT s.dept, COUNT(*) AS stu_cnt, AVG(s.age) AS avg_age\nFROM student s\nWHERE s.gender = ''男''\nGROUP BY s.dept\nHAVING COUNT(*) >= 5\nORDER BY avg_age DESC;"}, {"id": "b1-1-5-5-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "WHERE vs HAVING 核心考点", "text": "==WHERE 子句用于在“分组前”过滤行记录，条件中绝对不能包含聚合函数（如 SUM/AVG/COUNT）==；==HAVING 子句用于在“GROUP BY 分组后”对分组结果过滤，常与聚合函数连用==。"}]'::jsonb, '', 'B1-1.5.5 关系数据库语言 SQL。 SQL（结构化查询语言）四大语句类型 SQL 功能分类 分类全称缩写 核心包含指令动词 功能描述 数据定义语言 DDL CREATE, ALTER, DROP, TRUNCATE 定义或修改数据库、表、视图、索引的结构 数据操纵语言 DML INSERT, UPDATE, DELETE 对表中的记录行进行增、改、删数据内容 数据查询语言 DQL SELECT 从数据库中检索满足条件的数据（SQL 的核心灵魂） 数据控制语言 DCL GRANT, REVOKE, COMMIT, ROLLBACK 权限分配回收与事务控制管理 专转本经典 SQL 综合查询模板 SELECT s.dept, COUNT(*) AS stu_cnt, AVG(s.age) AS avg_age
FROM student s
WHERE s.gender = ''男''
GROUP BY s.dept
HAVING COUNT(*) >= 5
ORDER BY avg_age DESC; WHERE vs HAVING 核心考点 WHERE 子句用于在“分组前”过滤行记录，条件中绝对不能包含聚合函数（如 SUM/AVG/COUNT）；HAVING 子句用于在“GROUP BY 分组后”对分组结果过滤，常与聚合函数连用。', '{"pdf": "理论复习.pdf", "pages": [101]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B1-1.5.6 数据库系统及应用新技术。 (node_id=165)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (165, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (165, 1, '[{"id": "b1-1-5-6-b1", "t": "table", "imp": "core", "title": "现代数据库新技术体系与代表", "headers": ["新技术方向", "核心设计哲学与解决痛点", "代表性产品"], "rows": [["==分布式关系数据库（NewSQL）==", "保留传统关系型强一致事务（ACID）与标准 SQL，同时具备 NoSQL 的超大规模水平横向扩展能力", "==TiDB（国内开源分布式）、OceanBase（蚂蚁自研金融级）、Google Spanner=="], ["==云原生数据库（Cloud-Native DB）==", "采用==“存算分离”==架构，计算节点秒级扩容，存储底层共享分布式存储池", "阿里云 PolarDB、AWS Aurora、腾讯云 TDSQL"], ["==内存数据库（In-Memory DB）==", "将全部数据直接常驻内存，免除磁盘 I/O 寻道瓶颈，支持微秒级超高并发极速读写", "==Redis、SAP HANA=="], ["时序数据库（Time Series DB）", "专门优化时间戳序列传感器数据的海量追加写入与时间窗口聚合", "InfluxDB, TDengine, Prometheus"]]}, {"id": "b1-1-5-6-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "国之重器：自主可控国产数据库", "text": "我国在金融级核心交易场景打破甲骨文（Oracle）垄断，阿里蚂蚁集团自研的 ==OceanBase== 曾打破 TPC-C 国际基准性能测试世界纪录。"}]'::jsonb, '', 'B1-1.5.6 数据库系统及应用新技术。 现代数据库新技术体系与代表 新技术方向 核心设计哲学与解决痛点 代表性产品 分布式关系数据库（NewSQL） 保留传统关系型强一致事务（ACID）与标准 SQL，同时具备 NoSQL 的超大规模水平横向扩展能力 TiDB（国内开源分布式）、OceanBase（蚂蚁自研金融级）、Google Spanner 云原生数据库（Cloud-Native DB） 采用“存算分离”架构，计算节点秒级扩容，存储底层共享分布式存储池 阿里云 PolarDB、AWS Aurora、腾讯云 TDSQL 内存数据库（In-Memory DB） 将全部数据直接常驻内存，免除磁盘 I/O 寻道瓶颈，支持微秒级超高并发极速读写 Redis、SAP HANA 时序数据库（Time Series DB） 专门优化时间戳序列传感器数据的海量追加写入与时间窗口聚合 InfluxDB, TDengine, Prometheus 国之重器：自主可控国产数据库 我国在金融级核心交易场景打破甲骨文（Oracle）垄断，阿里蚂蚁集团自研的 OceanBase 曾打破 TPC-C 国际基准性能测试世界纪录。', '{"pdf": "理论复习.pdf", "pages": [101]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B2-2.1.1 物联网的基本概念。 (node_id=167)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (167, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (167, 1, '[{"id": "b2-2-1-1-b1", "t": "p", "imp": "core", "title": "物联网的定义与核心内涵", "text": "==物联网（Internet of Things，简称 IoT）==是指通过射频识别（RFID）、红外感应器、全球定位系统（GPS）、激光扫描器等信息传感设备，按约定的协议，把任何物品与互联网连接起来，进行信息交换和通信，以实现智能化识别、定位、跟踪、监控和管理的网络。其核心实质是==“物物相连、万物互联”=="}, {"id": "b2-2-1-1-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "物联网的核心基础", "text": "专转本高频考点：物联网的==业务与应用核心依然是互联网==，是在互联网基础上的延伸和扩展的网络；其用户端延伸和扩展到了任何物品与物品之间进行信息交换和通信。"}]'::jsonb, '', 'B2-2.1.1 物联网的基本概念。 物联网的定义与核心内涵 物联网（Internet of Things，简称 IoT）是指通过射频识别（RFID）、红外感应器、全球定位系统（GPS）、激光扫描器等信息传感设备，按约定的协议，把任何物品与互联网连接起来，进行信息交换和通信，以实现智能化识别、定位、跟踪、监控和管理的网络。其核心实质是“物物相连、万物互联” 物联网的核心基础 专转本高频考点：物联网的业务与应用核心依然是互联网，是在互联网基础上的延伸和扩展的网络；其用户端延伸和扩展到了任何物品与物品之间进行信息交换和通信。', '{"pdf": "理论复习.pdf", "pages": [102]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B2-2.1.2 物联网发展历程及国内外现状。 (node_id=168)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (168, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (168, 1, '[{"id": "b2-2-1-2-b1", "t": "table", "imp": "core", "title": "物联网发展历程标志性事件", "headers": ["年份/时期", "提出者/国家", "标志性事件与理念"], "rows": [["1995 年", "比尔·盖茨", "在《未来之路》中首次提及物物相联的设想"], ["==1999 年==", "==麻省理工学院（MIT）Auto-ID 中心==", "==Kevin Ashton 首次正式提出物联网（IoT）概念==，基于 RFID 和 EPC 体系"], ["2005 年", "国际电信联盟（ITU）", "发布《ITU 互联网报告 2005：物联网》，正式确立物联网定义"], ["2009 年", "中国（温家宝总理）", "在无锡提出==“感知中国”==战略构想，中国物联网发展全面提速"]]}, {"id": "b2-2-1-2-b2", "t": "list", "imp": "important", "title": "我国物联网产业现状", "items": ["建立无锡国家传感网创新示范区，形成长三角、环渤海、珠三角等多极产业协同集群", "我国在 NB-IoT（窄带物联网）、5G 物联网模组出货量与蜂窝物联网连接数均居世界前列，实现==“物超人”（移动物联网连接数超过移动电话用户数）=="]}]'::jsonb, '', 'B2-2.1.2 物联网发展历程及国内外现状。 物联网发展历程标志性事件 年份/时期 提出者/国家 标志性事件与理念 1995 年 比尔·盖茨 在《未来之路》中首次提及物物相联的设想 1999 年 麻省理工学院（MIT）Auto-ID 中心 Kevin Ashton 首次正式提出物联网（IoT）概念，基于 RFID 和 EPC 体系 2005 年 国际电信联盟（ITU） 发布《ITU 互联网报告 2005：物联网》，正式确立物联网定义 2009 年 中国（温家宝总理） 在无锡提出“感知中国”战略构想，中国物联网发展全面提速 我国物联网产业现状 建立无锡国家传感网创新示范区，形成长三角、环渤海、珠三角等多极产业协同集群 我国在 NB-IoT（窄带物联网）、5G 物联网模组出货量与蜂窝物联网连接数均居世界前列，实现“物超人”（移动物联网连接数超过移动电话用户数）', '{"pdf": "理论复习.pdf", "pages": [102, 103]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B2-2.1.3 物联网与互联网的区别。 (node_id=169)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (169, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (169, 1, '[{"id": "b2-2-1-3-b1", "t": "table", "imp": "core", "title": "物联网 vs 传统互联网的核心区别", "headers": ["对比维度", "传统互联网（Internet）", "物联网（IoT）"], "rows": [["==连接主体==", "以==“人”==为中心，连接计算机、智能手机等终端", "以==“物”==为中心，实现人与物、物与物的全面互联"], ["==信息来源==", "主要依靠人类主动输入、创建和发布信息", "依靠各类传感器、射频标签==自动感知、实时采集=="], ["==通信要求==", "追求高带宽、大吞吐量和长连接", "包含大量低功耗、低速率、低频偶发式海量数据上报（如水表抄表）"], ["==控制管理==", "侧重信息的检索、浏览与交互分享", "侧重对物理实体的实时在线监控、远程协同与闭环智能控制"]]}, {"id": "b2-2-1-3-b2", "t": "callout", "imp": "core", "kind": "tip", "title": "二者依存关系总结", "text": "物联网并不是独立于互联网的新网络，而是==以互联网为核心与承载通道的向物理世界的深度泛在拓展=="}]'::jsonb, '', 'B2-2.1.3 物联网与互联网的区别。 物联网 vs 传统互联网的核心区别 对比维度 传统互联网（Internet） 物联网（IoT） 连接主体 以“人”为中心，连接计算机、智能手机等终端 以“物”为中心，实现人与物、物与物的全面互联 信息来源 主要依靠人类主动输入、创建和发布信息 依靠各类传感器、射频标签自动感知、实时采集 通信要求 追求高带宽、大吞吐量和长连接 包含大量低功耗、低速率、低频偶发式海量数据上报（如水表抄表） 控制管理 侧重信息的检索、浏览与交互分享 侧重对物理实体的实时在线监控、远程协同与闭环智能控制 二者依存关系总结 物联网并不是独立于互联网的新网络，而是以互联网为核心与承载通道的向物理世界的深度泛在拓展', '{"pdf": "理论复习.pdf", "pages": [103]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B2-2.2.1 物联网三层体系结构。 (node_id=171)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (171, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (171, 1, '[{"id": "b2-2-2-1-b1", "t": "table", "imp": "core", "title": "物联网三层经典体系结构", "headers": ["体系层次", "核心功能定义", "典型设备与关键技术", "人体比喻"], "rows": [["==感知层（Sensing Layer）==", "全面感知物体信息，采集物理世界模拟量与数字量", "==RFID 电子标签、传感器、二维码、GPS、摄像头==", "==皮肤与感官=="], ["==网络层（Network Layer）==", "可靠、安全、长距离地将感知信息传输到计算中心", "==移动蜂窝网（4G/5G/NB-IoT）、互联网、有线宽带、局域网（Wi-Fi/蓝牙/ZigBee）==", "==神经中枢与脉络=="], ["==应用层（Application Layer）==", "结合行业需求对海量物联数据处理决策，提供智能服务", "智慧城市、智能家居、车联网、智能制造、云计算、大数据平台", "==大脑与执行器官=="]]}, {"id": "b2-2-2-1-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "分层判断高频题陷阱", "text": "选择题中识别技术归属层：==RFID 读写器、温湿度传感器属于感知层==；==无线局域网路由、5G 基站传输属于网络层==；==环境监控系统可视化大屏、智能水表计费软件属于应用层==。"}]'::jsonb, '', 'B2-2.2.1 物联网三层体系结构。 物联网三层经典体系结构 体系层次 核心功能定义 典型设备与关键技术 人体比喻 感知层（Sensing Layer） 全面感知物体信息，采集物理世界模拟量与数字量 RFID 电子标签、传感器、二维码、GPS、摄像头 皮肤与感官 网络层（Network Layer） 可靠、安全、长距离地将感知信息传输到计算中心 移动蜂窝网（4G/5G/NB-IoT）、互联网、有线宽带、局域网（Wi-Fi/蓝牙/ZigBee） 神经中枢与脉络 应用层（Application Layer） 结合行业需求对海量物联数据处理决策，提供智能服务 智慧城市、智能家居、车联网、智能制造、云计算、大数据平台 大脑与执行器官 分层判断高频题陷阱 选择题中识别技术归属层：RFID 读写器、温湿度传感器属于感知层；无线局域网路由、5G 基站传输属于网络层；环境监控系统可视化大屏、智能水表计费软件属于应用层。', '{"pdf": "理论复习.pdf", "pages": [103, 104]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B2-2.2.2 物联网感知层关键技术，RFID、EPC、传感器等技术基本原理。 (node_id=172)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (172, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (172, 1, '[{"id": "b2-2-2-2-b1", "t": "table", "imp": "core", "title": "RFID（射频识别）核心原理与分类", "headers": ["分类维度", "类型名称", "工作原理与供电", "特点与典型应用"], "rows": [["==按供电方式==", "==无源（被动）标签（Passive）==", "内部无电池，靠阅读器天线发出的射频电磁场感应供电", "成本极低、寿命长、读距短（数厘米到数米），公交卡、门禁卡"], ["按供电方式", "有源（主动）标签（Active）", "内置电池主动发射射频信号", "读距远（几十到百米）、成本高、寿命受限，ETC、集装箱追踪"], ["组成三要素", "==电子标签（Tag）、阅读器（Reader）、天线（Antenna）==", "阅读器通过天线发射射频载波，标签调制反射并解析数据", "实现==非接触式、多目标同时识别=="]]}, {"id": "b2-2-2-2-b2", "t": "list", "imp": "core", "title": "EPC 电子产品代码与传感器原理", "items": ["==EPC（Electronic Product Code）==：全球统一开放的产品全球唯一编码体系，是条形码的升级版，给全球每一个实体物品赋予唯一身份证", "==传感器（Sensor）==：能感受规定的被测量并按照一定规律转换成可用输出信号（通常为电信号）的器件，主要由==敏感元件、转换元件、变换电路==三部分组成"]}]'::jsonb, '', 'B2-2.2.2 物联网感知层关键技术，RFID、EPC、传感器等技术基本原理。 RFID（射频识别）核心原理与分类 分类维度 类型名称 工作原理与供电 特点与典型应用 按供电方式 无源（被动）标签（Passive） 内部无电池，靠阅读器天线发出的射频电磁场感应供电 成本极低、寿命长、读距短（数厘米到数米），公交卡、门禁卡 按供电方式 有源（主动）标签（Active） 内置电池主动发射射频信号 读距远（几十到百米）、成本高、寿命受限，ETC、集装箱追踪 组成三要素 电子标签（Tag）、阅读器（Reader）、天线（Antenna） 阅读器通过天线发射射频载波，标签调制反射并解析数据 实现非接触式、多目标同时识别 EPC 电子产品代码与传感器原理 EPC（Electronic Product Code）：全球统一开放的产品全球唯一编码体系，是条形码的升级版，给全球每一个实体物品赋予唯一身份证 传感器（Sensor）：能感受规定的被测量并按照一定规律转换成可用输出信号（通常为电信号）的器件，主要由敏感元件、转换元件、变换电路三部分组成', '{"pdf": "理论复习.pdf", "pages": [104, 105]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B2-2.2.3 物联网网络层关键技术，ZigBee、Wi-Fi、蓝牙等技术基本原理与特点。 (node_id=173)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (173, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (173, 1, '[{"id": "b2-2-2-3-b1", "t": "table", "imp": "core", "title": "短距离无线通信技术核心对比表（专转本高频必考）", "headers": ["通信技术", "IEEE 标准", "典型速率", "覆盖距离", "核心特点与主要应用"], "rows": [["==ZigBee（紫蜂）==", "==IEEE 802.15.4==", "250 kbps（低速）", "10 ~ 75 米", "==超低功耗、低成本、自组网（Mesh）、大网络容量（可容纳 65535 个节点）==，用于智能家居传感器组网"], ["==蓝牙（Bluetooth）==", "==IEEE 802.15.1==", "1 ~ 3 Mbps（BLE 更省电）", "10 米以内（PAN）", "点对点/主从星型连接、设备小巧，用于无线耳机、手环、手机近距互联"], ["==Wi-Fi（无线保真）==", "==IEEE 802.11 系列==", "数十 Mbps ~ 数 Gbps（高速）", "数十米到百米", "高带宽、高吞吐、功耗较大，用于家庭办公无线宽带接入与高速物联网终端"]]}, {"id": "b2-2-2-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "ZigBee 技术特性必记", "text": "牢记 ZigBee 的四大标签：==低功耗、低数据速率、低成本、支持自组网（Mesh 网状拓扑）==。在工业传感和智能家居照明传感器互联中居于支配地位。"}]'::jsonb, '', 'B2-2.2.3 物联网网络层关键技术，ZigBee、Wi-Fi、蓝牙等技术基本原理与特点。 短距离无线通信技术核心对比表（专转本高频必考） 通信技术 IEEE 标准 典型速率 覆盖距离 核心特点与主要应用 ZigBee（紫蜂） IEEE 802.15.4 250 kbps（低速） 10 ~ 75 米 超低功耗、低成本、自组网（Mesh）、大网络容量（可容纳 65535 个节点），用于智能家居传感器组网 蓝牙（Bluetooth） IEEE 802.15.1 1 ~ 3 Mbps（BLE 更省电） 10 米以内（PAN） 点对点/主从星型连接、设备小巧，用于无线耳机、手环、手机近距互联 Wi-Fi（无线保真） IEEE 802.11 系列 数十 Mbps ~ 数 Gbps（高速） 数十米到百米 高带宽、高吞吐、功耗较大，用于家庭办公无线宽带接入与高速物联网终端 ZigBee 技术特性必记 牢记 ZigBee 的四大标签：低功耗、低数据速率、低成本、支持自组网（Mesh 网状拓扑）。在工业传感和智能家居照明传感器互联中居于支配地位。', '{"pdf": "理论复习.pdf", "pages": [105, 106, 107]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B2-2.2.4 物联网应用层关键技术原理，物联网应用与云计算、大数据、人工智能等技术的融合。 (node_id=174)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (174, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (174, 1, '[{"id": "b2-2-2-4-b1", "t": "list", "imp": "core", "title": "物联网应用层关键支撑技术", "items": ["==中间件技术（Middleware）==：屏蔽底层异构硬件设备通信协议差异，为上层应用提供统一 API 和数据抽象服务", "==边缘计算（Edge Computing）==：在靠近物或数据源头的网络边缘侧，就近提供计算和存储服务，降低延迟并减轻骨干网带宽压力", "数字孪生（Digital Twin）：在数字空间构建物理实体的全要素动态镜像仿真"]}, {"id": "b2-2-2-4-b2", "t": "table", "imp": "core", "title": "物联网与前沿新兴技术的深度融合", "headers": ["融合方向", "协同互补机制", "典型落地应用"], "rows": [["==IoT + 云计算==", "为千万级并发设备连接提供弹性的海量数据入库与计算平台", "阿里云 IoT 物联网平台、华为云 OceanConnect"], ["==IoT + 大数据==", "对海量传感器时序数据做统计挖掘与关联分析", "设备预测性维护、耗电异常诊断、智能管网漏损监控"], ["==IoT + 人工智能==", "赋予物联网终端“边缘推理能力”，实现端侧智能", "人脸识别门禁闸机、工业缺陷检测相机、自动巡检无人机"]]}]'::jsonb, '', 'B2-2.2.4 物联网应用层关键技术原理，物联网应用与云计算、大数据、人工智能等技术的融合。 物联网应用层关键支撑技术 中间件技术（Middleware）：屏蔽底层异构硬件设备通信协议差异，为上层应用提供统一 API 和数据抽象服务 边缘计算（Edge Computing）：在靠近物或数据源头的网络边缘侧，就近提供计算和存储服务，降低延迟并减轻骨干网带宽压力 数字孪生（Digital Twin）：在数字空间构建物理实体的全要素动态镜像仿真 物联网与前沿新兴技术的深度融合 融合方向 协同互补机制 典型落地应用 IoT + 云计算 为千万级并发设备连接提供弹性的海量数据入库与计算平台 阿里云 IoT 物联网平台、华为云 OceanConnect IoT + 大数据 对海量传感器时序数据做统计挖掘与关联分析 设备预测性维护、耗电异常诊断、智能管网漏损监控 IoT + 人工智能 赋予物联网终端“边缘推理能力”，实现端侧智能 人脸识别门禁闸机、工业缺陷检测相机、自动巡检无人机', '{"pdf": "理论复习.pdf", "pages": [107, 108]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B2-2.3.1 物联网技术在智慧物流、智慧医疗、智能家居、智能制造、智能交通、现代农业等领域应用。 (node_id=176)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (176, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (176, 1, '[{"id": "b2-2-3-1-b1", "t": "table", "imp": "core", "title": "物联网重点行业典型落地应用", "headers": ["应用领域", "核心物联网技术手段", "具体场景实例"], "rows": [["==智慧物流==", "RFID 电子标签、条码、GPS/北斗定位", "包裹扫码秒级自动分拣、冷链运输温湿度全程追溯"], ["==智慧医疗==", "RFID 手环、无线传感生命体征采集", "新生儿防盗手环、ICU 患者体征连续监测、医疗耗材溯源"], ["==智能家居==", "ZigBee/Wi-Fi 组网、智能网关", "智能门锁、智能窗帘感应开合、手机远程控制空调"], ["==智能交通==", "地磁传感器、视频识别、DSRC/C-V2X", "==高速公路 ETC 无感扣费==、路口智能红绿灯、停车位智能引导"]]}, {"id": "b2-2-3-1-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "ETC 原理常考", "text": "高速公路不停车电子收费系统（ETC）利用车辆挡风玻璃上的车载单元（OBU）与收费站车道天线（RSU）之间的==专用短程通信技术（DSRC）及 RFID 射频技术==实现自动结算。"}]'::jsonb, '', 'B2-2.3.1 物联网技术在智慧物流、智慧医疗、智能家居、智能制造、智能交通、现代农业等领域应用。 物联网重点行业典型落地应用 应用领域 核心物联网技术手段 具体场景实例 智慧物流 RFID 电子标签、条码、GPS/北斗定位 包裹扫码秒级自动分拣、冷链运输温湿度全程追溯 智慧医疗 RFID 手环、无线传感生命体征采集 新生儿防盗手环、ICU 患者体征连续监测、医疗耗材溯源 智能家居 ZigBee/Wi-Fi 组网、智能网关 智能门锁、智能窗帘感应开合、手机远程控制空调 智能交通 地磁传感器、视频识别、DSRC/C-V2X 高速公路 ETC 无感扣费、路口智能红绿灯、停车位智能引导 ETC 原理常考 高速公路不停车电子收费系统（ETC）利用车辆挡风玻璃上的车载单元（OBU）与收费站车道天线（RSU）之间的专用短程通信技术（DSRC）及 RFID 射频技术实现自动结算。', '{"pdf": "理论复习.pdf", "pages": [108, 109, 110]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B2-2.3.2 物联网技术未来发展趋势。 (node_id=177)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (177, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (177, 1, '[{"id": "b2-2-3-2-b1", "t": "list", "imp": "core", "title": "物联网技术演进趋势", "items": ["==5G/6G 与 RedCap 广域赋能==：大连接、低时延特性让工业级远程操控与车联网成为现实", "==AIoT（人工智能物联网）深入发展==：万物互联（IoT）迈向万物智联（AIoT），终端兼具感知与推理计算", "==无源物联（Ambient IoT）==：利用环境中的微光、射频能量自供电通信，打破电池续航限制", "物联网设备安全与固件加固：解决海量设备弱密码、被黑客劫持为僵尸网络（DDoS）的安全隐患"]}, {"id": "b2-2-3-2-b2", "t": "callout", "imp": "normal", "kind": "tip", "title": "AIoT 概念", "text": "==AIoT 即 AI + IoT==，指人工智能技术与物联网在实际应用中落地融合，让物联网终端设备不仅能收集数据，更具备自主分析判断的“大脑”。"}]'::jsonb, '', 'B2-2.3.2 物联网技术未来发展趋势。 物联网技术演进趋势 5G/6G 与 RedCap 广域赋能：大连接、低时延特性让工业级远程操控与车联网成为现实 AIoT（人工智能物联网）深入发展：万物互联（IoT）迈向万物智联（AIoT），终端兼具感知与推理计算 无源物联（Ambient IoT）：利用环境中的微光、射频能量自供电通信，打破电池续航限制 物联网设备安全与固件加固：解决海量设备弱密码、被黑客劫持为僵尸网络（DDoS）的安全隐患 AIoT 概念 AIoT 即 AI + IoT，指人工智能技术与物联网在实际应用中落地融合，让物联网终端设备不仅能收集数据，更具备自主分析判断的“大脑”。', '{"pdf": "理论复习.pdf", "pages": [110]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B3-3.1.1 移动互联网的基本概念。 (node_id=179)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (179, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (179, 1, '[{"id": "b3-3-1-1-b1", "t": "p", "imp": "core", "title": "移动互联网的定义与公式", "text": "==移动互联网（Mobile Internet）==是移动通信与互联网相结合的产物，是移动通信技术和互联网技术、服务、商业模式融合的综合体。其本质是用户使用手机、平板等移动便携式智能终端，通过无线移动蜂窝网络或无线局域网接入互联网，享受各类信息服务。公式表示为：==移动互联网 = 移动通信网络 + 互联网=="}, {"id": "b3-3-1-1-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "核心辨析", "text": "移动互联网绝非将传统 PC 互联网内容简单地平移搬到手机屏幕上，而是结合了==移动性、便携性、位置感知与即时性==等特性的全新生态。"}]'::jsonb, '', 'B3-3.1.1 移动互联网的基本概念。 移动互联网的定义与公式 移动互联网（Mobile Internet）是移动通信与互联网相结合的产物，是移动通信技术和互联网技术、服务、商业模式融合的综合体。其本质是用户使用手机、平板等移动便携式智能终端，通过无线移动蜂窝网络或无线局域网接入互联网，享受各类信息服务。公式表示为：移动互联网 = 移动通信网络 + 互联网 核心辨析 移动互联网绝非将传统 PC 互联网内容简单地平移搬到手机屏幕上，而是结合了移动性、便携性、位置感知与即时性等特性的全新生态。', '{"pdf": "理论复习.pdf", "pages": [111]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B3-3.1.2 移动互联网的特征。 (node_id=180)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (180, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (180, 1, '[{"id": "b3-3-1-2-b1", "t": "table", "imp": "core", "title": "移动互联网五大典型特征（专转本高频考点）", "headers": ["主要特征", "核心内涵", "表现与应用场景"], "rows": [["==移动性与便携性==", "用户不受固定地理位置与网线束缚，终端轻便小巧随时随身携带", "公交、地铁、旅行中随时掏出手机上网处理事务"], ["==永远在线（Always Online）==", "终端全天候与基站保持信令连接，后台消息实时接收推送", "微信消息即时提醒、邮件即时推送通知"], ["==位置相关性（LBS）==", "结合 GPS/基站/Wi-Fi 定位，提供基于地理位置的定制化服务", "周边美食搜索、打车定位、实时地图导航"], ["==强隐私与个人属性==", "移动设备通常为个人独占私有，绑定用户真实身份与隐私", "指纹/面容解锁、手机验证码、移动支付认证"], ["终端资源受限性", "屏幕尺寸小、计算能力、存储容量及电池续航相比 PC 相对有限", "需要轻量化 App 架构与高效电源管理"]]}, {"id": "b3-3-1-2-b2", "t": "callout", "imp": "core", "kind": "tip", "title": "记忆技巧", "text": "核心五大特征记住四个字：==“移、随、位、私、限”==（移动便携、随时在线、位置服务、私人私密、终端受限）。"}]'::jsonb, '', 'B3-3.1.2 移动互联网的特征。 移动互联网五大典型特征（专转本高频考点） 主要特征 核心内涵 表现与应用场景 移动性与便携性 用户不受固定地理位置与网线束缚，终端轻便小巧随时随身携带 公交、地铁、旅行中随时掏出手机上网处理事务 永远在线（Always Online） 终端全天候与基站保持信令连接，后台消息实时接收推送 微信消息即时提醒、邮件即时推送通知 位置相关性（LBS） 结合 GPS/基站/Wi-Fi 定位，提供基于地理位置的定制化服务 周边美食搜索、打车定位、实时地图导航 强隐私与个人属性 移动设备通常为个人独占私有，绑定用户真实身份与隐私 指纹/面容解锁、手机验证码、移动支付认证 终端资源受限性 屏幕尺寸小、计算能力、存储容量及电池续航相比 PC 相对有限 需要轻量化 App 架构与高效电源管理 记忆技巧 核心五大特征记住四个字：“移、随、位、私、限”（移动便携、随时在线、位置服务、私人私密、终端受限）。', '{"pdf": "理论复习.pdf", "pages": [111, 112]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B3-3.1.3 移动互联网的发展历程。 (node_id=181)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (181, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (181, 1, '[{"id": "b3-3-1-3-b1", "t": "table", "imp": "core", "title": "移动通信网络演进历程（1G 到 5G）", "headers": ["代际", "核心技术", "代表制式/标准", "业务形态与峰值速率"], "rows": [["==1G（第一代）==", "模拟通信技术", "FDMA、AMPS、TACS（“大哥大”）", "仅支持语音通话，易被窃听串号"], ["==2G（第二代）==", "数字语音技术", "==GSM、CDMA、GPRS==", "数字化语音通信，支持短信（SMS）和低速上网"], ["==3G（第三代）==", "码分多址高速数据", "==WCDMA、CDMA2000、TD-SCDMA（我国自主标准）==", "峰值数 Mbps，支持手机网页浏览和视频通话"], ["==4G（第四代）==", "OFDMA 与 MIMO", "==LTE-FDD、TD-LTE（我国主导）==", "峰值 100 Mbps，移动支付、高清短视频爆发"], ["==5G（第五代）==", "超密集组网、大规模天线", "5G NR（3GPP Release 15+）", "峰值 10~20 Gbps，万物互联与低时延高可靠"]]}, {"id": "b3-3-1-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "中国 3G/4G 自主标准考点", "text": "==我国主导提出的 3G 国际标准是 TD-SCDMA==；我国主导提出的 4G 国际标准是 ==TD-LTE==。这是专转本历史高频选择题考点。"}]'::jsonb, '', 'B3-3.1.3 移动互联网的发展历程。 移动通信网络演进历程（1G 到 5G） 代际 核心技术 代表制式/标准 业务形态与峰值速率 1G（第一代） 模拟通信技术 FDMA、AMPS、TACS（“大哥大”） 仅支持语音通话，易被窃听串号 2G（第二代） 数字语音技术 GSM、CDMA、GPRS 数字化语音通信，支持短信（SMS）和低速上网 3G（第三代） 码分多址高速数据 WCDMA、CDMA2000、TD-SCDMA（我国自主标准） 峰值数 Mbps，支持手机网页浏览和视频通话 4G（第四代） OFDMA 与 MIMO LTE-FDD、TD-LTE（我国主导） 峰值 100 Mbps，移动支付、高清短视频爆发 5G（第五代） 超密集组网、大规模天线 5G NR（3GPP Release 15+） 峰值 10~20 Gbps，万物互联与低时延高可靠 中国 3G/4G 自主标准考点 我国主导提出的 3G 国际标准是 TD-SCDMA；我国主导提出的 4G 国际标准是 TD-LTE。这是专转本历史高频选择题考点。', '{"pdf": "理论复习.pdf", "pages": [112]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B3-3.1.4 5G 关键技术和主要优势。 (node_id=182)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (182, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (182, 1, '[{"id": "b3-3-1-4-b1", "t": "table", "imp": "core", "title": "5G 三大核心应用场景（ITU 规范，必须背熟）", "headers": ["场景缩写", "场景中文全称", "核心性能指标要求", "典型落地应用"], "rows": [["==eMBB==", "==增强型移动宽带==", "用户体验速率 1 Gbps，峰值速率可达 20 Gbps", "4K/8K 超高清直播、AR/VR 沉浸式交互、裸眼 3D"], ["==uRLLC==", "==超高可靠超低时延通信==", "空口传输==时延低至 1 毫秒==，可靠性达 99.999%", "==车联网（自动驾驶）、远程手术示教、工业机器人精准控制=="], ["==mMTC==", "==海量机器类通信==", "==连接密度达到每平方公里 100 万个连接==", "智能水表抄表、智慧物流仓储传感、智慧城市井盖管网监控"]]}, {"id": "b3-3-1-4-b2", "t": "list", "imp": "core", "title": "5G 关键赋能技术", "items": ["==大规模天线阵列（Massive MIMO）==：基站配置数十乃至数百根天线，大幅提升频谱利用效率与波束赋形精确度", "==网络切片（Network Slicing）==：基于 SDN/NFV 在统一物理网络上虚拟出满足不同 QoS 需求的端到端逻辑专用网络", "==毫米波通信（Millimeter Wave）与边缘计算（MEC）==：开拓高频段频谱资源，在基站边缘分流降低骨干网络传输往返延迟"]}]'::jsonb, '', 'B3-3.1.4 5G 关键技术和主要优势。 5G 三大核心应用场景（ITU 规范，必须背熟） 场景缩写 场景中文全称 核心性能指标要求 典型落地应用 eMBB 增强型移动宽带 用户体验速率 1 Gbps，峰值速率可达 20 Gbps 4K/8K 超高清直播、AR/VR 沉浸式交互、裸眼 3D uRLLC 超高可靠超低时延通信 空口传输时延低至 1 毫秒，可靠性达 99.999% 车联网（自动驾驶）、远程手术示教、工业机器人精准控制 mMTC 海量机器类通信 连接密度达到每平方公里 100 万个连接 智能水表抄表、智慧物流仓储传感、智慧城市井盖管网监控 5G 关键赋能技术 大规模天线阵列（Massive MIMO）：基站配置数十乃至数百根天线，大幅提升频谱利用效率与波束赋形精确度 网络切片（Network Slicing）：基于 SDN/NFV 在统一物理网络上虚拟出满足不同 QoS 需求的端到端逻辑专用网络 毫米波通信（Millimeter Wave）与边缘计算（MEC）：开拓高频段频谱资源，在基站边缘分流降低骨干网络传输往返延迟', '{"pdf": "理论复习.pdf", "pages": [112, 113]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B3-3.2.1 SOA 面向服务架构的基本概念。 (node_id=184)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (184, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (184, 1, '[{"id": "b3-3-2-1-b1", "t": "p", "imp": "core", "title": "SOA 的定义与核心原则", "text": "==面向服务的架构（Service-Oriented Architecture，简称 SOA）==是一种软件系统架构设计风格，它将应用程序的不同功能单元抽象为==松散耦合的服务（Services）==。服务之间通过定义明确的接口和协议（如 HTTP、SOAP、REST）进行调用，而无需了解底层具体编程语言与硬件平台实现。"}, {"id": "b3-3-2-1-b2", "t": "table", "imp": "core", "title": "SOA 架构的三大核心角色与交互动作", "headers": ["架构角色", "功能职责", "对应的交互动作"], "rows": [["==服务提供者（Service Provider）==", "创建并实现具体服务功能实体，向注册中心发布接口信息", "==发布（Publish）=="], ["==服务注册中心（Service Broker）==", "维护服务元数据目录，提供查询检索机制", "==注册与发现（Registry）=="], ["==服务请求者（Service Consumer）==", "发起业务请求，查询注册中心定位服务后发起远程调用", "==查找（Find）与绑定（Bind）=="]]}]'::jsonb, '', 'B3-3.2.1 SOA 面向服务架构的基本概念。 SOA 的定义与核心原则 面向服务的架构（Service-Oriented Architecture，简称 SOA）是一种软件系统架构设计风格，它将应用程序的不同功能单元抽象为松散耦合的服务（Services）。服务之间通过定义明确的接口和协议（如 HTTP、SOAP、REST）进行调用，而无需了解底层具体编程语言与硬件平台实现。 SOA 架构的三大核心角色与交互动作 架构角色 功能职责 对应的交互动作 服务提供者（Service Provider） 创建并实现具体服务功能实体，向注册中心发布接口信息 发布（Publish） 服务注册中心（Service Broker） 维护服务元数据目录，提供查询检索机制 注册与发现（Registry） 服务请求者（Service Consumer） 发起业务请求，查询注册中心定位服务后发起远程调用 查找（Find）与绑定（Bind）', '{"pdf": "理论复习.pdf", "pages": [113, 114]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B3-3.2.2 Web2.0 的含义。 (node_id=185)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (185, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (185, 1, '[{"id": "b3-3-2-2-b1", "t": "table", "imp": "core", "title": "Web 1.0 vs Web 2.0 核心演进对比", "headers": ["对比维度", "Web 1.0 时代", "Web 2.0 时代"], "rows": [["==内容生成方式==", "以网站运营编辑者单向生产为主（PGC）", "==用户贡献内容（UGC，User-Generated Content）=="], ["==交互模式==", "用户纯被动浏览、静态只读网页", "==双向互动、评论、点赞、关注、个性化订阅=="], ["==技术支撑==", "静态 HTML 页面、CGI 脚本", "==Ajax 异步局部刷新、富互联网应用（RIA）、JSON 数据交互=="], ["典型代表产品", "新浪/搜狐传统新闻门户网、黄页", "博客、微博、知乎、微信朋友圈、维基百科"]]}, {"id": "b3-3-2-2-b2", "t": "callout", "imp": "core", "kind": "tip", "title": "核心关键词", "text": "牢记 Web 2.0 的灵魂三大关键词：==以人为本、分享互动、用户生产内容（UGC）==。"}]'::jsonb, '', 'B3-3.2.2 Web2.0 的含义。 Web 1.0 vs Web 2.0 核心演进对比 对比维度 Web 1.0 时代 Web 2.0 时代 内容生成方式 以网站运营编辑者单向生产为主（PGC） 用户贡献内容（UGC，User-Generated Content） 交互模式 用户纯被动浏览、静态只读网页 双向互动、评论、点赞、关注、个性化订阅 技术支撑 静态 HTML 页面、CGI 脚本 Ajax 异步局部刷新、富互联网应用（RIA）、JSON 数据交互 典型代表产品 新浪/搜狐传统新闻门户网、黄页 博客、微博、知乎、微信朋友圈、维基百科 核心关键词 牢记 Web 2.0 的灵魂三大关键词：以人为本、分享互动、用户生产内容（UGC）。', '{"pdf": "理论复习.pdf", "pages": [114]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B3-3.2.3 HTML5 的新特性。 (node_id=186)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (186, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (186, 1, '[{"id": "b3-3-2-3-b1", "t": "table", "imp": "core", "title": "HTML5 革命性新特性梳理", "headers": ["新特性分类", "新增核心标签/API", "功能说明与传统做法对比"], "rows": [["==原生多媒体支持==", "`<audio>`、`<video>` 标签", "==无需安装 Flash 等第三方播放器插件==即可在浏览器内原生播放音视频"], ["==语义化标签结构==", "`<header>`, `<footer>`, `<nav>`, `<article>`, `<section>`", "取代过去滥用 `<div>`，提升页面可读性、无障碍访问和 SEO"], ["==2D/3D 绘图渲染==", "`<canvas>` 元素、WebGL 接口", "支持使用 JavaScript 在页面上实时绘制动态交互图形与游戏图表"], ["==本地持久化存储==", "`localStorage` 与 `sessionStorage`", "容量达 5MB+（远大于传统 Cookie 的 4KB 限制），不随 HTTP 请求自动上传"], ["地理位置 API", "`navigator.geolocation`", "原生获取移动终端当前经纬度位置"]]}, {"id": "b3-3-2-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "localStorage vs sessionStorage", "text": "==localStorage 是永久存储==，除非手动清除否则关闭浏览器一直存在；==sessionStorage 是会话级存储==，关闭当前浏览器标签页或窗口即自动销毁。"}]'::jsonb, '', 'B3-3.2.3 HTML5 的新特性。 HTML5 革命性新特性梳理 新特性分类 新增核心标签/API 功能说明与传统做法对比 原生多媒体支持 <audio>、<video> 标签 无需安装 Flash 等第三方播放器插件即可在浏览器内原生播放音视频 语义化标签结构 <header>, <footer>, <nav>, <article>, <section> 取代过去滥用 <div>，提升页面可读性、无障碍访问和 SEO 2D/3D 绘图渲染 <canvas> 元素、WebGL 接口 支持使用 JavaScript 在页面上实时绘制动态交互图形与游戏图表 本地持久化存储 localStorage 与 sessionStorage 容量达 5MB+（远大于传统 Cookie 的 4KB 限制），不随 HTTP 请求自动上传 地理位置 API navigator.geolocation 原生获取移动终端当前经纬度位置 localStorage vs sessionStorage localStorage 是永久存储，除非手动清除否则关闭浏览器一直存在；sessionStorage 是会话级存储，关闭当前浏览器标签页或窗口即自动销毁。', '{"pdf": "理论复习.pdf", "pages": [114, 115]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B3-3.2.4 Android 的系统架构。 (node_id=187)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (187, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (187, 1, '[{"id": "b3-3-2-4-b1", "t": "table", "imp": "core", "title": "Android 经典四层体系架构（自顶向下，必考）", "headers": ["层级名称", "英文标识", "主要包含内容与组件"], "rows": [["==1. 应用程序层==", "Applications", "系统自带及用户安装的应用：如电话、短信、浏览器、微信等，主要用 Java/Kotlin 编写"], ["==2. 应用程序框架层==", "Application Framework", "==四大组件管理器（Activity Manager、Window Manager、Content Provider、Notification Manager 等）=="], ["==3. 系统运行时与核心库==", "Libraries & Android Runtime (ART)", "C/C++ 本地核心系统库（OpenGL、WebKit、SQLite 等）+ ==ART 虚拟机（早期为 Dalvik）=="], ["==4. Linux 内核层==", "Linux Kernel", "==基于 Linux 内核==，负责底层硬件驱动（显示驱动、蓝牙驱动、电源管理、Binder IPC 驱动等）"]]}, {"id": "b3-3-2-4-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "Android 底层核心考点", "text": "专转本必考题：==Android 操作系统的底层是基于 Linux 内核开发的==；Android 应用程序运行在定制的虚拟机中（早期为 Dalvik，后升级为采用 AOT/JIT 混合编译的 ART 虚拟机）。"}]'::jsonb, '', 'B3-3.2.4 Android 的系统架构。 Android 经典四层体系架构（自顶向下，必考） 层级名称 英文标识 主要包含内容与组件 1. 应用程序层 Applications 系统自带及用户安装的应用：如电话、短信、浏览器、微信等，主要用 Java/Kotlin 编写 2. 应用程序框架层 Application Framework 四大组件管理器（Activity Manager、Window Manager、Content Provider、Notification Manager 等） 3. 系统运行时与核心库 Libraries & Android Runtime (ART) C/C++ 本地核心系统库（OpenGL、WebKit、SQLite 等）+ ART 虚拟机（早期为 Dalvik） 4. Linux 内核层 Linux Kernel 基于 Linux 内核，负责底层硬件驱动（显示驱动、蓝牙驱动、电源管理、Binder IPC 驱动等） Android 底层核心考点 专转本必考题：Android 操作系统的底层是基于 Linux 内核开发的；Android 应用程序运行在定制的虚拟机中（早期为 Dalvik，后升级为采用 AOT/JIT 混合编译的 ART 虚拟机）。', '{"pdf": "理论复习.pdf", "pages": [115]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B3-3.2.5 iOS 的系统架构。 (node_id=188)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (188, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (188, 1, '[{"id": "b3-3-2-5-b1", "t": "table", "imp": "core", "title": "iOS 操作系统四层架构（自顶向下）", "headers": ["层级名称", "英文名称", "功能定位与核心组件"], "rows": [["==1. 触摸层（Cocoa Touch 层）==", "Cocoa Touch Layer", "直接面向 UI 交互与触控事件处理（UIKit 框架、手势识别、多任务调度）"], ["==2. 媒体层==", "Media Layer", "提供音频、视频、2D/3D 图形技术（Core Graphics、OpenGL ES/Metal、AVFoundation）"], ["==3. 核心服务层==", "Core Services Layer", "基础系统服务与数据管理（Core Foundation、网络连接、SQLite 数据库引擎、位置服务）"], ["==4. 核心操作系统层==", "Core OS Layer", "==基于 Darwin 内核（Mach微内核 + BSD）==，提供文件系统、网络套接字、硬件驱动与安全认证"]]}, {"id": "b3-3-2-5-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "Android vs iOS 对比常考", "text": "Android 属于开源生态（由 Google 和开放手机联盟主导），底层是 Linux；iOS 属于苹果闭源生态，底层基于 Darwin 内核。iOS 的沙盒机制（Sandbox）确保应用数据彼此完全隔离。"}]'::jsonb, '', 'B3-3.2.5 iOS 的系统架构。 iOS 操作系统四层架构（自顶向下） 层级名称 英文名称 功能定位与核心组件 1. 触摸层（Cocoa Touch 层） Cocoa Touch Layer 直接面向 UI 交互与触控事件处理（UIKit 框架、手势识别、多任务调度） 2. 媒体层 Media Layer 提供音频、视频、2D/3D 图形技术（Core Graphics、OpenGL ES/Metal、AVFoundation） 3. 核心服务层 Core Services Layer 基础系统服务与数据管理（Core Foundation、网络连接、SQLite 数据库引擎、位置服务） 4. 核心操作系统层 Core OS Layer 基于 Darwin 内核（Mach微内核 + BSD），提供文件系统、网络套接字、硬件驱动与安全认证 Android vs iOS 对比常考 Android 属于开源生态（由 Google 和开放手机联盟主导），底层是 Linux；iOS 属于苹果闭源生态，底层基于 Darwin 内核。iOS 的沙盒机制（Sandbox）确保应用数据彼此完全隔离。', '{"pdf": "理论复习.pdf", "pages": [115, 116]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

