INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (190, 1, '[{"id": "b3-3-3-1-b1", "t": "table", "imp": "core", "title": "移动互联网关键行业应用落地", "headers": ["应用领域", "典型应用模式", "代表产品或服务"], "rows": [["==移动金融==", "手机银行、移动第三方扫码支付、数字钱包、在线理财", "微信支付、支付宝、云闪付、掌上银行 App"], ["==电子政务==", "政务服务掌上办、移动公积金查询、健康码/医保电子凭证", "“苏服办”、“国家政务服务平台”微信/支付宝小程序"], ["==移动娱乐==", "移动短视频、在线音乐、移动竞技游戏、移动网络文学", "抖音、快手、QQ 音乐、王者荣耀、微信读书"]]}, {"id": "b3-3-3-1-b2", "t": "callout", "imp": "normal", "kind": "tip", "title": "移动支付的普及价值", "text": "二维码扫码支付以其极低的商户部署成本与极高的普及率，极大推进了我国无现金社会与微型商业数字化的建设。"}]'::jsonb, '', 'B3-3.3.1 移动互联网在金融服务、电子政务、娱乐等领域的应用。 移动互联网关键行业应用落地 应用领域 典型应用模式 代表产品或服务 移动金融 手机银行、移动第三方扫码支付、数字钱包、在线理财 微信支付、支付宝、云闪付、掌上银行 App 电子政务 政务服务掌上办、移动公积金查询、健康码/医保电子凭证 “苏服办”、“国家政务服务平台”微信/支付宝小程序 移动娱乐 移动短视频、在线音乐、移动竞技游戏、移动网络文学 抖音、快手、QQ 音乐、王者荣耀、微信读书 移动支付的普及价值 二维码扫码支付以其极低的商户部署成本与极高的普及率，极大推进了我国无现金社会与微型商业数字化的建设。', '{"pdf": "理论复习.pdf", "pages": [116]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

