INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (191, 1, '[{"id": "b3-3-3-2-b1", "t": "list", "imp": "core", "title": "移动互联网核心未来演进方向", "items": ["==5G/6G 深度融合与产业互联网化==：从单纯面向消费者的“消费互联网（To C）”大步迈向赋能千行百业的“产业互联网（To B）”", "==终端形态与交互多态化==：折叠屏、智能手表、AR/VR 眼镜等多形态终端多端协同，跨屏无缝流转", "==端侧 AI 与大模型应用结合==：移动终端内置独立 NPU 神经处理单元，实现端侧离线智能处理与个性化生成式助手", "网络与数据主权安全：APP 违法违规收集个人信息治理、SDK 行为合规监控与全生命周期加密保护"]}, {"id": "b3-3-3-2-b2", "t": "callout", "imp": "important", "kind": "warn", "title": "消费互联网向产业互联网升级", "text": "移动互联网人口红利逐步见顶，未来发展的最大增量在于深度融入智能制造、智慧物流、工业互联网等产业互联网深水区。"}]'::jsonb, '', 'B3-3.3.2 移动互联网未来发展趋势。 移动互联网核心未来演进方向 5G/6G 深度融合与产业互联网化：从单纯面向消费者的“消费互联网（To C）”大步迈向赋能千行百业的“产业互联网（To B）” 终端形态与交互多态化：折叠屏、智能手表、AR/VR 眼镜等多形态终端多端协同，跨屏无缝流转 端侧 AI 与大模型应用结合：移动终端内置独立 NPU 神经处理单元，实现端侧离线智能处理与个性化生成式助手 网络与数据主权安全：APP 违法违规收集个人信息治理、SDK 行为合规监控与全生命周期加密保护 消费互联网向产业互联网升级 移动互联网人口红利逐步见顶，未来发展的最大增量在于深度融入智能制造、智慧物流、工业互联网等产业互联网深水区。', '{"pdf": "理论复习.pdf", "pages": [116]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B4-4.1.1 云计算的基本概念。 (node_id=193)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (193, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (193, 1, '[{"id": "b4-4-1-1-b1", "t": "p", "imp": "core", "title": "云计算的权威定义（NIST 定义）", "text": "==云计算（Cloud Computing）==是一种通过网络统一组织和灵活调用各种计算资源（如计算、存储、网络、软件），实现按需分配、计量计费、高可扩展的计算交付模式。根据美国国家标准与技术研究院（NIST）的定义，云计算是一种能够通过网络便捷地、按需访问可配置计算资源共享池的模式。比喻为：==像用水、用电一样按需使用计算资源，按量付费=="}, {"id": "b4-4-1-1-b2", "t": "table", "imp": "core", "title": "云计算五大基本特征（NIST 5 Essential Characteristics）", "headers": ["特征名称", "英文标识", "特征核心解释"], "rows": [["==按需自助服务==", "On-demand self-service", "用户无需与服务商人工交互，可自主自动获取计算能力（如申请云主机）"], ["==广泛的网络接入==", "Broad network access", "可通过标准机制经由各类网络（互联网/专线）从各种终端设备访问"], ["==资源池化==", "Resource pooling", "多租户共享计算资源池，资源以动态方式分配和重新分配"], ["==快速弹性伸缩==", "Rapid elasticity", "资源可迅速弹性供应和释放，可应对业务高并发峰值动态扩容"], ["==可度量的服务==", "Measured service", "资源使用情况根据实际占用（如 CPU 时间、存储 GB、流量）进行精确计量和计费"]]}]'::jsonb, '', 'B4-4.1.1 云计算的基本概念。 云计算的权威定义（NIST 定义） 云计算（Cloud Computing）是一种通过网络统一组织和灵活调用各种计算资源（如计算、存储、网络、软件），实现按需分配、计量计费、高可扩展的计算交付模式。根据美国国家标准与技术研究院（NIST）的定义，云计算是一种能够通过网络便捷地、按需访问可配置计算资源共享池的模式。比喻为：像用水、用电一样按需使用计算资源，按量付费 云计算五大基本特征（NIST 5 Essential Characteristics） 特征名称 英文标识 特征核心解释 按需自助服务 On-demand self-service 用户无需与服务商人工交互，可自主自动获取计算能力（如申请云主机） 广泛的网络接入 Broad network access 可通过标准机制经由各类网络（互联网/专线）从各种终端设备访问 资源池化 Resource pooling 多租户共享计算资源池，资源以动态方式分配和重新分配 快速弹性伸缩 Rapid elasticity 资源可迅速弹性供应和释放，可应对业务高并发峰值动态扩容 可度量的服务 Measured service 资源使用情况根据实际占用（如 CPU 时间、存储 GB、流量）进行精确计量和计费', '{"pdf": "理论复习.pdf", "pages": [117]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B4-4.1.2 云计算产生的历史背景。 (node_id=194)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (194, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (194, 1, '[{"id": "b4-4-1-2-b1", "t": "table", "imp": "core", "title": "云计算诞生的技术与商业驱动背景", "headers": ["驱动维度", "历史背景与核心痛点", "技术突破与催化"], "rows": [["==算力需求与资源闲置矛盾==", "企业传统自建数据中心（IDC）采购周期长、成本高昂，且平日服务器利用率极低（普遍不足 15%）", "亚马逊 AWS 率先将节日峰值富余计算资源对外出租，开创云计算商业化商业模式先河"], ["==互联网数据爆炸式增长==", "Web2.0 与移动应用爆发，海量非结构化数据急剧膨胀，单台大型机/超级计算机受物理摩尔定律限制难以为继", "==分布式计算技术（Google GFS/MapReduce）==证明利用海量廉价 PC 服务器集群可替代昂贵小型机"], ["==虚拟化与网络带宽普及==", "多租户在单台物理机上隔离运行困难", "==x86 硬件虚拟化（Intel VT-x）与宽带网络提速降费==为云计算扫清了技术障碍"]]}, {"id": "b4-4-1-2-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "麦卡锡公用计算理念", "text": "早在 1961 年，计算机科学家==约翰·麦卡锡（John McCarthy）就预言：“计算机计算能力终有一天可能会像自来水和电一样，成为一种公用事业设施（Utility Computing）。”== 云计算正是这一设想的真正实现。"}]'::jsonb, '', 'B4-4.1.2 云计算产生的历史背景。 云计算诞生的技术与商业驱动背景 驱动维度 历史背景与核心痛点 技术突破与催化 算力需求与资源闲置矛盾 企业传统自建数据中心（IDC）采购周期长、成本高昂，且平日服务器利用率极低（普遍不足 15%） 亚马逊 AWS 率先将节日峰值富余计算资源对外出租，开创云计算商业化商业模式先河 互联网数据爆炸式增长 Web2.0 与移动应用爆发，海量非结构化数据急剧膨胀，单台大型机/超级计算机受物理摩尔定律限制难以为继 分布式计算技术（Google GFS/MapReduce）证明利用海量廉价 PC 服务器集群可替代昂贵小型机 虚拟化与网络带宽普及 多租户在单台物理机上隔离运行困难 x86 硬件虚拟化（Intel VT-x）与宽带网络提速降费为云计算扫清了技术障碍 麦卡锡公用计算理念 早在 1961 年，计算机科学家约翰·麦卡锡（John McCarthy）就预言：“计算机计算能力终有一天可能会像自来水和电一样，成为一种公用事业设施（Utility Computing）。” 云计算正是这一设想的真正实现。', '{"pdf": "理论复习.pdf", "pages": [117, 118]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B4-4.1.3 云计算的优势。 (node_id=195)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (195, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (195, 1, '[{"id": "b4-4-1-3-b1", "t": "table", "imp": "core", "title": "企业采用云计算相比传统自建机房的核心优势", "headers": ["优势维度", "传统自建 IT 机房", "云计算服务模式"], "rows": [["==资本开支（成本）==", "需前期一次性巨额投入购买硬件与机房基础设施（CapEx 高）", "按需开通、按月按量付费，转变为日常运营支出（OpEx 显著降低）"], ["==部署与交付速度==", "硬件采购、上架、布线安装通常耗时数周甚至数月", "控制台或 API ==几分钟内秒级自动创建并交付数百台云服务器=="], ["==容灾与高可用性==", "单点故障风险高，双活容灾成本翻倍", "云厂商多可用区部署、自动故障迁移、多副本数据冗余，可用性达 99.99%+"], ["==运维与安全保障==", "需专门团队维护风火水电与网络安防，易受勒索病毒攻破", "云厂商集中顶尖安全专家防护，自动打补丁，免去底层硬件维护"]]}, {"id": "b4-4-1-3-b2", "t": "callout", "imp": "core", "kind": "tip", "title": "总结", "text": "云计算核心优势一句话概括：==降低成本、随需应变、极速弹性、安全可靠、免除底层硬件运维负担=="}]'::jsonb, '', 'B4-4.1.3 云计算的优势。 企业采用云计算相比传统自建机房的核心优势 优势维度 传统自建 IT 机房 云计算服务模式 资本开支（成本） 需前期一次性巨额投入购买硬件与机房基础设施（CapEx 高） 按需开通、按月按量付费，转变为日常运营支出（OpEx 显著降低） 部署与交付速度 硬件采购、上架、布线安装通常耗时数周甚至数月 控制台或 API 几分钟内秒级自动创建并交付数百台云服务器 容灾与高可用性 单点故障风险高，双活容灾成本翻倍 云厂商多可用区部署、自动故障迁移、多副本数据冗余，可用性达 99.99%+ 运维与安全保障 需专门团队维护风火水电与网络安防，易受勒索病毒攻破 云厂商集中顶尖安全专家防护，自动打补丁，免去底层硬件维护 总结 云计算核心优势一句话概括：降低成本、随需应变、极速弹性、安全可靠、免除底层硬件运维负担', '{"pdf": "理论复习.pdf", "pages": [118]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B4-4.2.1 分布式计算的概念及特点。 (node_id=197)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (197, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (197, 1, '[{"id": "b4-4-2-1-b1", "t": "p", "imp": "core", "title": "分布式计算的概念", "text": "==分布式计算（Distributed Computing）==是一种将庞大复杂的计算任务拆分成多个较小的子任务，分发给网络中多台独立的计算机（节点）协同并行处理，最终合并各子任务计算结果的技术。其核心思想是==“化整为零、分而治之（Divide and Conquer）”=="}, {"id": "b4-4-2-1-b2", "t": "table", "imp": "core", "title": "分布式计算的三大核心特点与 CAP 定理", "headers": ["特性要素", "内涵与原理说明", "对应理论/准则"], "rows": [["==高可扩展性（Scalability）==", "支持通过简单增加通用廉价服务器节点平滑扩充计算和存储能力（横向扩展 Scale Out）", "横向扩展远优于纵向提升单机硬件（Scale Up）"], ["==容错性与可靠性==", "任何单个节点宕机不会导致整个系统崩溃，系统会自动将故障节点上的任务重新调度给健康节点", "心跳检测机制与数据多副本冗余备份"], ["==CAP 定理约束==", "分布式系统不可能同时满足：==一致性（C）、可用性（A）、分区容错性（P）==，必须三选二（通常选 AP 或 CP）", "专转本必考分布式理论基础定理"]]}]'::jsonb, '', 'B4-4.2.1 分布式计算的概念及特点。 分布式计算的概念 分布式计算（Distributed Computing）是一种将庞大复杂的计算任务拆分成多个较小的子任务，分发给网络中多台独立的计算机（节点）协同并行处理，最终合并各子任务计算结果的技术。其核心思想是“化整为零、分而治之（Divide and Conquer）” 分布式计算的三大核心特点与 CAP 定理 特性要素 内涵与原理说明 对应理论/准则 高可扩展性（Scalability） 支持通过简单增加通用廉价服务器节点平滑扩充计算和存储能力（横向扩展 Scale Out） 横向扩展远优于纵向提升单机硬件（Scale Up） 容错性与可靠性 任何单个节点宕机不会导致整个系统崩溃，系统会自动将故障节点上的任务重新调度给健康节点 心跳检测机制与数据多副本冗余备份 CAP 定理约束 分布式系统不可能同时满足：一致性（C）、可用性（A）、分区容错性（P），必须三选二（通常选 AP 或 CP） 专转本必考分布式理论基础定理', '{"pdf": "理论复习.pdf", "pages": [118, 119]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B4-4.2.2 虚拟化技术的概念及特点。 (node_id=198)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (198, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (198, 1, '[{"id": "b4-4-2-2-b1", "t": "p", "imp": "core", "title": "虚拟化的概念与核心组件", "text": "==虚拟化（Virtualization）==是指将物理硬件实体资源（CPU、内存、硬盘、网卡）进行抽象、解耦和切分，模拟为一套或多套相互隔离的虚拟计算环境的技术。其核心调度管理软件被称为==虚拟机监视器（Hypervisor，或 VMM）==。"}, {"id": "b4-4-2-2-b2", "t": "table", "imp": "core", "title": "虚拟化的三大本质特点与技术路线对比", "headers": ["特点/对比项", "核心内涵", "传统虚拟机（VMware/KVM） vs 容器技术（Docker）"], "rows": [["==隔离性（Isolation）==", "同一宿主机上运行的各虚拟机相互独立，一个虚拟机崩溃或感染病毒绝不影响其他虚拟机", "虚拟机为系统级硬件模拟隔离（强隔离）；容器共享宿主操作系统内核（轻量级进程隔离）"], ["==封装性（Encapsulation）==", "虚拟机的全部状态（系统、应用、数据）被封装为一个或几个独立的文件（如 vmdk/qcow2 镜像）", "VM 镜像文件几 GB~几十 GB；Docker 镜像仅几十 MB，==秒级启动=="], ["==硬件无关性（Independence）==", "虚拟机运行在 Hypervisor 提供的抽象虚拟硬件之上，无需针对底层特定物理主板配置驱动", "支持虚拟机整机无感知在线热迁移（Live Migration）"]]}]'::jsonb, '', 'B4-4.2.2 虚拟化技术的概念及特点。 虚拟化的概念与核心组件 虚拟化（Virtualization）是指将物理硬件实体资源（CPU、内存、硬盘、网卡）进行抽象、解耦和切分，模拟为一套或多套相互隔离的虚拟计算环境的技术。其核心调度管理软件被称为虚拟机监视器（Hypervisor，或 VMM）。 虚拟化的三大本质特点与技术路线对比 特点/对比项 核心内涵 传统虚拟机（VMware/KVM） vs 容器技术（Docker） 隔离性（Isolation） 同一宿主机上运行的各虚拟机相互独立，一个虚拟机崩溃或感染病毒绝不影响其他虚拟机 虚拟机为系统级硬件模拟隔离（强隔离）；容器共享宿主操作系统内核（轻量级进程隔离） 封装性（Encapsulation） 虚拟机的全部状态（系统、应用、数据）被封装为一个或几个独立的文件（如 vmdk/qcow2 镜像） VM 镜像文件几 GB~几十 GB；Docker 镜像仅几十 MB，秒级启动 硬件无关性（Independence） 虚拟机运行在 Hypervisor 提供的抽象虚拟硬件之上，无需针对底层特定物理主板配置驱动 支持虚拟机整机无感知在线热迁移（Live Migration）', '{"pdf": "理论复习.pdf", "pages": [119]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B4-4.2.3 存储技术的概念及特点。 (node_id=199)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (199, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (199, 1, '[{"id": "b4-4-2-3-b1", "t": "table", "imp": "core", "title": "主流网络存储三大架构对比（专转本网络/存储高频考点）", "headers": ["存储技术类型", "英文简称", "连接方式与协议", "核心特点与典型应用"], "rows": [["==直接附加存储==", "==DAS（Direct-Attached）==", "通过 SCSI/SATA/SAS 电缆直接挂接在服务器总线上", "无网络协议开销，但为存储孤岛，无法跨服务器共享"], ["==网络附加存储==", "==NAS（Network-Attached）==", "通过局域网以==文件级（File-level）==协议访问（NFS、CIFS/SMB）", "专用文件服务器，网络即插即用，多客户端共享文档共享盘"], ["==存储区域网络==", "==SAN（Storage Area Network）==", "通过光纤通道（FC）或 IP 专网以==块级（Block-level）==访问（FC-SAN、IP-SAN/iSCSI）", "高性能、低延迟、面向高端数据库及企业级密集存储集群"]]}, {"id": "b4-4-2-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "NAS 与 SAN 的核心本质区别", "text": "专转本常考单选题辨析：==NAS 提供的是“文件级共享”（看到的是网络共享文件夹），而 SAN 提供的是“块级存储”（操作系统将其识别为本地裸磁盘，格式化后使用）==。"}]'::jsonb, '', 'B4-4.2.3 存储技术的概念及特点。 主流网络存储三大架构对比（专转本网络/存储高频考点） 存储技术类型 英文简称 连接方式与协议 核心特点与典型应用 直接附加存储 DAS（Direct-Attached） 通过 SCSI/SATA/SAS 电缆直接挂接在服务器总线上 无网络协议开销，但为存储孤岛，无法跨服务器共享 网络附加存储 NAS（Network-Attached） 通过局域网以文件级（File-level）协议访问（NFS、CIFS/SMB） 专用文件服务器，网络即插即用，多客户端共享文档共享盘 存储区域网络 SAN（Storage Area Network） 通过光纤通道（FC）或 IP 专网以块级（Block-level）访问（FC-SAN、IP-SAN/iSCSI） 高性能、低延迟、面向高端数据库及企业级密集存储集群 NAS 与 SAN 的核心本质区别 专转本常考单选题辨析：NAS 提供的是“文件级共享”（看到的是网络共享文件夹），而 SAN 提供的是“块级存储”（操作系统将其识别为本地裸磁盘，格式化后使用）。', '{"pdf": "理论复习.pdf", "pages": [119, 120]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B4-4.3.1 公有云、私有云、混合云。 (node_id=201)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (201, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (201, 1, '[{"id": "b4-4-3-1-b1", "t": "table", "imp": "core", "title": "云计算四大部署模式对比（按服务对象和部署位置）", "headers": ["部署模式", "拥有者与服务对象", "核心优缺点", "适用场景"], "rows": [["==公有云（Public Cloud）==", "第三方云厂商拥有，面向公众或广大众包企业租户开放", "成本最低、即开即用、弹性强；但敏感数据存放在外部", "互联网初创企业、轻量级 Web 业务、公开服务"], ["==私有云（Private Cloud）==", "单个组织/企业独占，建在企业内部内网数据中心", "数据安全可控性最高；但建设与后期维护成本高昂", "银行金融机构、大型军工国企、政府涉密部门"], ["==混合云（Hybrid Cloud）==", "融合公有云与私有云，两者间通过安全专网/VPN 互联", "兼顾私有云的安全性与公有云的弹性扩容优势，架构复杂", "核心机密数据留在私有云，促销突发峰值业务切到公有云"], ["社区云（Community Cloud）", "由若干利益共同体组织联合构建共享（如医疗行业云）", "共担建设成本，契合行业专属法规标准", "特定行业联盟、区域政务信息共享中心"]]}, {"id": "b4-4-3-1-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "混合云成为大中型企业主流", "text": "在大中型企业数字化转型中，==“核心业务数据上私有云，弹性高并发前台业务上公有云”的混合云架构==已成为最普及的技术选型策略。"}]'::jsonb, '', 'B4-4.3.1 公有云、私有云、混合云。 云计算四大部署模式对比（按服务对象和部署位置） 部署模式 拥有者与服务对象 核心优缺点 适用场景 公有云（Public Cloud） 第三方云厂商拥有，面向公众或广大众包企业租户开放 成本最低、即开即用、弹性强；但敏感数据存放在外部 互联网初创企业、轻量级 Web 业务、公开服务 私有云（Private Cloud） 单个组织/企业独占，建在企业内部内网数据中心 数据安全可控性最高；但建设与后期维护成本高昂 银行金融机构、大型军工国企、政府涉密部门 混合云（Hybrid Cloud） 融合公有云与私有云，两者间通过安全专网/VPN 互联 兼顾私有云的安全性与公有云的弹性扩容优势，架构复杂 核心机密数据留在私有云，促销突发峰值业务切到公有云 社区云（Community Cloud） 由若干利益共同体组织联合构建共享（如医疗行业云） 共担建设成本，契合行业专属法规标准 特定行业联盟、区域政务信息共享中心 混合云成为大中型企业主流 在大中型企业数字化转型中，“核心业务数据上私有云，弹性高并发前台业务上公有云”的混合云架构已成为最普及的技术选型策略。', '{"pdf": "理论复习.pdf", "pages": [120]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B4-4.3.2 IaaS、PaaS、SaaS。 (node_id=202)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (202, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (202, 1, '[{"id": "b4-4-3-2-b1", "t": "table", "imp": "core", "title": "云计算三大经典服务层次（专转本每考必出大题）", "headers": ["服务层次", "英文全称", "服务交付内容", "用户负责维护的部分", "典型代表实例"], "rows": [["==IaaS（基础设施即服务）==", "Infrastructure as a Service", "提供计算、存储、网络等最基础的底层硬件资源", "用户需自行安装操作系统、中间件、运行环境及上层应用程序", "阿里云 ECS、AWS EC2、虚拟机、云硬盘"], ["==PaaS（平台即服务）==", "Platform as a Service", "提供应用软件开发、测试和运行的操作系统与中间件平台环境", "用户仅负责编写和部署自己的业务代码与数据，底层由平台托管", "Google App Engine、各类云原生容器云平台、函数计算 Serverless"], ["==SaaS（软件即服务）==", "Software as a Service", "直接向最终用户交付开箱即用的完整功能软件应用", "用户无需负责任何底层维护，开通账号直接通过浏览器/App 使用", "微软 Office 365、腾讯会议、企业微信、各类 Web 邮箱"]]}, {"id": "b4-4-3-2-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "披萨做饭比喻法牢记服务分层", "text": "==IaaS 相当于租厨房设备（炉灶煤气给你，自己买菜做饭）；PaaS 相当于点半成品外卖配送（厨房调料搞好，自己炒熟）；SaaS 相当于去餐馆直接吃现成披萨（啥都不用管，拿筷子直接享用）==。"}]'::jsonb, '', 'B4-4.3.2 IaaS、PaaS、SaaS。 云计算三大经典服务层次（专转本每考必出大题） 服务层次 英文全称 服务交付内容 用户负责维护的部分 典型代表实例 IaaS（基础设施即服务） Infrastructure as a Service 提供计算、存储、网络等最基础的底层硬件资源 用户需自行安装操作系统、中间件、运行环境及上层应用程序 阿里云 ECS、AWS EC2、虚拟机、云硬盘 PaaS（平台即服务） Platform as a Service 提供应用软件开发、测试和运行的操作系统与中间件平台环境 用户仅负责编写和部署自己的业务代码与数据，底层由平台托管 Google App Engine、各类云原生容器云平台、函数计算 Serverless SaaS（软件即服务） Software as a Service 直接向最终用户交付开箱即用的完整功能软件应用 用户无需负责任何底层维护，开通账号直接通过浏览器/App 使用 微软 Office 365、腾讯会议、企业微信、各类 Web 邮箱 披萨做饭比喻法牢记服务分层 IaaS 相当于租厨房设备（炉灶煤气给你，自己买菜做饭）；PaaS 相当于点半成品外卖配送（厨房调料搞好，自己炒熟）；SaaS 相当于去餐馆直接吃现成披萨（啥都不用管，拿筷子直接享用）。', '{"pdf": "理论复习.pdf", "pages": [120]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

