INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (203, 1, '[{"id": "b4-4-3-3-b1", "t": "table", "imp": "core", "title": "国内外主流云服务提供商与代表产品", "headers": ["厂商分类", "云服务商名称", "底层自研核心技术/系统", "主要产品与定位优势"], "rows": [["国内头部云厂商", "==阿里云（Alibaba Cloud）==", "==飞天（Apsara）分布式云操作系统==", "国内市场份额第一，ECS、RDS、OSS、大数据 MaxCompute"], ["国内头部云厂商", "==华为云（Huawei Cloud）==", "擎天架构、自研鲲鹏/昇腾生态", "政企与工业制造云首选，软硬件深度一体化协同"], ["国内头部云厂商", "==腾讯云（Tencent Cloud）==", "自研星海服务器、沧海存储", "游戏云、音视频直播、文娱社交与小程序开发生态优势"], ["国际头部云厂商", "==亚马逊 AWS==", "Nitro 自研系统、DynamoDB", "全球云计算开创者与全球市场份额第一，产品矩阵最完备"], ["国际头部云厂商", "微软 Azure", "Azure 云平台、与 Windows 生态融合", "企业级混合云、Office 365 与 OpenAI 深度整合生态"], ["国际头部云厂商", "Google Cloud", "Borg 集群调度、Kubernetes 开源鼻祖", "大数据处理、AI/机器学习与云原生技术创新高地"]]}, {"id": "b4-4-3-3-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "国内自研云操作系统考点", "text": "专转本选择题常考点：==阿里云自主研发的超大规模分布式云计算操作系统名为“飞天”（Apsara）==。"}]'::jsonb, '', 'B4-4.3.3 AWS、Google、阿里云、华为云、腾讯云等国内外主流云服务提供平台。 国内外主流云服务提供商与代表产品 厂商分类 云服务商名称 底层自研核心技术/系统 主要产品与定位优势 国内头部云厂商 阿里云（Alibaba Cloud） 飞天（Apsara）分布式云操作系统 国内市场份额第一，ECS、RDS、OSS、大数据 MaxCompute 国内头部云厂商 华为云（Huawei Cloud） 擎天架构、自研鲲鹏/昇腾生态 政企与工业制造云首选，软硬件深度一体化协同 国内头部云厂商 腾讯云（Tencent Cloud） 自研星海服务器、沧海存储 游戏云、音视频直播、文娱社交与小程序开发生态优势 国际头部云厂商 亚马逊 AWS Nitro 自研系统、DynamoDB 全球云计算开创者与全球市场份额第一，产品矩阵最完备 国际头部云厂商 微软 Azure Azure 云平台、与 Windows 生态融合 企业级混合云、Office 365 与 OpenAI 深度整合生态 国际头部云厂商 Google Cloud Borg 集群调度、Kubernetes 开源鼻祖 大数据处理、AI/机器学习与云原生技术创新高地 国内自研云操作系统考点 专转本选择题常考点：阿里云自主研发的超大规模分布式云计算操作系统名为“飞天”（Apsara）。', '{"pdf": "理论复习.pdf", "pages": [120]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B5-5.1.1 大数据产生背景与基本概念、主要特性。 (node_id=205)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (205, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (205, 1, '[{"id": "b5-5-1-1-b1", "t": "p", "imp": "core", "title": "大数据的基本概念与产生背景", "text": "==大数据（Big Data）==是指无法在一定时间范围内用常规软件工具进行捕捉、管理和处理的数据集合，是需要新处理模式才能具有更强的决策力、洞察发现力和流程优化能力的海量、高增长率和多样化的信息资产。其产生的核心驱动力为**互联网、移动互联网、物联网的普及以及各类传感器数据的爆发式增长**。"}, {"id": "b5-5-1-1-b2", "t": "table", "imp": "core", "title": "大数据的核心特征（4V 特征，业界亦扩充为 5V）", "headers": ["特征维度 (4V)", "英文原词", "核心内涵解释", "考点要记"], "rows": [["==海量性（大量）==", "Volume", "数据体量巨大，跃升到 ==TB、PB、EB 乃至 ZB 级别==", "数据量从传统 GB 级跃升"], ["==多样性（多样）==", "Variety", "数据类型繁多，包括==结构化、半结构化（XML/JSON）与非结构化（音频/视频/图片）==", "非结构化数据占比超过 80%"], ["==高速性（快速）==", "Velocity", "数据生成速度快、处理速度要求高，要求==实时分析与流式处理==", "一秒定律（1 second rule）"], ["==低价值密度（价值）==", "Value", "价值密度极低，但==商业价值极高==，需要海量提炼", "沙里淘金，关键在于提炼关联分析"], ["真实性（真实，第5V）", "Veracity", "数据的质量、准确性与可信赖度", "数据清洗与质量控制的前提"]]}, {"id": "b5-5-1-1-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "大数据核心思维陷阱", "text": "专转本常考辨析：大数据时代强调==关注“相关关系”而非必须探究“因果关系”==；强调**采用全样数据而非传统抽样数据**；容忍数据的**混杂性而非追求绝对精确性**。"}]'::jsonb, '', 'B5-5.1.1 大数据产生背景与基本概念、主要特性。 大数据的基本概念与产生背景 大数据（Big Data）是指无法在一定时间范围内用常规软件工具进行捕捉、管理和处理的数据集合，是需要新处理模式才能具有更强的决策力、洞察发现力和流程优化能力的海量、高增长率和多样化的信息资产。其产生的核心驱动力为互联网、移动互联网、物联网的普及以及各类传感器数据的爆发式增长。 大数据的核心特征（4V 特征，业界亦扩充为 5V） 特征维度 (4V) 英文原词 核心内涵解释 考点要记 海量性（大量） Volume 数据体量巨大，跃升到 TB、PB、EB 乃至 ZB 级别 数据量从传统 GB 级跃升 多样性（多样） Variety 数据类型繁多，包括结构化、半结构化（XML/JSON）与非结构化（音频/视频/图片） 非结构化数据占比超过 80% 高速性（快速） Velocity 数据生成速度快、处理速度要求高，要求实时分析与流式处理 一秒定律（1 second rule） 低价值密度（价值） Value 价值密度极低，但商业价值极高，需要海量提炼 沙里淘金，关键在于提炼关联分析 真实性（真实，第5V） Veracity 数据的质量、准确性与可信赖度 数据清洗与质量控制的前提 大数据核心思维陷阱 专转本常考辨析：大数据时代强调关注“相关关系”而非必须探究“因果关系”；强调采用全样数据而非传统抽样数据；容忍数据的混杂性而非追求绝对精确性。', '{"pdf": "理论复习.pdf", "pages": [121, 122]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B5-5.1.2 大数据的发展历程。 (node_id=206)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (206, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (206, 1, '[{"id": "b5-5-1-2-b1", "t": "table", "imp": "core", "title": "大数据技术发展的三个主要阶段", "headers": ["发展阶段", "时间区间", "标志性技术/代表", "阶段核心特征"], "rows": [["==萌芽期（技术准备）==", "1980s - 2000 年", "数据仓库、商务智能、数据挖掘", "关系型数据库主导，开始面临海量存储瓶颈"], ["==成熟期（开源爆发）==", "2000 年 - 2010 年", "==Google 三驾马车（GFS/MapReduce/BigTable）==、**Apache Hadoop/HDFS**", "分布式计算与存储框架确立，NoSQL 兴起"], ["==应用期（生态繁荣与智能融合）==", "2010 年至今", "Spark 内存计算、Flink 流计算、深度学习结合", "实时计算、数据湖、AI 与大数据深度融合"]]}, {"id": "b5-5-1-2-b2", "t": "list", "imp": "important", "title": "我国大数据国家战略关键节点", "items": ["2015 年国务院印发《促进大数据发展行动纲要》，大数据正式上升为==国家战略==", "“十三五”与“十四五”规划均将大数据作为推动经济高质量发展的战略支撑", "建立国家级大数据综合试验区（如贵州等试验区），推进数字中国与数字政府建设"]}]'::jsonb, '', 'B5-5.1.2 大数据的发展历程。 大数据技术发展的三个主要阶段 发展阶段 时间区间 标志性技术/代表 阶段核心特征 萌芽期（技术准备） 1980s - 2000 年 数据仓库、商务智能、数据挖掘 关系型数据库主导，开始面临海量存储瓶颈 成熟期（开源爆发） 2000 年 - 2010 年 Google 三驾马车（GFS/MapReduce/BigTable）、Apache Hadoop/HDFS 分布式计算与存储框架确立，NoSQL 兴起 应用期（生态繁荣与智能融合） 2010 年至今 Spark 内存计算、Flink 流计算、深度学习结合 实时计算、数据湖、AI 与大数据深度融合 我国大数据国家战略关键节点 2015 年国务院印发《促进大数据发展行动纲要》，大数据正式上升为国家战略 “十三五”与“十四五”规划均将大数据作为推动经济高质量发展的战略支撑 建立国家级大数据综合试验区（如贵州等试验区），推进数字中国与数字政府建设', '{"pdf": "理论复习.pdf", "pages": [121, 122]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B5-5.1.3 大数据与云计算、人工智能技术的关系。 (node_id=207)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (207, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (207, 1, '[{"id": "b5-5-1-3-b1", "t": "table", "imp": "core", "title": "大数据、云计算与人工智能的“三位一体”协同关系", "headers": ["技术要素", "在协同体系中的角色", "比喻说明", "相互依存关系"], "rows": [["==大数据（Data）==", "==原料与资产==", "石油 / 燃料", "为 AI 算法模型提供海量高质量训练数据与验证场景"], ["==云计算（Computing）==", "==计算基础设施==", "引擎 / 电网", "为大数据处理与 AI 训练提供弹性的分布式算力与海量存储"], ["==人工智能（AI）==", "==深度价值提炼引擎==", "大脑 / 驾驶员", "利用深度学习与机器学习让大数据从单纯统计提升到智能决策"]]}, {"id": "b5-5-1-3-b2", "t": "callout", "imp": "core", "kind": "tip", "title": "记忆口诀", "text": "==“云计算是底座（算力），大数据是资源（燃料），人工智能是导向与应用（大脑）”==。三者相互促进、密不可分。"}]'::jsonb, '', 'B5-5.1.3 大数据与云计算、人工智能技术的关系。 大数据、云计算与人工智能的“三位一体”协同关系 技术要素 在协同体系中的角色 比喻说明 相互依存关系 大数据（Data） 原料与资产 石油 / 燃料 为 AI 算法模型提供海量高质量训练数据与验证场景 云计算（Computing） 计算基础设施 引擎 / 电网 为大数据处理与 AI 训练提供弹性的分布式算力与海量存储 人工智能（AI） 深度价值提炼引擎 大脑 / 驾驶员 利用深度学习与机器学习让大数据从单纯统计提升到智能决策 记忆口诀 “云计算是底座（算力），大数据是资源（燃料），人工智能是导向与应用（大脑）”。三者相互促进、密不可分。', '{"pdf": "理论复习.pdf", "pages": [122, 123]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B5-5.2.1 Hadoop、MapReduce、NoSQL 等技术基本功能。 (node_id=209)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (209, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (209, 1, '[{"id": "b5-5-2-1-b1", "t": "table", "imp": "core", "title": "Hadoop 核心组件与基本功能", "headers": ["Hadoop 核心组件", "全称/功能定位", "工作机制与关键概念"], "rows": [["==HDFS==", "分布式文件系统（存储层）", "采用**主从架构（NameNode 管理元数据，DataNode 存储实际数据块 Block）**，默认按 3 副本冗余容错"], ["==MapReduce==", "分布式并行计算框架（计算层）", "核心分为两阶段：==Map（映射/分发）==将任务切分处理为键值对 `<k1, v1> -> <k2, v2>`；==Reduce（规约/汇总）==对相同 key 聚合并输出结果"], ["==YARN==", "集群资源调度与资源管理器", "统一负责集群中的 CPU、内存等资源分配调度（ResourceManager 与 NodeManager）"]]}, {"id": "b5-5-2-1-b2", "t": "table", "imp": "core", "title": "NoSQL（非关系型数据库）四大类型对比", "headers": ["NoSQL 数据库分类", "代表产品", "数据模型特点", "典型适用场景"], "rows": [["==键值（Key-Value）数据库==", "==Redis==, Memcached", "基于哈希表以 key-value 快速读写", "内容缓存、会话管理、高频读写计数器"], ["==文档型（Document）数据库==", "==MongoDB==, CouchDB", "以 JSON / BSON 等半结构化文档存储", "Web 内容管理、用户画像、日志存储"], ["==列族（Column-family）数据库==", "==HBase==, Cassandra", "按列族分布式存储，支持海量稀疏表", "海量日志存储、时序数据、历史轨迹"], ["==图（Graph）数据库==", "==Neo4j==", "图结构存储（节点、关系、属性）", "社交网络关系、知识图谱、风控反欺诈"]]}, {"id": "b5-5-2-1-b3", "t": "callout", "imp": "core", "kind": "trap", "title": "Hadoop 组件常考细节", "text": "==NameNode 仅存储文件系统元数据（文件名、目录树、块映射位置），不直接存储实际数据块==；实际数据分散存储在各个 DataNode 上。"}]'::jsonb, '', 'B5-5.2.1 Hadoop、MapReduce、NoSQL 等技术基本功能。 Hadoop 核心组件与基本功能 Hadoop 核心组件 全称/功能定位 工作机制与关键概念 HDFS 分布式文件系统（存储层） 采用主从架构（NameNode 管理元数据，DataNode 存储实际数据块 Block），默认按 3 副本冗余容错 MapReduce 分布式并行计算框架（计算层） 核心分为两阶段：Map（映射/分发）将任务切分处理为键值对 <k1, v1> -> <k2, v2>；Reduce（规约/汇总）对相同 key 聚合并输出结果 YARN 集群资源调度与资源管理器 统一负责集群中的 CPU、内存等资源分配调度（ResourceManager 与 NodeManager） NoSQL（非关系型数据库）四大类型对比 NoSQL 数据库分类 代表产品 数据模型特点 典型适用场景 键值（Key-Value）数据库 Redis, Memcached 基于哈希表以 key-value 快速读写 内容缓存、会话管理、高频读写计数器 文档型（Document）数据库 MongoDB, CouchDB 以 JSON / BSON 等半结构化文档存储 Web 内容管理、用户画像、日志存储 列族（Column-family）数据库 HBase, Cassandra 按列族分布式存储，支持海量稀疏表 海量日志存储、时序数据、历史轨迹 图（Graph）数据库 Neo4j 图结构存储（节点、关系、属性） 社交网络关系、知识图谱、风控反欺诈 Hadoop 组件常考细节 NameNode 仅存储文件系统元数据（文件名、目录树、块映射位置），不直接存储实际数据块；实际数据分散存储在各个 DataNode 上。', '{"pdf": "理论复习.pdf", "pages": [123, 124, 125]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B5-5.2.2 爬虫、清洗等技术基本概念及常用工具认知。 (node_id=210)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (210, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (210, 1, '[{"id": "b5-5-2-2-b1", "t": "list", "imp": "core", "title": "网络爬虫与数据采集核心概念", "items": ["==网络爬虫（Web Crawler/Spider）==：自动从互联网抓取超文本网页的程序，遵循 `robots.txt` 协议", "常用爬虫框架与工具：Python 中的 ==Requests==、==Scrapy==、BeautifulSoup、Selenium 以及开源分布式采集工具", "传感器与日志采集：如 Flume、Logstash、Kafka 负责从服务器日志及物联网设备进行实时数据管道流转"]}, {"id": "b5-5-2-2-b2", "t": "table", "imp": "core", "title": "数据清洗（Data Cleaning）的核心任务与方法", "headers": ["清洗对象", "主要缺陷现象", "标准处理手段与算法"], "rows": [["==缺失值处理==", "字段为空（NULL/NaN）", "==删除记录、人工填充、统计值填充（均值/中位数/众数）或回归预测填充=="], ["==异常值检测==", "取值超出合理范围（如年龄 300 岁）", "==3σ 原则（正态分布）、箱线图（IQR 四分位距）、聚类剔除=="], ["==重复值清洗==", "多条记录完全相同或语义重复", "按主键或核心特征联合去重，保留最新或最全版本"], ["数据规范化", "格式不一（如日期格式混杂、单位不同）", "统一数据单位与时间戳格式，字段值标准化（如最小-最大归一化、Z-score）"]]}]'::jsonb, '', 'B5-5.2.2 爬虫、清洗等技术基本概念及常用工具认知。 网络爬虫与数据采集核心概念 网络爬虫（Web Crawler/Spider）：自动从互联网抓取超文本网页的程序，遵循 robots.txt 协议 常用爬虫框架与工具：Python 中的 Requests、Scrapy、BeautifulSoup、Selenium 以及开源分布式采集工具 传感器与日志采集：如 Flume、Logstash、Kafka 负责从服务器日志及物联网设备进行实时数据管道流转 数据清洗（Data Cleaning）的核心任务与方法 清洗对象 主要缺陷现象 标准处理手段与算法 缺失值处理 字段为空（NULL/NaN） 删除记录、人工填充、统计值填充（均值/中位数/众数）或回归预测填充 异常值检测 取值超出合理范围（如年龄 300 岁） 3σ 原则（正态分布）、箱线图（IQR 四分位距）、聚类剔除 重复值清洗 多条记录完全相同或语义重复 按主键或核心特征联合去重，保留最新或最全版本 数据规范化 格式不一（如日期格式混杂、单位不同） 统一数据单位与时间戳格式，字段值标准化（如最小-最大归一化、Z-score）', '{"pdf": "理论复习.pdf", "pages": [124, 125]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B5-5.2.3 大数据分析、挖掘、可视化技术基本概念。 (node_id=211)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (211, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (211, 1, '[{"id": "b5-5-2-3-b1", "t": "list", "imp": "core", "title": "数据分析与挖掘核心流程与常用算法", "items": ["==数据挖掘（Data Mining）==：从大量、不完全、有噪声、模糊、随机的数据中，提取隐含在其中、人们事先不知道但又是潜在有用的信息和知识的过程", "三大主流挖掘任务：==分类（决策树/朴素贝叶斯/SVM）==、==聚类（K-Means/层次聚类）==、==关联规则分析（Apriori/FP-Growth，如“啤酒与尿布”经典案例）==", "预测性建模：线性回归、逻辑回归、时间序列分析（ARIMA）等"]}, {"id": "b5-5-2-3-b2", "t": "table", "imp": "important", "title": "主流数据可视化技术与工具", "headers": ["分类", "代表工具与框架", "特点与应用"], "rows": [["==开源 Web 前端图表库==", "==ECharts（百度开源）==, D3.js, Chart.js", "基于 Web 技术，支持丰富的动态交互与大屏展示"], ["专业 BI 商业报表软件", "==Tableau==, Power BI, FineBI (帆软)", "拖拽式生成商业智能仪表板，多维联动分析"], ["Python/R 科学绘图库", "Matplotlib, Seaborn, ggplot2", "数据科学与算法建模分析阶段的快速绘图与统计展现"]]}]'::jsonb, '', 'B5-5.2.3 大数据分析、挖掘、可视化技术基本概念。 数据分析与挖掘核心流程与常用算法 数据挖掘（Data Mining）：从大量、不完全、有噪声、模糊、随机的数据中，提取隐含在其中、人们事先不知道但又是潜在有用的信息和知识的过程 三大主流挖掘任务：分类（决策树/朴素贝叶斯/SVM）、聚类（K-Means/层次聚类）、关联规则分析（Apriori/FP-Growth，如“啤酒与尿布”经典案例） 预测性建模：线性回归、逻辑回归、时间序列分析（ARIMA）等 主流数据可视化技术与工具 分类 代表工具与框架 特点与应用 开源 Web 前端图表库 ECharts（百度开源）, D3.js, Chart.js 基于 Web 技术，支持丰富的动态交互与大屏展示 专业 BI 商业报表软件 Tableau, Power BI, FineBI (帆软) 拖拽式生成商业智能仪表板，多维联动分析 Python/R 科学绘图库 Matplotlib, Seaborn, ggplot2 数据科学与算法建模分析阶段的快速绘图与统计展现', '{"pdf": "理论复习.pdf", "pages": [125, 126]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B5-5.3.1 大数据在农业、工业互联网、服务业等领域的典型应用。 (node_id=213)
