INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (213, 1, '[{"id": "b5-5-3-1-b1", "t": "table", "imp": "core", "title": "大数据重点行业典型落地应用", "headers": ["行业领域", "典型大数据应用场景", "实现价值"], "rows": [["==智慧农业==", "精准测土配方、遥感估产、病虫害预警、农产品全流程溯源", "节约水肥成本、提高产量与食品安全可追溯"], ["==工业互联网==", "设备预测性维护（PHM）、生产质量缺陷溯源、柔性排产优化", "减少意外停机时间、提升良品率与能耗管理"], ["==金融服务业==", "信用卡反欺诈、大数据征信风控、智能投顾、精准营销推荐", "秒级放贷风控审批、降低不良资产率"], ["==智慧交通/政务==", "城市大脑交通拥堵信号灯动态配时、一网通办数据共享", "提高城市通行效率、实现便民政务服务"]]}, {"id": "b5-5-3-1-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "典型应用考查要点", "text": "专转本考试常考行业场景匹配题，例如：通过分析海量机器传感器时序数据提前预警轴承磨损故障，属于==工业互联网预测性维护=="}]'::jsonb, '', 'B5-5.3.1 大数据在农业、工业互联网、服务业等领域的典型应用。 大数据重点行业典型落地应用 行业领域 典型大数据应用场景 实现价值 智慧农业 精准测土配方、遥感估产、病虫害预警、农产品全流程溯源 节约水肥成本、提高产量与食品安全可追溯 工业互联网 设备预测性维护（PHM）、生产质量缺陷溯源、柔性排产优化 减少意外停机时间、提升良品率与能耗管理 金融服务业 信用卡反欺诈、大数据征信风控、智能投顾、精准营销推荐 秒级放贷风控审批、降低不良资产率 智慧交通/政务 城市大脑交通拥堵信号灯动态配时、一网通办数据共享 提高城市通行效率、实现便民政务服务 典型应用考查要点 专转本考试常考行业场景匹配题，例如：通过分析海量机器传感器时序数据提前预警轴承磨损故障，属于工业互联网预测性维护', '{"pdf": "理论复习.pdf", "pages": [126, 127]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B5-5.3.2 大数据未来发展趋势。 (node_id=214)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (214, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (214, 1, '[{"id": "b5-5-3-2-b1", "t": "list", "imp": "core", "title": "大数据前沿技术演进方向", "items": ["==湖仓一体（Lakehouse）==：融合数据湖的低成本多格式存储与数据仓库的事务支持（ACID）及高性能分析", "==隐私计算与联邦学习==：在“数据可用不可见、数据不动计算动”前提下跨机构安全联合建模", "==流批一体（Stream-Batch Convergence）==：统一批处理与实时流计算（以 Apache Flink 为典型代表）", "数据资产化与数据安全合规：《数据安全法》与《个人信息保护法》护航下的合规数据要素流通市场"]}, {"id": "b5-5-3-2-b2", "t": "callout", "imp": "core", "kind": "warn", "title": "数据安全与隐私保护红线", "text": "大数据未来发展中，==数据要素确权、合规交易与隐私保护==是最核心的法律与政策底线，严禁未授权采集和滥用个人生物识别及行为隐私数据。"}]'::jsonb, '', 'B5-5.3.2 大数据未来发展趋势。 大数据前沿技术演进方向 湖仓一体（Lakehouse）：融合数据湖的低成本多格式存储与数据仓库的事务支持（ACID）及高性能分析 隐私计算与联邦学习：在“数据可用不可见、数据不动计算动”前提下跨机构安全联合建模 流批一体（Stream-Batch Convergence）：统一批处理与实时流计算（以 Apache Flink 为典型代表） 数据资产化与数据安全合规：《数据安全法》与《个人信息保护法》护航下的合规数据要素流通市场 数据安全与隐私保护红线 大数据未来发展中，数据要素确权、合规交易与隐私保护是最核心的法律与政策底线，严禁未授权采集和滥用个人生物识别及行为隐私数据。', '{"pdf": "理论复习.pdf", "pages": [127]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B6-6.1.1 人工智能的基本概念。 (node_id=216)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (216, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (216, 1, '[{"id": "b6-6-1-1-b1", "t": "p", "imp": "core", "title": "人工智能的定义与本质", "text": "==人工智能（Artificial Intelligence，简称 AI）==是研究、开发用于模拟、延伸和扩展人的智能的理论、方法、技术及应用系统的一门新的技术科学。由==约翰·麦卡锡（John McCarthy）==等人在 1956 年达特茅斯会议上首次提出。其研究目标是让机器能够胜任一些通常需要人类智能才能完成的复杂工作。"}, {"id": "b6-6-1-1-b2", "t": "table", "imp": "core", "title": "弱人工智能 vs 强人工智能 vs 超人工智能", "headers": ["类别", "英文", "定义及特征", "典型代表/现状"], "rows": [["==弱人工智能（专用 AI）==", "ANI (Narrow AI)", "专注于解决单一特定领域问题，无自主意识", "AlphaGo、人脸识别、语音助手（目前所处阶段）"], ["==强人工智能（通用 AI）==", "AGI (General AI)", "具备如同人类一样的全面思维、推理与自我学习适应能力", "目前处于前沿理论与研发探索阶段"], ["超人工智能", "ASI (Super AI)", "在各领域（科学创造、智力水平）均超越人类最高大脑水平", "未来设想阶段"]]}]'::jsonb, '', 'B6-6.1.1 人工智能的基本概念。 人工智能的定义与本质 人工智能（Artificial Intelligence，简称 AI）是研究、开发用于模拟、延伸和扩展人的智能的理论、方法、技术及应用系统的一门新的技术科学。由约翰·麦卡锡（John McCarthy）等人在 1956 年达特茅斯会议上首次提出。其研究目标是让机器能够胜任一些通常需要人类智能才能完成的复杂工作。 弱人工智能 vs 强人工智能 vs 超人工智能 类别 英文 定义及特征 典型代表/现状 弱人工智能（专用 AI） ANI (Narrow AI) 专注于解决单一特定领域问题，无自主意识 AlphaGo、人脸识别、语音助手（目前所处阶段） 强人工智能（通用 AI） AGI (General AI) 具备如同人类一样的全面思维、推理与自我学习适应能力 目前处于前沿理论与研发探索阶段 超人工智能 ASI (Super AI) 在各领域（科学创造、智力水平）均超越人类最高大脑水平 未来设想阶段', '{"pdf": "理论复习.pdf", "pages": [128]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B6-6.1.2 人工智能的基本原理。 (node_id=217)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (217, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (217, 1, '[{"id": "b6-6-1-2-b1", "t": "table", "imp": "core", "title": "人工智能的三大学派（核心哲学与基础）", "headers": ["学派名称", "别称/代表思想", "核心技术与方法", "代表学者与典型成果"], "rows": [["==符号主义（逻辑学派）==", "Symbolism / 逻辑主义", "基于逻辑推理与知识库表达，认为智能源于物理符号系统的操作", "专家系统、知识图谱、Prolog 语言"], ["==连接主义（仿生学派）==", "Connectionism / 仿生主义", "仿照人脑神经网络结构，通过神经元互联与权值调整学习", "==人工神经网络（ANN）、深度学习=="], ["==行为主义（控制学派）==", "Actionism / 进化主义", "强调智能取决于感知与行动，通过环境交互进化", "控制论、强化学习、自主移动机器人"]]}, {"id": "b6-6-1-2-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "图灵测试（Turing Test）考点", "text": "==阿兰·图灵（Alan Turing）==在 1950 年提出图灵测试：若隔室测试者在五分钟内提问，无法以超过 30% 的概率区分回答者是机器还是真人，则认为机器具有人类智能。图灵被誉为==计算机科学之父和人工智能之父=="}]'::jsonb, '', 'B6-6.1.2 人工智能的基本原理。 人工智能的三大学派（核心哲学与基础） 学派名称 别称/代表思想 核心技术与方法 代表学者与典型成果 符号主义（逻辑学派） Symbolism / 逻辑主义 基于逻辑推理与知识库表达，认为智能源于物理符号系统的操作 专家系统、知识图谱、Prolog 语言 连接主义（仿生学派） Connectionism / 仿生主义 仿照人脑神经网络结构，通过神经元互联与权值调整学习 人工神经网络（ANN）、深度学习 行为主义（控制学派） Actionism / 进化主义 强调智能取决于感知与行动，通过环境交互进化 控制论、强化学习、自主移动机器人 图灵测试（Turing Test）考点 阿兰·图灵（Alan Turing）在 1950 年提出图灵测试：若隔室测试者在五分钟内提问，无法以超过 30% 的概率区分回答者是机器还是真人，则认为机器具有人类智能。图灵被誉为计算机科学之父和人工智能之父', '{"pdf": "理论复习.pdf", "pages": [128, 129]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B6-6.1.3 人工智能发展历程。 (node_id=218)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (218, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (218, 1, '[{"id": "b6-6-1-3-b1", "t": "table", "imp": "core", "title": "人工智能“三起两落”的发展演进", "headers": ["发展时期", "起伏阶段", "驱动技术与关键标志", "低谷原因/转折点"], "rows": [["1956 - 1970s 初", "第一次黄金期", "==1956 达特茅斯会议诞生==；定理证明程序、机器翻译起步", "算法局限，无法解决组合爆炸问题，遭遇第一次低谷"], ["1970s 末 - 1980s", "第二次繁荣期", "==专家系统（Expert System）==商用爆发、知识库兴起", "知识获取困难、推理脆弱、维护成本高昂，遭遇第二次低谷"], ["2006 年至今", "第三次爆发期（深度学习时代）", "==Hinton 提出深度学习==、**算力（GPU）爆发、海量大数据支持**", "AlphaGo 击败围棋世界冠军、大语言模型（LLM）突破"]]}, {"id": "b6-6-1-3-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "达特茅斯会议与历史考点", "text": "==1956 年达特茅斯会议标志着人工智能学科的正式诞生==；1997 年 IBM “深蓝”计算机战胜国际象棋世界冠军卡斯帕罗夫，2016 年 DeepMind 的 AlphaGo 战胜围棋世界冠军李世石。"}]'::jsonb, '', 'B6-6.1.3 人工智能发展历程。 人工智能“三起两落”的发展演进 发展时期 起伏阶段 驱动技术与关键标志 低谷原因/转折点 1956 - 1970s 初 第一次黄金期 1956 达特茅斯会议诞生；定理证明程序、机器翻译起步 算法局限，无法解决组合爆炸问题，遭遇第一次低谷 1970s 末 - 1980s 第二次繁荣期 专家系统（Expert System）商用爆发、知识库兴起 知识获取困难、推理脆弱、维护成本高昂，遭遇第二次低谷 2006 年至今 第三次爆发期（深度学习时代） Hinton 提出深度学习、算力（GPU）爆发、海量大数据支持 AlphaGo 击败围棋世界冠军、大语言模型（LLM）突破 达特茅斯会议与历史考点 1956 年达特茅斯会议标志着人工智能学科的正式诞生；1997 年 IBM “深蓝”计算机战胜国际象棋世界冠军卡斯帕罗夫，2016 年 DeepMind 的 AlphaGo 战胜围棋世界冠军李世石。', '{"pdf": "理论复习.pdf", "pages": [128, 129]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B6-6.2.1 深度学习的概念，常用算法。 (node_id=220)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (220, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (220, 1, '[{"id": "b6-6-2-1-b1", "t": "p", "imp": "core", "title": "深度学习（Deep Learning）概念", "text": "==深度学习==是机器学习的分支，通过构建含多个隐层的**深度人工神经网络**模型，逐层自动抽取数据的低级特征并组合成高抽象度语义特征。传统机器学习需繁琐人工设计特征工程，深度学习实现了==端到端（End-to-End）自动特征学习=="}, {"id": "b6-6-2-1-b2", "t": "table", "imp": "core", "title": "深度学习主流经典网络架构与算法", "headers": ["网络类型", "英文简称", "结构特征与优势", "主要应用领域"], "rows": [["==卷积神经网络==", "==CNN==", "包含**卷积层（特征提取）、池化层（降维）、全连接层**；参数共享与局部连接", "==图像识别、目标检测、医学影像分析=="], ["==循环神经网络==", "==RNN / LSTM / GRU==", "神经元存在内部环路反馈，具有“记忆”能力，专门处理序列数据", "==语音识别、机器翻译、文本序列处理=="], ["==生成对抗网络==", "==GAN==", "由==生成器（Generator）和判别器（Discriminator）==相互博弈对抗学习", "图像生成、超分辨率修复、AI 换脸"], ["Transformer 模型", "Transformer", "基于自注意力机制（Self-Attention），高度并行处理长文本", "大语言模型（GPT、BERT）的基础架构"]]}]'::jsonb, '', 'B6-6.2.1 深度学习的概念，常用算法。 深度学习（Deep Learning）概念 深度学习是机器学习的分支，通过构建含多个隐层的深度人工神经网络模型，逐层自动抽取数据的低级特征并组合成高抽象度语义特征。传统机器学习需繁琐人工设计特征工程，深度学习实现了端到端（End-to-End）自动特征学习 深度学习主流经典网络架构与算法 网络类型 英文简称 结构特征与优势 主要应用领域 卷积神经网络 CNN 包含卷积层（特征提取）、池化层（降维）、全连接层；参数共享与局部连接 图像识别、目标检测、医学影像分析 循环神经网络 RNN / LSTM / GRU 神经元存在内部环路反馈，具有“记忆”能力，专门处理序列数据 语音识别、机器翻译、文本序列处理 生成对抗网络 GAN 由生成器（Generator）和判别器（Discriminator）相互博弈对抗学习 图像生成、超分辨率修复、AI 换脸 Transformer 模型 Transformer 基于自注意力机制（Self-Attention），高度并行处理长文本 大语言模型（GPT、BERT）的基础架构', '{"pdf": "理论复习.pdf", "pages": [129, 130]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B6-6.2.2 自然语言处理的概念。 (node_id=221)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (221, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (221, 1, '[{"id": "b6-6-2-2-b1", "t": "list", "imp": "core", "title": "自然语言处理（NLP）概念与任务", "items": ["==自然语言处理（Natural Language Processing，NLP）==：研究计算机如何理解、解析、生成人类自然语言的学科，被誉为==“人工智能皇冠上的明珠”==", "核心分为两大分支：==自然语言理解（NLU）==（如句法分析、意图识别）与==自然语言生成（NLG）==（如文本摘要、智能写作）", "常见基础任务：中文分词（如 Jieba）、词性标注（POS）、命名实体识别（NER）、情感倾向性分析、机器翻译与智能客服问答"]}, {"id": "b6-6-2-2-b2", "t": "callout", "imp": "important", "kind": "trap", "title": "中文 NLP 与英文处理的最大差异", "text": "专转本常考考点：英文单词之间自带空格自然分隔，而==中文句子连续书写无空格分割，因此“中文分词”（Word Segmentation）是中文 NLP 的关键预处理第一步==。"}]'::jsonb, '', 'B6-6.2.2 自然语言处理的概念。 自然语言处理（NLP）概念与任务 自然语言处理（Natural Language Processing，NLP）：研究计算机如何理解、解析、生成人类自然语言的学科，被誉为“人工智能皇冠上的明珠” 核心分为两大分支：自然语言理解（NLU）（如句法分析、意图识别）与自然语言生成（NLG）（如文本摘要、智能写作） 常见基础任务：中文分词（如 Jieba）、词性标注（POS）、命名实体识别（NER）、情感倾向性分析、机器翻译与智能客服问答 中文 NLP 与英文处理的最大差异 专转本常考考点：英文单词之间自带空格自然分隔，而中文句子连续书写无空格分割，因此“中文分词”（Word Segmentation）是中文 NLP 的关键预处理第一步。', '{"pdf": "理论复习.pdf", "pages": [130]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B6-6.2.3 计算机视觉的概念。 (node_id=222)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (222, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (222, 1, '[{"id": "b6-6-2-3-b1", "t": "list", "imp": "core", "title": "计算机视觉（CV）概念与核心任务", "items": ["==计算机视觉（Computer Vision，CV）==：用摄影机和计算机代替人眼对目标进行识别、跟踪和测量，并进一步做图形图像处理，使计算机能“看懂”客观世界", "核心基础任务四阶演进：==图像分类（Image Classification）== -> ==目标检测（Object Detection，带边界框）== -> ==语义分割（Semantic Segmentation，像素级类别标注）== -> 实例分割（区分不同个体）", "典型应用：人脸识别闸机、自动驾驶车辆车道线识别、安防人体姿态估计、医学影像病灶筛查"]}, {"id": "b6-6-2-3-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "计算机视觉的基石算法", "text": "在深度学习时代，==卷积神经网络（CNN）及其变体（如 ResNet、YOLO）==是计算机视觉领域应用最广泛的基础算法架构。"}]'::jsonb, '', 'B6-6.2.3 计算机视觉的概念。 计算机视觉（CV）概念与核心任务 计算机视觉（Computer Vision，CV）：用摄影机和计算机代替人眼对目标进行识别、跟踪和测量，并进一步做图形图像处理，使计算机能“看懂”客观世界 核心基础任务四阶演进：图像分类（Image Classification） -> 目标检测（Object Detection，带边界框） -> 语义分割（Semantic Segmentation，像素级类别标注） -> 实例分割（区分不同个体） 典型应用：人脸识别闸机、自动驾驶车辆车道线识别、安防人体姿态估计、医学影像病灶筛查 计算机视觉的基石算法 在深度学习时代，卷积神经网络（CNN）及其变体（如 ResNet、YOLO）是计算机视觉领域应用最广泛的基础算法架构。', '{"pdf": "理论复习.pdf", "pages": [130, 131]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B6-6.2.4 数据挖掘的概念，常用算法。 (node_id=223)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (223, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (223, 1, '[{"id": "b6-6-2-4-b1", "t": "table", "imp": "core", "title": "机器学习与数据挖掘主要算法分类", "headers": ["学习范式", "数据特点", "常用经典算法", "典型应用"], "rows": [["==监督学习（Supervised）==", "数据**带有标注标签（Label）**", "==决策树（ID3/C4.5）、支持向量机（SVM）、朴素贝叶斯、K 近邻（KNN）、逻辑回归==", "垃圾邮件分类、房价预测、信用评分"], ["==无监督学习（Unsupervised）==", "数据**无预先标注标签**", "==K-Means 均值聚类、层次聚类、PCA 主成分分析、Apriori 关联规则==", "客户细分群体画像、购物篮关联挖掘"], ["强化学习（Reinforcement）", "通过**环境奖惩反馈（Reward）**试错学习", "Q-Learning, Policy Gradient, DQN", "下棋博弈、机器人运动控制、自动驾驶决策"]]}, {"id": "b6-6-2-4-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "KNN vs K-Means 高频混淆辨析", "text": "==KNN（K-Nearest Neighbors，K近邻）属于监督学习的“分类算法”==（需要已知训练样本标签）；而==K-Means（K均值）属于无监督学习的“聚类算法”==（不需要任何先验标签）。"}]'::jsonb, '', 'B6-6.2.4 数据挖掘的概念，常用算法。 机器学习与数据挖掘主要算法分类 学习范式 数据特点 常用经典算法 典型应用 监督学习（Supervised） 数据带有标注标签（Label） 决策树（ID3/C4.5）、支持向量机（SVM）、朴素贝叶斯、K 近邻（KNN）、逻辑回归 垃圾邮件分类、房价预测、信用评分 无监督学习（Unsupervised） 数据无预先标注标签 K-Means 均值聚类、层次聚类、PCA 主成分分析、Apriori 关联规则 客户细分群体画像、购物篮关联挖掘 强化学习（Reinforcement） 通过环境奖惩反馈（Reward）试错学习 Q-Learning, Policy Gradient, DQN 下棋博弈、机器人运动控制、自动驾驶决策 KNN vs K-Means 高频混淆辨析 KNN（K-Nearest Neighbors，K近邻）属于监督学习的“分类算法”（需要已知训练样本标签）；而K-Means（K均值）属于无监督学习的“聚类算法”（不需要任何先验标签）。', '{"pdf": "理论复习.pdf", "pages": [131]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

