INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (226, 1, '[{"id": "b6-6-3-2-b1", "t": "table", "imp": "core", "title": "人工智能垂直领域典型应用场景", "headers": ["应用领域", "核心技术方案", "代表性功能实例"], "rows": [["智能家居", "语音交互、环境感知、物联联动", "智能音箱语音控制、扫地机器人激光雷达路径规划、智能恒温空调"], ["智能交通", "车路协同、CV 车辆识别", "违章自动抓拍、ETC 无感通行、无人驾驶高精地图导航"], ["智能制造", "机器视觉质检、智能装配机器人", "芯片晶圆表面瑕疵毫秒级检测、汽车工业机器人精准焊接"], ["智慧医疗", "医学图像分割辅助诊断", "肺结节 CT 智能辅助筛查、病历自然语言结构化录入"], ["智慧金融", "风控反洗钱、量化投资、OCR 识别", "远程身份证人脸核身、银行流水异常洗钱监测、智能客服"], ["智慧教育", "自适应学习系统、OCR 批改", "英语口语智能评分、作业错题精准诊断与个性化题库推送"]]}, {"id": "b6-6-3-2-b2", "t": "callout", "imp": "normal", "kind": "tip", "title": "应用考情总结", "text": "各类垂直领域的核心均体现了“==感知智能（听、看、说）到认知智能（理解、思考、决策）==”的深度融合与赋能。"}]'::jsonb, '', 'B6-6.3.2 人工智能在智能家居、智能交通、智能制造、智慧医疗、智慧金融、智慧教育等领域应用。 人工智能垂直领域典型应用场景 应用领域 核心技术方案 代表性功能实例 智能家居 语音交互、环境感知、物联联动 智能音箱语音控制、扫地机器人激光雷达路径规划、智能恒温空调 智能交通 车路协同、CV 车辆识别 违章自动抓拍、ETC 无感通行、无人驾驶高精地图导航 智能制造 机器视觉质检、智能装配机器人 芯片晶圆表面瑕疵毫秒级检测、汽车工业机器人精准焊接 智慧医疗 医学图像分割辅助诊断 肺结节 CT 智能辅助筛查、病历自然语言结构化录入 智慧金融 风控反洗钱、量化投资、OCR 识别 远程身份证人脸核身、银行流水异常洗钱监测、智能客服 智慧教育 自适应学习系统、OCR 批改 英语口语智能评分、作业错题精准诊断与个性化题库推送 应用考情总结 各类垂直领域的核心均体现了“感知智能（听、看、说）到认知智能（理解、思考、决策）”的深度融合与赋能。', '{"pdf": "理论复习.pdf", "pages": [132]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B6-6.3.3 人工智能未来发展趋势。 (node_id=227)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (227, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (227, 1, '[{"id": "b6-6-3-3-b1", "t": "list", "imp": "core", "title": "人工智能核心未来趋势与治理挑战", "items": ["==大模型与通用人工智能（AGI）演进==：从单一感知智能迈向多模态认知智能（语言、视觉、声音融合）", "==端侧轻量化与边缘 AI==：通过量化、剪枝与知识蒸馏，使 AI 模型在手机、穿戴等边缘终端高效本地推理", "==可解释性 AI（XAI）与具身智能（Embodied AI）==：提升算法透明度，人形机器人与物理世界具身交互", "科技伦理与安全治理：算法偏见治理、数据隐私保护、深度伪造（Deepfake）防范与法律合规框架"]}, {"id": "b6-6-3-3-b2", "t": "callout", "imp": "core", "kind": "warn", "title": "科技伦理与法律红线", "text": "==生成式人工智能服务管理暂行办法==规定，AI 生成内容应当体现社会主义核心价值观，不得含有虚假信息，并对生成的图片、视频等内容进行显式水印标识。"}]'::jsonb, '', 'B6-6.3.3 人工智能未来发展趋势。 人工智能核心未来趋势与治理挑战 大模型与通用人工智能（AGI）演进：从单一感知智能迈向多模态认知智能（语言、视觉、声音融合） 端侧轻量化与边缘 AI：通过量化、剪枝与知识蒸馏，使 AI 模型在手机、穿戴等边缘终端高效本地推理 可解释性 AI（XAI）与具身智能（Embodied AI）：提升算法透明度，人形机器人与物理世界具身交互 科技伦理与安全治理：算法偏见治理、数据隐私保护、深度伪造（Deepfake）防范与法律合规框架 科技伦理与法律红线 生成式人工智能服务管理暂行办法规定，AI 生成内容应当体现社会主义核心价值观，不得含有虚假信息，并对生成的图片、视频等内容进行显式水印标识。', '{"pdf": "理论复习.pdf", "pages": [132]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B7-7.1.1 区块链基本概念。 (node_id=229)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (229, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (229, 1, '[{"id": "b7-7-1-1-b1", "t": "p", "imp": "core", "title": "区块链的本质定义", "text": "==区块链（Blockchain）==是由密码学技术连接的一串包含交易信息的“数据块”（Block），在本质上是一个==去中心化、共享的分布式账本（Distributed Ledger）==。它通过网络中多个节点共同维护和验证数据，无需依赖第三方中心化权威机构信用背书即可建立信任关系。最早由==中本聪（Satoshi Nakamoto）==在 2008 年发表的《比特币：一种点对点的电子现金系统》白皮书中提出。"}, {"id": "b7-7-1-1-b2", "t": "table", "imp": "core", "title": "区块结构剖析（区块头 + 区块体）", "headers": ["区块组成部分", "包含的核心字段", "功能与作用"], "rows": [["==区块头（Block Header）==", "==前一区块哈希值（PrevHash）==、时间戳、难度目标、==随机数（Nonce）==、==默克尔根（Merkle Root）==", "通过存储前一区块哈希建立单向链式结构，任何历史篡改都会导致后续链断裂"], ["==区块体（Block Body）==", "本区块记录的所有交易记录列表（Transactions）", "实际的业务账目数据，通过哈希运算组织成默克尔树"]]}]'::jsonb, '', 'B7-7.1.1 区块链基本概念。 区块链的本质定义 区块链（Blockchain）是由密码学技术连接的一串包含交易信息的“数据块”（Block），在本质上是一个去中心化、共享的分布式账本（Distributed Ledger）。它通过网络中多个节点共同维护和验证数据，无需依赖第三方中心化权威机构信用背书即可建立信任关系。最早由中本聪（Satoshi Nakamoto）在 2008 年发表的《比特币：一种点对点的电子现金系统》白皮书中提出。 区块结构剖析（区块头 + 区块体） 区块组成部分 包含的核心字段 功能与作用 区块头（Block Header） 前一区块哈希值（PrevHash）、时间戳、难度目标、随机数（Nonce）、默克尔根（Merkle Root） 通过存储前一区块哈希建立单向链式结构，任何历史篡改都会导致后续链断裂 区块体（Block Body） 本区块记录的所有交易记录列表（Transactions） 实际的业务账目数据，通过哈希运算组织成默克尔树', '{"pdf": "理论复习.pdf", "pages": [133, 134]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B7-7.1.2 区块链技术基础、技术特点及价值。 (node_id=230)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (230, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (230, 1, '[{"id": "b7-7-1-2-b1", "t": "table", "imp": "core", "title": "区块链四大核心技术支撑与技术特点", "headers": ["核心支撑技术", "对应的区块链四大核心特点", "技术原理与实现说明"], "rows": [["==P2P 对等网络==", "==去中心化（Decentralized）==", "节点地位均等，无单点故障（SPOF），数据全网多副本冗余备份"], ["==密码学技术==", "==不可篡改与防伪造==", "利用 ==SHA-256 等哈希函数、非对称加密（公钥/私钥）、数字签名==保障安全"], ["==共识机制==", "==集体维护与多方信任==", "通过确定算法（如 PoW、PoS、PBFT）在全网无中心信任环境下达成账本一致性"], ["==智能合约==", "==可编程性与自动执行==", "运行在区块链分布式虚拟机上的代码，条件满足即==自动强制执行==，不可单方毁约"]]}, {"id": "b7-7-1-2-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "非对称加密核心常考", "text": "专转本必考非对称加密原理：==公钥公开用于加密，私钥自己保管用于解密；私钥签名证明身份，公钥用于验证签名==。比特币地址由公钥经过哈希与编码派生。"}]'::jsonb, '', 'B7-7.1.2 区块链技术基础、技术特点及价值。 区块链四大核心技术支撑与技术特点 核心支撑技术 对应的区块链四大核心特点 技术原理与实现说明 P2P 对等网络 去中心化（Decentralized） 节点地位均等，无单点故障（SPOF），数据全网多副本冗余备份 密码学技术 不可篡改与防伪造 利用 SHA-256 等哈希函数、非对称加密（公钥/私钥）、数字签名保障安全 共识机制 集体维护与多方信任 通过确定算法（如 PoW、PoS、PBFT）在全网无中心信任环境下达成账本一致性 智能合约 可编程性与自动执行 运行在区块链分布式虚拟机上的代码，条件满足即自动强制执行，不可单方毁约 非对称加密核心常考 专转本必考非对称加密原理：公钥公开用于加密，私钥自己保管用于解密；私钥签名证明身份，公钥用于验证签名。比特币地址由公钥经过哈希与编码派生。', '{"pdf": "理论复习.pdf", "pages": [134, 135]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

