INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (231, 1, '[{"id": "b7-7-1-3-b1", "t": "table", "imp": "core", "title": "区块链技术演进的三大阶段（区块链 1.0 ~ 3.0）", "headers": ["演进代际", "定位与主要内涵", "代表性项目", "主要特征与技术突破"], "rows": [["==区块链 1.0==", "==数字货币阶段==", "==比特币（Bitcoin）==", "实现去中心化的点对点电子现金转账，账本简单转账记录"], ["==区块链 2.0==", "==可编程金融阶段==", "==以太坊（Ethereum）==", "引入==智能合约（Smart Contract）==与以太坊虚拟机（EVM），支持图灵完备编程与 DApp"], ["==区块链 3.0==", "==更广泛的社会治理与泛行业阶段==", "超级账本 Fabric、联盟链", "超越金融领域，赋能实体经济供应链、政务管理、司法存证、跨链互通"]]}, {"id": "b7-7-1-3-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "区块链代际划分核心考点", "text": "专转本选择题常考标志物：==区块链 1.0 的标志是比特币，区块链 2.0 的核心里程碑是智能合约（以太坊）==。"}]'::jsonb, '', 'B7-7.1.3 区块链的发展历程。 区块链技术演进的三大阶段（区块链 1.0 ~ 3.0） 演进代际 定位与主要内涵 代表性项目 主要特征与技术突破 区块链 1.0 数字货币阶段 比特币（Bitcoin） 实现去中心化的点对点电子现金转账，账本简单转账记录 区块链 2.0 可编程金融阶段 以太坊（Ethereum） 引入智能合约（Smart Contract）与以太坊虚拟机（EVM），支持图灵完备编程与 DApp 区块链 3.0 更广泛的社会治理与泛行业阶段 超级账本 Fabric、联盟链 超越金融领域，赋能实体经济供应链、政务管理、司法存证、跨链互通 区块链代际划分核心考点 专转本选择题常考标志物：区块链 1.0 的标志是比特币，区块链 2.0 的核心里程碑是智能合约（以太坊）。', '{"pdf": "理论复习.pdf", "pages": [134, 135]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B7-7.2.1 以太坊技术框架。 (node_id=233)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (233, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (233, 1, '[{"id": "b7-7-2-1-b1", "t": "table", "imp": "core", "title": "以太坊（Ethereum）技术架构核心要素", "headers": ["核心组成要素", "技术说明与功能", "考点关注"], "rows": [["==智能合约语言==", "以 ==Solidity== 语言为代表的图灵完备高级编程语言", "编写部署至以太坊的合约代码"], ["==以太坊虚拟机（EVM）==", "全球去中心化虚拟机，所有节点均运行 EVM 执行字节码", "保证智能合约在所有节点产生完全相同的执行状态"], ["==Gas 机制（汽油费）==", "衡量执行合约操作需消耗的计算资源度量单位", "防止恶意无限死循环攻击（Gas 耗尽直接中断回滚）"], ["代币与账户体系", "原生代币 Ether（ETH）；包含外部账户（EOA）与合约账户（CA）", "状态转换系统，每次交易更新全网状态树（Merkle Patricia Tree）"]]}, {"id": "b7-7-2-1-b2", "t": "callout", "imp": "core", "kind": "trap", "title": "以太坊图灵完备性", "text": "比特币的脚本系统故意设计为**非图灵完备（不支持循环语句以防止死循环）**；而==以太坊引入图灵完备虚拟机（EVM），通过 Gas 燃料机制限制执行步数来防范死循环攻击==。"}]'::jsonb, '', 'B7-7.2.1 以太坊技术框架。 以太坊（Ethereum）技术架构核心要素 核心组成要素 技术说明与功能 考点关注 智能合约语言 以 Solidity 语言为代表的图灵完备高级编程语言 编写部署至以太坊的合约代码 以太坊虚拟机（EVM） 全球去中心化虚拟机，所有节点均运行 EVM 执行字节码 保证智能合约在所有节点产生完全相同的执行状态 Gas 机制（汽油费） 衡量执行合约操作需消耗的计算资源度量单位 防止恶意无限死循环攻击（Gas 耗尽直接中断回滚） 代币与账户体系 原生代币 Ether（ETH）；包含外部账户（EOA）与合约账户（CA） 状态转换系统，每次交易更新全网状态树（Merkle Patricia Tree） 以太坊图灵完备性 比特币的脚本系统故意设计为非图灵完备（不支持循环语句以防止死循环）；而以太坊引入图灵完备虚拟机（EVM），通过 Gas 燃料机制限制执行步数来防范死循环攻击。', '{"pdf": "理论复习.pdf", "pages": [135, 136]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- B7-7.2.2 超级账本 Fabric 技术框架。 (node_id=234)
INSERT INTO kb_entry (node_id, status, published_rev, updated_at) VALUES (234, 'published', 1, now()) ON CONFLICT (node_id) DO UPDATE SET status = 'published', published_rev = 1, updated_at = now();
INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (234, 1, '[{"id": "b7-7-2-2-b1", "t": "table", "imp": "core", "title": "以太坊（公有链） vs 超级账本 Fabric（联盟链）对比", "headers": ["对比维度", "以太坊（公有链代表）", "超级账本 Hyperledger Fabric（联盟链代表）"], "rows": [["==准入机制==", "==完全开放==，任何人自由加入或退出", "==严格权限准入==，需成员管理服务（MSP/CA）身份颁发"], ["==智能合约==", "Smart Contract（Solidity，运行于 EVM）", "==链码（Chaincode）==，支持 Go、Java、Node.js 编写"], ["==共识机制==", "早期 PoW / 现 PoS，依赖代币激励", "==无原生代币==，采用 Raft、Kafka、PBFT 等高性能确定性共识"], ["==通道与隐私==", "全网公开透明可查", "==多通道（Channel）隔离==，不同业务通道间数据互不可见"], ["性能 TPS", "15~30 TPS（较低）", "数千 TPS（高吞吐、毫秒级低延迟，适合企业级商务）"]]}, {"id": "b7-7-2-2-b2", "t": "list", "imp": "important", "title": "Fabric 核心节点角色划分", "items": ["==背书节点（Endorser）==：执行链码模拟运行并对执行结果签名背书", "==排序节点（Orderer）==：接收背书交易进行全局排序并打包生成区块，不关心交易具体内容", "==记账节点（Committer）==：验证区块中交易的合法性并写入本地分布式账本"]}]'::jsonb, '', 'B7-7.2.2 超级账本 Fabric 技术框架。 以太坊（公有链） vs 超级账本 Fabric（联盟链）对比 对比维度 以太坊（公有链代表） 超级账本 Hyperledger Fabric（联盟链代表） 准入机制 完全开放，任何人自由加入或退出 严格权限准入，需成员管理服务（MSP/CA）身份颁发 智能合约 Smart Contract（Solidity，运行于 EVM） 链码（Chaincode），支持 Go、Java、Node.js 编写 共识机制 早期 PoW / 现 PoS，依赖代币激励 无原生代币，采用 Raft、Kafka、PBFT 等高性能确定性共识 通道与隐私 全网公开透明可查 多通道（Channel）隔离，不同业务通道间数据互不可见 性能 TPS 15~30 TPS（较低） 数千 TPS（高吞吐、毫秒级低延迟，适合企业级商务） Fabric 核心节点角色划分 背书节点（Endorser）：执行链码模拟运行并对执行结果签名背书 排序节点（Orderer）：接收背书交易进行全局排序并打包生成区块，不关心交易具体内容 记账节点（Committer）：验证区块中交易的合法性并写入本地分布式账本', '{"pdf": "理论复习.pdf", "pages": [136, 137]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

