INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (236, 1, '[{"id": "b7-7-3-1-b1", "t": "table", "imp": "core", "title": "区块链在各行业典型应用与核心价值", "headers": ["应用领域", "解决的核心痛点", "代表性应用场景"], "rows": [["==金融与跨境支付==", "跨行清算周期长（T+1/T+2）、中转成本高", "跨境实时点对点清算、数字人民币（e-CNY）结算体系"], ["==供应链金融与溯源==", "信息不对称、核心企业信用难穿透多级供应商", "应收账款凭证多级流转、高档白酒/生鲜原产地防伪追溯"], ["==司法存证与版权保护==", "电子证据易被篡改灭失、版权侵权取证难", "互联网法院司法存证区块链、原创图片/文章上链确权"], ["==慈善公益与教育就业==", "善款流向不透明、学历证书伪造", "善款流向全流程公示不可篡改、学历学位上链防伪验真"]]}, {"id": "b7-7-3-1-b2", "t": "callout", "imp": "important", "kind": "tip", "title": "区块链应用考点总结", "text": "专转本常考：凡是涉及==“多方参与、缺乏中心权威、数据要求防篡改可追溯、自动履约”==的场景，均为区块链最佳适用场景。"}]'::jsonb, '', 'B7-7.3.1 区块链在金融、供应链、保险、慈善、教育就业等行业的应用。 区块链在各行业典型应用与核心价值 应用领域 解决的核心痛点 代表性应用场景 金融与跨境支付 跨行清算周期长（T+1/T+2）、中转成本高 跨境实时点对点清算、数字人民币（e-CNY）结算体系 供应链金融与溯源 信息不对称、核心企业信用难穿透多级供应商 应收账款凭证多级流转、高档白酒/生鲜原产地防伪追溯 司法存证与版权保护 电子证据易被篡改灭失、版权侵权取证难 互联网法院司法存证区块链、原创图片/文章上链确权 慈善公益与教育就业 善款流向不透明、学历证书伪造 善款流向全流程公示不可篡改、学历学位上链防伪验真 区块链应用考点总结 专转本常考：凡是涉及“多方参与、缺乏中心权威、数据要求防篡改可追溯、自动履约”的场景，均为区块链最佳适用场景。', '{"pdf": "理论复习.pdf", "pages": [137, 138]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

