INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref) VALUES (237, 1, '[{"id": "b7-7-3-2-b1", "t": "list", "imp": "core", "title": "区块链核心技术发展趋势", "items": ["==跨链技术（Cross-Chain）==：打破区块链数据孤岛，实现异构链之间的资产与信息互通（如侧链、中继链、哈希锁定）", "==扩容技术与性能突破==：Layer 2 二层网络（Rollups、状态通道）、分片技术（Sharding）显著提升 TPS", "==隐私计算与区块链结合==：零知识证明（ZKP）、同态加密在保证账本可验证的同时保护交易敏感信息", "与 Web 3.0 和实体经济深度融合：去中心化身份（DID）、数据要素可信流通基础设施构建"]}, {"id": "b7-7-3-2-b2", "t": "callout", "imp": "core", "kind": "warn", "title": "区块链监管与合规", "text": "国家网信办推行==《区块链信息服务管理规定》==，要求境内区块链服务提供者必须完成网信办备案，严格防范以虚拟货币名义进行非法集资与传销。"}]'::jsonb, '', 'B7-7.3.2 区块链发展趋势。 区块链核心技术发展趋势 跨链技术（Cross-Chain）：打破区块链数据孤岛，实现异构链之间的资产与信息互通（如侧链、中继链、哈希锁定） 扩容技术与性能突破：Layer 2 二层网络（Rollups、状态通道）、分片技术（Sharding）显著提升 TPS 隐私计算与区块链结合：零知识证明（ZKP）、同态加密在保证账本可验证的同时保护交易敏感信息 与 Web 3.0 和实体经济深度融合：去中心化身份（DID）、数据要素可信流通基础设施构建 区块链监管与合规 国家网信办推行《区块链信息服务管理规定》，要求境内区块链服务提供者必须完成网信办备案，严格防范以虚拟货币名义进行非法集资与传销。', '{"pdf": "理论复习.pdf", "pages": [138]}'::jsonb) ON CONFLICT (node_id, rev_no) DO UPDATE SET blocks = EXCLUDED.blocks, search_text = EXCLUDED.search_text, source_ref = EXCLUDED.source_ref;

-- 2. 先利用关联题投票（majority vote）将已有对应题目的知识点精确下沉到三级节点
WITH q_vote AS (
  SELECT k.id AS kp_id,
         q.chapter_id AS target_l3,
         ROW_NUMBER() OVER (PARTITION BY k.id ORDER BY count(*) DESC, q.chapter_id) AS rn
    FROM t_knowledge_point k
    JOIN t_question_kp x ON x.kp_id = k.id
    JOIN t_question q ON q.id = x.question_id AND NOT q.deleted
    JOIN t_chapter ch ON ch.id = q.chapter_id AND ch.level = 3
   WHERE NOT k.deleted
     AND k.node_id IN (SELECT id FROM t_chapter WHERE (subject_id = 4 AND level = 2) OR id = 36)
   GROUP BY k.id, q.chapter_id
)
UPDATE t_knowledge_point k
   SET node_id = v.target_l3
  FROM q_vote v
 WHERE k.id = v.kp_id AND v.rn = 1;

-- 3. 对 A2-2.1（node_id=65）中挂错的 Office/多媒体操作知识点专项迁移下沉
UPDATE t_knowledge_point k
   SET node_id = CASE
     -- Word/文档排版相关 -> 119 (A4-4.1.4 文本编辑处理与展现) 或 116 (A4-4.1.1)
     WHEN k.title ~* 'Word|段落|页眉|页脚|字体|样式|文档|分栏|标尺|制表位|首字下沉|查找.*替换' THEN 119
     -- 表格/单元格/Excel -> 119 (A4-4.1.4)
     WHEN k.title ~* 'Excel|工作表|工作簿|单元格|行高|列宽|填充柄|筛选|排序|图表|数据透视|公式|函数|VLOOKUP|SUM|AVERAGE' THEN 119
     -- PowerPoint/幻灯片 -> 119 (A4-4.1.4) 或 136 (A4-4.4.5)
     WHEN k.title ~* 'PowerPoint|幻灯片|演示文稿|母版|放映|动作设置|切换' THEN 119
     -- 多媒体/图片/音频 -> 125 (A4-4.2.5) / 129 (A4-4.3.2)
     WHEN k.title ~* '图片|剪贴画|艺术字|SmartArt|音效' THEN 125
     -- Windows 操作管理 -> 311 (S5-1) / 72 (A2-2.2.4)
     WHEN k.title ~* 'Windows|控制面板|快捷键|任务栏|开始菜单' THEN 72
     -- 软件分类 -> 67 (A2-2.1.2)
     WHEN k.title ~* '分类|系统软件|应用软件|中间件|支撑|工具|商业|免费|开源|共享' THEN 67
     -- 默认归入 66 (A2-2.1.1 软件的定义)
     ELSE 66
   END
 WHERE NOT k.deleted AND k.node_id = 65;

