         ELSE 72
       END
     ELSE k.node_id
   END
 WHERE NOT k.deleted
   AND (k.node_id IN (SELECT id FROM t_chapter WHERE subject_id = 4 AND level = 2) OR k.node_id = 36);

-- 5. 安全保底兜底：若仍有任何未删除知识点直挂在 L2 节点，自动分配给该 L2 下的第一个三级子节点
UPDATE t_knowledge_point k
   SET node_id = (
     SELECT min(c3.id)
       FROM t_chapter c3
      WHERE c3.parent_id = k.node_id
        AND c3.level = 3
   )
 WHERE NOT k.deleted
   AND k.node_id IN (SELECT id FROM t_chapter WHERE subject_id = 4 AND level = 2);

-- 6. 更新站点公告，告知全站 232 个三级考点讲义已 100% 精编发布上线
UPDATE site_announcement
   SET version = '2026-11-02-6',
       updated_at = now(),
       history_json = history_json || '[{"date": "11-02 22:00", "text": "全站考纲 232 个三级考点（技能 S1~S6 77个 + 理论 155个）精编讲义已全量 100% 结构化发布上线，全量知识点完成精细化下沉！"}]'::jsonb
 WHERE id = 1;

COMMIT;
